"use client";

/**
 * Interaction pattern adapted from Beautiful UI (MIT, Shane Levine).
 * Forge rewrite: fg-* tokens. Not a replacement for DataTable.
 */

import { useState } from "react";
import { cn } from "../../../lib/utils";
import { SurfaceCard } from "../surface-card";

export type AgentDiffColumn = {
  key: string;
  label: string;
};

export type AgentDiffChange = "keep" | "remove" | "add";

export type AgentDiffRow = {
  id: string;
  cells: Record<string, string>;
  change: AgentDiffChange;
};

export function AgentDiffTable({
  title,
  locale = "zh",
  columns,
  rows,
  applyLabel,
  appliedLabel = locale === "zh" ? "项变更已应用" : "edits applied",
  onApply,
  toggleHint = locale === "zh" ? "点击变更行可取消或重新选择" : "Click changed rows to toggle",
  formatApplyLabel,
  formatAppliedLabel,
  className = "",
}: {
  title: string;
  locale?: "zh" | "en";
  columns: AgentDiffColumn[];
  rows: AgentDiffRow[];
  applyLabel?: string;
  appliedLabel?: string;
  onApply?: (includedIds: string[]) => void;
  toggleHint?: string;
  /** Format the complete button text, including count and pluralization. */
  formatApplyLabel?: (count: number) => string;
  /** Format the complete completion text, including count. */
  formatAppliedLabel?: (count: number) => string;
  className?: string;
}) {
  const [included, setIncluded] = useState<Record<string, boolean>>(() =>
    Object.fromEntries(rows.filter((row) => row.change !== "keep").map((row) => [row.id, true])),
  );
  const [applied, setApplied] = useState(false);
  const changed = rows.filter((row) => row.change !== "keep" && included[row.id]);
  const removals = changed.filter((row) => row.change === "remove").length;
  const additions = changed.filter((row) => row.change === "add").length;

  function toggle(id: string) {
    if (applied) return;
    setIncluded((current) => ({ ...current, [id]: !current[id] }));
  }

  return (
    <SurfaceCard
      className={className}
      title={title}
      subtitle={applied ? undefined : toggleHint}
      padding="none"
      footer={
        applied ? (
          <p className="text-sm font-medium text-fg-green-500">
            {formatAppliedLabel ? formatAppliedLabel(changed.length) : `${changed.length} ${appliedLabel}`}
          </p>
        ) : (
          <div className="flex items-center justify-between gap-3">
            <p className="text-xs text-fg-grey-500">
              {locale === "zh" ? `删除 ${removals} 项 · 新增 ${additions} 项` : `${removals} ${removals === 1 ? "removal" : "removals"} · ${additions} ${additions === 1 ? "addition" : "additions"}`}
            </p>
            <button
              type="button"
              disabled={changed.length === 0}
              onClick={() => {
                setApplied(true);
                onApply?.(changed.map((row) => row.id));
              }}
              className="inline-flex items-center justify-center rounded-full bg-accent px-3 py-2.5 text-xs font-bold leading-4 tracking-fg text-accent-foreground disabled:cursor-not-allowed disabled:opacity-60"
            >
              {formatApplyLabel ? formatApplyLabel(changed.length) : (applyLabel ? applyLabel.replace("changes", `${changed.length} ${changed.length === 1 ? "change" : "changes"}`) : locale === "zh" ? `应用 ${changed.length} 项变更` : `Apply ${changed.length} ${changed.length === 1 ? "change" : "changes"}`)}
            </button>
          </div>
        )
      }
    >
      <table className="w-full text-left text-sm">
        <thead>
          <tr className="border-b border-fg-grey-200 text-xs text-fg-grey-500">
            {columns.map((column) => (
              <th key={column.key} className="px-4 py-2.5 font-semibold">
                {column.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const active = row.change !== "keep" && included[row.id];
            const interactive = row.change !== "keep" && !applied;
            return (
              <tr
                key={row.id}
                onClick={interactive ? () => toggle(row.id) : undefined}
                className={cn(
                  "border-b border-fg-grey-100 last:border-0",
                  interactive && "cursor-pointer",
                  active && row.change === "remove" && "bg-fg-red-50",
                  active && row.change === "add" && "bg-fg-green-50",
                  row.change !== "keep" && !active && "opacity-50",
                )}
              >
                {columns.map((column) => (
                  <td key={column.key} className="px-4 py-2.5 text-fg-black">
                    {row.cells[column.key]}
                  </td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </SurfaceCard>
  );
}

