            followUps={["冬季哪些口味最畅销", "对比意式冰淇淋与软冰淇淋的利润率"]}
            onFollowUp={(text) => setFollowUp(text)}
          />
          {followUp && <p className="text-sm text-fg-grey-700">已选择： {followUp}</p>}
        </SubSection>
