                id: "think",
                kind: "think",
                label: "思考中",
                chip: "正在安排生产计划…",
                detail: [
                  { text: "周末需求带动开心果口味销量，优先安排生产。" },
                  { text: "按当前批次产能，晚间还有两个冷冻作业时段。" },
