## AppLayoutProps (type)

```ts
export interface AppLayoutProps {
  /** Motion for the navigation shell and its nested menu branches. */
  motion?: MotionPreference;
  mode?: AppLayoutMode;
  profilePosition?: AppLayoutProfilePosition;
  accent?: AppLayoutAccentColor;
  children: ReactNode;
