"use client";

import { useEffect, useLayoutEffect, useRef, useState, type FormEvent, type KeyboardEvent, type ReactNode } from "react";
import { MagniferLinear, QuitFullScreenLinear, SidebarMinimalisticLinear } from "../icons";
import { AskAiCompactComposerContext } from "./ask-ai-composer-context";
import { AskAiIcon } from "./ask-ai-icon";
import { cn } from "../lib/utils";
import { Button } from "../components/ui/button";
import { PlusIcon } from "../components/ui/plain-icons";
import type { AccentColor } from "../components/ui/accent-utils";
import type { AskAiMessage, AskAiSessionItem } from "./ask-ai-types";

export const ASK_AI_FS_LAYER_ATTR = "data-ask-ai-fs-layer";
/** Session rail width: 16rem token, not a hardcoded px value. */
export const ASK_AI_FULLSCREEN_RAIL_WIDTH = "16rem";

function AskAiFullscreenComposer({
  draft,
  onDraftChange,
  pending,
  disabled,
  placeholder,
  tall,
  onSubmit,
}: {
  draft: string;
  onDraftChange: (value: string) => void;
  pending: boolean;
  disabled?: boolean;
  placeholder: string;
  tall?: boolean;
  onSubmit: () => void;
}) {
  const inputRef = useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    input.style.height = "auto";
    input.style.height = `${Math.min(input.scrollHeight, 192)}px`;
  }, [draft, tall]);

  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      onSubmit();
    }
  }

  return (
    <form
      data-ask-ai-fs-composer
      className="w-full"
      onSubmit={(event: FormEvent) => {
        event.preventDefault();
        onSubmit();
      }}
    >
      <div
        data-ask-ai-fs-composer-box
        className={cn(
          "flex gap-2.5 border border-fg-grey-200 bg-background",
          tall ? "flex-col rounded-2xl px-3.5 pb-2.5 pt-3.5 shadow-md" : "items-end rounded-[28px] px-3.5 py-2 shadow-sm",
        )}
      >
        <textarea
          ref={inputRef}
          aria-label="向 AI 提问"
          placeholder={placeholder}
          value={draft}
          disabled={pending || disabled}
          rows={tall ? 3 : 1}
          className={cn(
            "w-full resize-none border-0 bg-transparent text-base leading-6 text-foreground outline-none placeholder:text-fg-grey-400",
            tall ? "min-h-16" : "min-h-6 min-w-0 flex-1 py-1.5",
          )}
          onChange={(event) => onDraftChange(event.target.value)}
          onKeyDown={onKeyDown}
        />
        <div className="flex items-center justify-end">
          <button type="submit" disabled={pending || disabled || !draft.trim()} className="rounded-full bg-accent px-3 py-2.5 text-xs font-bold leading-4 tracking-fg text-accent-foreground disabled:cursor-not-allowed disabled:opacity-60">
            发送
          </button>
        </div>
      </div>
    </form>
  );
}

function AskAiDefaultTranscript({
  label,
  messages,
  pending,
  error,
  failedQuestion,
  onRetry,
}: {
  label: string;
  messages: AskAiMessage[];
  pending: boolean;
  error: string | null;
  failedQuestion: string | null;
  onRetry: () => void;
}) {
  return (
    <>
      <div role="log" aria-label="对话记录" aria-live="polite" className="flex flex-col gap-5">
        {messages.map((message, index) => (
          <div key={index} className={cn("flex flex-col gap-1.5", message.role === "user" && "items-end")}>
            <span className="text-xs text-fg-grey-500">{message.role === "user" ? "你" : label}</span>
            <p className={cn("max-w-full whitespace-pre-wrap break-words text-sm leading-6", message.role === "user" && "rounded-2xl bg-fg-grey-100 px-4 py-3")}>
              {message.content}
            </p>
            {message.role === "assistant" && message.links && (
              <div className="flex flex-wrap gap-2">
                {message.links.map((link, linkIndex) => (
                  <a
                    key={linkIndex}
                    href={link.href}
                    className="max-w-full break-words rounded-xl border border-fg-grey-200 px-3 py-2 text-sm font-semibold text-fg-grey-700 hover:bg-fg-grey-100 focus-visible:outline-2 focus-visible:outline-fg-grey-500"
                  >
                    {link.label}
                  </a>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
      {pending && <p role="status" className="mt-5 text-sm text-fg-grey-500">正在思考…</p>}
      {error && (
        <div className="mt-5 flex items-center gap-3">
          <p role="alert" className="text-sm text-fg-red">{error}</p>
          <Button size="sm" variant="tertiary" color="grey" onClick={onRetry} disabled={!failedQuestion || pending}>
            重试
          </Button>
        </div>
      )}
    </>
  );
}

export function AskAiFullscreenLayer({
  color,
  label,
  railLabel = "Ask",
  landingTitle = "今天想做什么？",
  placeholder,
  brand,
  session,
  messages,
  composer,
  sessions = [],
  currentSessionId,
  onNewSession,
  onSelectSession,
  searchQuery,
  onSearchQueryChange,
  suggestions = [],
  draft,
  onDraftChange,
  pending,
  disabled,
  error,
  failedQuestion,
  conversation,
  hasConversation,
  onSubmit,
  onRetry,
  onSuggestion,
  onExit,
}: {
  color?: AccentColor;
  label: string;
  railLabel?: string;
  landingTitle?: string;
  placeholder: string;
  brand?: ReactNode;
  session?: ReactNode;
  messages?: ReactNode;
  composer?: ReactNode;
  sessions?: AskAiSessionItem[];
  currentSessionId?: string;
  onNewSession?: () => void;
  onSelectSession?: (id: string) => void;
  searchQuery?: string;
  onSearchQueryChange?: (query: string) => void;
  suggestions?: string[];
  draft: string;
  onDraftChange: (value: string) => void;
  pending: boolean;
  disabled?: boolean;
  error: string | null;
  failedQuestion: string | null;
  conversation: AskAiMessage[];
  hasConversation?: boolean;
  onSubmit: () => void;
  onRetry: () => void;
  onSuggestion: (question: string) => void;
  onExit: () => void;
}) {
  const [railOpen, setRailOpen] = useState(() => typeof window === "undefined" || !window.matchMedia?.("(max-width: 767px)").matches);
  useEffect(() => {
    const breakpoint = window.matchMedia?.("(max-width: 767px)");
    if (!breakpoint) return;
    const syncRail = () => setRailOpen(!breakpoint.matches);
    breakpoint.addEventListener("change", syncRail);
    return () => breakpoint.removeEventListener("change", syncRail);
  }, []);
  const searchControlled = searchQuery !== undefined;
  const [internalSearch, setInternalSearch] = useState("");
  const railQuery = searchControlled ? searchQuery : internalSearch;
  const inConversation = hasConversation ?? conversation.length > 0;
  const scrollRef = useRef<HTMLDivElement>(null);
  const transcriptRef = useRef<HTMLDivElement>(null);
  const composerRef = useRef<HTMLDivElement>(null);
  const followingRef = useRef(true);
  const [awayFromLatest, setAwayFromLatest] = useState(false);

  function measureComposer() {
    const height = composerRef.current?.getBoundingClientRect().height ?? 0;
    const clearance = `${Math.ceil(height) + 20}px`;
    if (transcriptRef.current) transcriptRef.current.style.paddingBottom = clearance;
    if (scrollRef.current) scrollRef.current.style.scrollPaddingBottom = clearance;
  }

  function scrollToLatest() {
    const host = scrollRef.current;
    if (!host) return;
    host.scrollTop = host.scrollHeight;
    followingRef.current = true;
    setAwayFromLatest(false);
  }

  function onTranscriptScroll() {
    const host = scrollRef.current;
    if (!host) return;
    const nearBottom = host.scrollHeight - host.scrollTop - host.clientHeight <= 48;
    followingRef.current = nearBottom;
    setAwayFromLatest(!nearBottom);
  }

  // Session changes start at the latest reply; updates within a session respect
  // the reader's position. Observe both content growth and composer/viewport resize.
  useLayoutEffect(() => {
    followingRef.current = true;
    measureComposer();
    scrollToLatest();
  }, [currentSessionId, inConversation]);
  useLayoutEffect(() => {
    measureComposer();
    if (followingRef.current) scrollToLatest();
  });
  useEffect(() => {
    const host = scrollRef.current;
    const transcript = transcriptRef.current;
    if (!host || !transcript || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      measureComposer();
      if (followingRef.current) scrollToLatest();
      else onTranscriptScroll();
    });
    observer.observe(host);
    observer.observe(transcript);
    if (composerRef.current) observer.observe(composerRef.current);
    return () => observer.disconnect();
  }, [inConversation]);

  const defaultComposer = (
    <AskAiFullscreenComposer
      draft={draft}
      onDraftChange={onDraftChange}
      pending={pending}
      disabled={disabled}
      placeholder={placeholder}
      tall={!inConversation}
      onSubmit={onSubmit}
    />
  );

  function setRailQuery(next: string) {
    if (!searchControlled) setInternalSearch(next);
    onSearchQueryChange?.(next);
  }

  return (
    <div
      {...{ [ASK_AI_FS_LAYER_ATTR]: "" }}
      data-accent={color}
      role="dialog"
      aria-modal="true"
      aria-label={`${label} 全屏`}
      className="pointer-events-auto fixed inset-0 z-50 flex bg-background"
    >
      {railOpen ? (
        <aside
          data-ask-ai-fs-rail
          aria-label="会话栏"
          className="max-md:absolute max-md:inset-y-0 max-md:left-0 max-md:z-20 max-md:shadow-lg flex min-h-0 shrink-0 flex-col border-r border-fg-grey-200 bg-background px-3 py-4"
          style={{ width: ASK_AI_FULLSCREEN_RAIL_WIDTH }}
        >
          <div className="px-2.5 pb-4 pt-0.5">
            {brand ?? (
              <div className="inline-flex items-center gap-2 text-base font-semibold text-fg-black">
                <AskAiIcon />
                {railLabel}
              </div>
            )}
          </div>
          {session ?? (
            <>
              <button
                type="button"
                data-ask-ai-fs-new
                className="flex w-full items-center gap-2 rounded-lg bg-transparent px-2.5 py-2 text-left text-sm font-medium leading-5 text-fg-grey-700 hover:bg-fg-grey-50 focus-visible:outline-2 focus-visible:outline-fg-grey-500"
                onClick={onNewSession}
              >
                <PlusIcon size={16} />
                新建对话
              </button>
              <div data-ask-ai-fs-rail-search className="mb-5 mt-1">
                <label className="flex items-center gap-2 rounded-lg border border-fg-grey-200 bg-background px-2.5 py-1.5 text-fg-grey-500">
                  <MagniferLinear size={16} />
                  <input
                    type="search"
                    value={railQuery}
                    placeholder="搜索"
                    aria-label="搜索历史"
                    className="w-full bg-transparent text-sm leading-5 text-foreground outline-none placeholder:text-fg-grey-400"
                    onChange={(event) => setRailQuery(event.target.value)}
                  />
                </label>
              </div>
              <div className="forge-ask-ai-fs-scroll min-h-0 flex-1 overflow-y-auto px-0.5">
                {sessions.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    data-ask-ai-fs-hist={item.id}
                    className={cn(
                      "block w-full truncate rounded-lg px-2.5 py-2.5 text-left text-sm leading-6 hover:bg-fg-grey-50 focus-visible:outline-2 focus-visible:outline-fg-grey-500",
                      currentSessionId === item.id ? "bg-accent-soft font-medium text-accent" : "text-fg-grey-700",
                    )}
                    onClick={() => onSelectSession?.(item.id)}
                  >
                    {item.title}
                  </button>
                ))}
                {sessions.length === 0 ? (
                  <p className="px-2.5 py-4 text-center text-sm text-fg-grey-500">暂无最近对话</p>
                ) : null}
              </div>
            </>
          )}
        </aside>
      ) : null}

      <div data-ask-ai-fs-main className="forge-ask-ai-fs-main relative flex min-h-0 min-w-0 flex-1 flex-col bg-background">
        <div className="absolute right-4 top-3 z-10 flex items-center gap-1">
          <button
            type="button"
            title={railOpen ? "收起会话栏" : "展开会话栏"}
            aria-label={railOpen ? "收起会话栏" : "展开会话栏"}
            data-ask-ai-fs-rail-toggle
            className="inline-flex size-9 items-center justify-center rounded-lg text-fg-grey-500 hover:bg-fg-grey-50 hover:text-foreground focus-visible:outline-2 focus-visible:outline-fg-grey-500"
            onClick={() => setRailOpen((open) => !open)}
          >
            <SidebarMinimalisticLinear size={18} />
          </button>
          <button
            type="button"
            title="退出全屏"
            aria-label="退出全屏"
            data-ask-ai-exit-fullscreen
            className="inline-flex size-9 items-center justify-center rounded-lg text-fg-grey-500 hover:bg-fg-grey-100 hover:text-foreground focus-visible:outline-2 focus-visible:outline-fg-grey-500"
            onClick={onExit}
          >
            <QuitFullScreenLinear size={18} />
          </button>
        </div>

        {inConversation ? (
          <div data-ask-ai-fs-chat className="relative flex min-h-0 min-w-0 flex-1 flex-col">
            <div data-ask-ai-fs-scroll ref={scrollRef} onScroll={onTranscriptScroll}
              tabIndex={0} role="region" aria-label="对话滚动区域"
              className="forge-ask-ai-fs-scroll min-h-0 flex-1 overflow-y-auto overscroll-contain [overflow-anchor:none] focus-visible:outline-2 focus-visible:outline-fg-grey-300">
              <div data-ask-ai-fs-messages ref={transcriptRef} className="forge-ask-ai-fs-transcript mx-auto w-full min-w-0 px-6 pb-5 pt-14">
                {messages ?? (
                  <AskAiDefaultTranscript
                    label={label}
                    messages={conversation}
                    pending={pending}
                    error={error}
                    failedQuestion={failedQuestion}
                    onRetry={onRetry}
                  />
                )}
              </div>
            </div>
            <div data-ask-ai-fs-composer-region ref={composerRef} className="pointer-events-none absolute inset-x-0 bottom-0 px-4 md:px-6"
              style={{ paddingBottom: "max(1rem, env(safe-area-inset-bottom))" }}>
              {awayFromLatest && (
                <div className="pointer-events-auto absolute inset-x-0 bottom-full flex justify-center pb-2">
                  <Button size="sm" variant="secondary" color="grey" onClick={scrollToLatest}>回到最新</Button>
                </div>
              )}
              <div className="forge-ask-ai-fs-content forge-ask-ai-fs-floating-composer pointer-events-auto mx-auto w-full">
                <AskAiCompactComposerContext value={true}>{composer ?? defaultComposer}</AskAiCompactComposerContext>
              </div>
            </div>
          </div>
        ) : (
          <div data-ask-ai-fs-landing className="flex min-h-0 flex-1 flex-col items-center overflow-y-auto px-8 pb-10 pt-16">
            <div data-ask-ai-fs-landing-inner className="forge-ask-ai-fs-content flex w-full flex-col items-center">
              <h2 className="mb-7 text-center text-3xl font-semibold leading-tight tracking-fg text-fg-black">
                {landingTitle}
              </h2>
              {composer ?? defaultComposer}
              {messages ? null : (
                <div data-ask-ai-fs-suggest className="mt-4 flex w-full flex-wrap justify-center gap-2.5">
                  {suggestions.map((question, index) => (
                    <button
                      key={`${index}-${question}`}
                      type="button"
                      disabled={pending || disabled}
                      data-ask-ai-fs-suggest-chip
                      className="rounded-xl border border-fg-grey-200 bg-background px-3.5 py-3 text-left text-sm text-fg-black hover:bg-fg-grey-50 focus-visible:outline-2 focus-visible:outline-fg-grey-500 disabled:opacity-50"
                      onClick={() => onSuggestion(question)}
                    >
                      {question}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

