      )}
    >
      {visible.map((h, i) => {
        const isActive = h === maxBar;
        const bg = isColored
          ? (isActive ? "bg-white" : "bg-white/30")
          : (isActive ? barActive[color] : barInactive[color]);
        const height = isWide
          ? Math.max(8, Math.round((h / maxBar) * wideMax))
          : h;
        return (
          <div
            key={i}
            className={cn("rounded-lg", isWide ? "w-2" : "w-[5px]", bg)}
            style={{ height: `${height}px` }}
          />
        );
      })}
    </div>
  );
}

