"use client";

import type { MotionPreference } from "../../../lib/motion";
import { useReducedMotion } from "../../../internal/motion";
import { cn } from "../../../lib/utils";
import { ChartTooltip } from "./chart-tooltip";
import { LABEL_TEXT, LABEL_TEXT_ACTIVE, resolveColor } from "./chart-utils";
import { accentColors, type AccentColor } from "../accent-utils";

interface BarHorizontalChartDataItem {
  value: number;
  label?: string;
}

interface BarHorizontalChartProps {
  data: BarHorizontalChartDataItem[];
  domain?: [number, number];
  target?: number;
  targetLabel?: string;
  ranges?: { to: number; color?: string }[];
  motion?: MotionPreference;
  accent?: AccentColor;
  activeIndex?: number;
  color?: string;
  inactiveColor?: string;
  barWidth?: "thin" | "wide";
  showLabels?: boolean;
  showTooltip?: boolean;
  tooltipValue?: string;
  tooltipTrend?: "up" | "down";
}

export function BarHorizontalChart({
  data,
  domain, target, targetLabel, ranges = [], motion = "auto",
  accent = "blue",
  activeIndex,
  color,
  inactiveColor,
  barWidth = "thin",
  showLabels = false,
  showTooltip = false,
  tooltipValue,
  tooltipTrend,
}: BarHorizontalChartProps) {
  const reduced = useReducedMotion(motion);
  const theme = accentColors[accent];
  const activeColor = color ?? theme.bg;
  const resolvedInactiveColor = inactiveColor ?? activeColor;
  const minValue = domain?.[0] ?? 0;
  const maxValue = domain?.[1] ?? Math.max(...data.map((d) => d.value), 1);
  const percent = (value: number) => Math.max(0, Math.min(100, (value - minValue) / (maxValue - minValue || 1) * 100));

  return (
    <div className="flex w-full flex-col gap-2">
      {data.map((item, i) => {
        const isActive = i === activeIndex;
        const widthPct = percent(item.value);
        const barColor = isActive ? activeColor : resolvedInactiveColor;

        return (
          <div key={i} className="relative flex items-center gap-2">
            {showLabels && item.label && (
              <span
                className={cn("w-10 shrink-0 text-right", isActive ? LABEL_TEXT_ACTIVE : LABEL_TEXT)}
                style={isActive ? { color: resolveColor(activeColor) } : undefined}
              >
                {item.label}
              </span>
            )}

            <div
              className={cn(
                "relative flex flex-1 items-center",
                isActive && "rounded-r-lg",
              )}
            >
              {ranges.map((range, index) => <div key={index} aria-hidden className="absolute inset-y-0" style={{ left: `${index ? percent(ranges[index - 1].to) : 0}%`, width: `${percent(range.to) - (index ? percent(ranges[index - 1].to) : 0)}%`, background: resolveColor(range.color ?? "bg-fg-grey-200") }} />)}
              {target !== undefined && <span data-chart-target={target} role="img" aria-label={targetLabel ?? `目标 ${target}`} className="absolute -bottom-2 -top-2 z-10 w-0.5 bg-fg-red" style={{ left: `${percent(target)}%`, transition: reduced ? "none" : "left 350ms ease" }} />}
              {isActive && (
                <div className={cn(
                  "pointer-events-none absolute inset-0 rounded-lg bg-gradient-to-l from-transparent",
                  accent === "purple" ? "to-fg-violet/10" : accent === "blue" ? "to-fg-blue/10" : "to-fg-black/10",
                )} />
              )}

              <div
                className={cn(
                  barColor,
                  barWidth === "thin"
                    ? "h-2 rounded-full"
                    : "h-8 rounded-lg",
                )}
                style={{ width: `${widthPct}%`, position: "relative", transition: reduced ? "none" : "width 450ms cubic-bezier(.2,.8,.2,1)" }}
              />

              {isActive && showTooltip && tooltipValue && (
                <div
                  className="absolute -top-10 z-10 -translate-x-1/2"
                  style={{ left: `${widthPct}%` }}
                >
                  <ChartTooltip
                    items={[
                      { color: activeColor, value: tooltipValue, trend: tooltipTrend },
                    ]}
                  />
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { cn } from "../../../lib/utils";
import { ChartTooltip } from "./chart-tooltip";
import { LABEL_TEXT, LABEL_TEXT_ACTIVE, resolveColor } from "./chart-utils";
import { accentColors, type AccentColor } from "../accent-utils";

interface BarUpsideDownChartDataItem {
  upperValue: number;
  lowerValue: number;
  label?: string;
}

interface BarUpsideDownChartProps {
  data: BarUpsideDownChartDataItem[];
  accent?: AccentColor;
  activeIndex?: number;
  /** Upper bar color override. Defaults to accent.bg. */
  upperColor?: string;
  /** Lower bar color override. Defaults to accent.ramp[2] (mid-light shade). */
  lowerColor?: string;
  barWidth?: "thin" | "wide";
  showLabels?: boolean;
  showTooltip?: boolean;
  tooltipUpperValue?: string;
  tooltipLowerValue?: string;
  tooltipTrend?: "up" | "down";
  height?: string;
}

export function BarUpsideDownChart({
  data,
  accent = "blue",
  activeIndex,
  upperColor,
  lowerColor,
  barWidth = "thin",
  showLabels = false,
  showTooltip = false,
  tooltipUpperValue,
  tooltipLowerValue,
  tooltipTrend,
  height = "h-36",
}: BarUpsideDownChartProps) {
  const theme = accentColors[accent];
  const resolvedUpper = upperColor ?? theme.bg;
  const resolvedLower = lowerColor ?? theme.ramp[2];
  const maxUpper = Math.max(...data.map((d) => d.upperValue), 1);
  const maxLower = Math.max(...data.map((d) => d.lowerValue), 1);
  const maxValue = Math.max(maxUpper, maxLower);

  const barClasses =
    barWidth === "thin" ? "w-2 rounded-full" : "w-8 rounded-lg";

  return (
    <div className={cn("inline-flex w-full items-start", height)}>
      {data.map((item, i) => {
        const isActive = i === activeIndex;
        const upperPct = (item.upperValue / maxValue) * 100;
        const lowerPct = (item.lowerValue / maxValue) * 100;

        return (
          <div
            key={i}
            className={cn(
              "relative flex flex-1 flex-col items-center justify-start",
              height,
            )}
          >
            {isActive && (
              <div className={cn(
                "pointer-events-none absolute inset-0 rounded-b-lg bg-gradient-to-b to-transparent",
                accent === "purple" ? "from-fg-violet/10" : accent === "blue" ? "from-fg-blue/10" : "from-fg-black/10",
              )} />
            )}

            <div className="flex flex-1 flex-col items-center justify-center gap-1">
              <div className={cn(resolvedUpper, barClasses)} style={{ height: `${upperPct}%` }} />
              <div className={cn(resolvedLower, barClasses)} style={{ height: `${lowerPct}%` }} />
            </div>

            {showLabels && item.label && (
              <span
                className={cn("mt-2", isActive ? LABEL_TEXT_ACTIVE : LABEL_TEXT)}
                style={isActive ? { color: resolveColor(resolvedUpper) } : undefined}
              >
                {item.label}
              </span>
            )}

            {isActive && showTooltip && (tooltipUpperValue || tooltipLowerValue) && (
              <div className="absolute -bottom-14 z-10">
                <ChartTooltip
                  items={[
                    ...(tooltipUpperValue
                      ? [{ color: resolvedUpper, value: tooltipUpperValue, trend: tooltipTrend }]
                      : []),
                    ...(tooltipLowerValue
                      ? [{ color: resolvedLower, value: tooltipLowerValue }]
                      : []),
                  ]}
                />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import { cn } from "../../lib/utils";

