  className?: string;
  ariaLabel?: string;
}) {
  return (
    <nav aria-label={ariaLabel} className={cn("inline-flex justify-start items-center gap-2", className)}>
      {items.map((item, index) => {
        const isLast = index === items.length - 1;

        return (
