"use client";

import { useRef } from "react";
import type { MotionPreference } from "../../lib/motion";
import { useMovingIndicator } from "../../internal/motion";

import { cn } from "../../lib/utils";

// ============================================================
// ButtonGroup - 分段控制器
// color: purple, blue, black
// shape: rounded, pill
// ============================================================

const activeItemColors = {
  purple: "bg-fg-violet-100 text-fg-violet",
  blue: "bg-fg-blue-100 text-fg-blue",
  black: "bg-fg-grey-200 text-fg-black",
} as const;

export type ButtonGroupColor = keyof typeof activeItemColors;
export type ButtonGroupShape = "rounded" | "pill";

export interface ButtonGroupItem {
  label: string;
}

export function ButtonGroup({
  items,
  activeIndex = 0,
  color = "blue",
  shape = "rounded",
  onChange,
  className,
  motion = "auto",
  ariaLabel = "选项组",
}: {
  items: ButtonGroupItem[];
  activeIndex?: number;
  color?: ButtonGroupColor;
  shape?: ButtonGroupShape;
  onChange?: (index: number) => void;
  className?: string;
  motion?: MotionPreference;
  ariaLabel?: string;
}) {
  const isPill = shape === "pill";

  const rootRef = useRef<HTMLDivElement>(null);
  const indicator = useMovingIndicator(rootRef, "[aria-pressed='true']", activeIndex);
  return (
    <div
      ref={rootRef}
      data-motion={motion}
      role="group"
      aria-label={ariaLabel}
      className={cn(
        "relative isolate p-1 bg-white outline outline-1 outline-offset-[-1px] outline-fg-grey-200 inline-flex",
        isPill ? "rounded-full" : "rounded-xl",
        className
      )}
    >
      <span aria-hidden ref={indicator} className={cn("forge-moving-indicator forge-pill-indicator", activeItemColors[color], isPill ? "rounded-full" : "rounded-lg")} />
      {items.map((item, index) => (
        <button
          key={index}
          type="button"
          aria-pressed={index === activeIndex}
          onClick={() => onChange?.(index)}
          onKeyDown={event => {
            const next = event.key === "ArrowRight" || event.key === "ArrowDown" ? (index + 1) % items.length : event.key === "ArrowLeft" || event.key === "ArrowUp" ? (index - 1 + items.length) % items.length : event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : -1;
            if (next < 0) return;
            event.preventDefault(); onChange?.(next); rootRef.current?.querySelectorAll<HTMLButtonElement>("button")[next]?.focus();
          }}
          className={cn(
            "relative z-[1] px-4 py-2 text-sm leading-5 cursor-pointer whitespace-nowrap",
            isPill ? "rounded-full" : "rounded-lg",
            index === activeIndex
              ? `${activeItemColors[color].split(" ").filter((value) => !value.startsWith("bg-")).join(" ")} font-bold`
              : "text-fg-grey-700 font-semibold"
          )}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}

