  iconChipBg: string;
  /** Accent text/stroke for icon chip */
  iconChipText: string;
  /** Avatar border color (should match card bg so stacked avatars
   * have a visual gap in the card's own color) */
  avatarBorder: string;
  /** Decorative glow gradient (bottom-right blob) */
