    iconChipText: "text-white",
    avatarBorder: "border-fg-black",
    glowFrom: "from-fg-cyan-500/0 to-fg-cyan-500/25",
    glowTo: "from-fg-cyan-500/50 to-fg-cyan-500/0",
  },
