      className={cn(
        "w-8 h-8 rounded-full flex items-center justify-center transition-opacity hover:opacity-80 cursor-pointer shrink-0",
        theme.iconChipBg,
        theme.iconChipText,
      )}
    >
      <MenuDotsBold size={16} />
    </button>
  );
}

