  { key: "customer", header: "客户", width: "w-[170px]", render: (r) => <CellTextSubtitle title={r.customer} subtitle={r.email} /> },
  { key: "total", header: "金额", valueKind: "number", width: "w-[120px]", render: (r) => <CellNumber value={r.total} /> },
