        title="数字右对齐"
        description="金额、数量、单价、百分比右对齐，列头同右。工号、订单号、日期是标识，左对齐，列头同左。位数不同，便于对照小数点。"
      >
        <DataTable<AlignSample>
          title="对齐验收"
          subtitle="数字列 valueKind=number，标识列 valueKind=identifier"
          columns={alignColumns}
          rows={alignSamples}
          getRowKey={(row) => row.orderNo}
        />
      </Section>

      {/* ============ DataTable - 6 columns ============ */}
      <Section title="6 Column Table" description="紧凑视图：订单号 / 商品 / 客户 / 金额 / 进度 / 操作。金额与进度右对齐。">
        <DataTable<Order>
          title="近期订单"
          subtitle="近期动态摘要"
          columns={sixColumns}
          rows={orders}
          showCheckbox
          getRowKey={(row) => row.id}
          selectedRowKeys={new Set(["#302011"])}
          showPagination
          currentPage={2}
          totalPages={5}
          paginationLabel="Showing 1-5 from 25"
        />
      </Section>

      {/* ============ DataTable - 8 columns × 3 colors ============ */}
      <Section title="8 Column Table" description="扩展视图：加入 date / payment / status。3 色主题铺开。">
        <div className="flex flex-col gap-6">
          {dataTableColors.map((c) => (
            <DataTable<Order>
              key={c}
              title={`Order History (color="${c}")`}
              subtitle="最近 30 天的全部订单"
              columns={eightColumns}
              rows={orders}
              color={c}
              checkboxColor={c === "black" ? "purple" : c}
              showCheckbox
              getRowKey={(row) => row.id}
              selectedRowKeys={new Set(["#302012", "#302002"])}
              showPagination
              currentPage={1}
              totalPages={5}
              paginationLabel="Showing 1-5 from 25"
            />
          ))}
        </div>
      </Section>

      {/* ============ 6-Column Colors ============ */}
      <Section title="6 Column - Colors" description="purple / blue / black 3 色主题在 6 列模式下的对比。">
        <div className="flex flex-col gap-6">
          {dataTableColors.map((c) => (
            <DataTable<Order>
              key={c}
              title={`color="${c}"`}
              columns={sixColumns}
              rows={orders.slice(0, 3)}
              color={c}
              checkboxColor={c === "black" ? "purple" : c}
              showCheckbox
              getRowKey={(row) => row.id}
              selectedRowKeys={new Set(["#302012"])}
              showPagination
              currentPage={2}
              totalPages={5}
              paginationLabel="Showing 1-3 from 25"
            />
          ))}
        </div>
      </Section>

      {/* ============ FullWidthTable × 3 colors ============ */}
      <Section title="Full Width Table" description="整页 table，自带 row count 选择和分页。3 色全铺。">
        <div className="flex flex-col gap-6">
          {dataTableColors.map((c) => (
            <FullWidthTable<Order>
              key={c}
              title={`All Orders (color="${c}")`}
              subtitle="完整订单列表与明细"
              columns={fullWidthColumns}
              rows={orders}
              color={c}
              checkboxColor={c === "black" ? "purple" : c}
              getRowKey={(row) => row.id}
              selectedRowKeys={new Set(["#302011", "#301901"])}
              showPagination
              currentPage={1}
              totalPages={5}
              showRowCount
              rowCountOptions={[5, 10, 25, 50]}
              currentRowCount={5}
              totalRows={25}
            />
          ))}
        </div>
      </Section>
    </div>
  );
}

