import { type ReactNode } from "react";
import { cn } from "../../../lib/utils";
import { MenuDotsBold } from "../../../icons";
import { resolveCardWidthClass, type CardWidth } from "../card-utils";

type ChartCardSize = "4col" | "6col" | "8col" | "full";

interface ChartCardProps {
  title: string;
  subtitle?: string;
  children: ReactNode;
  footer?: ReactNode;
  action?: ReactNode;
  onMenuClick?: () => void;
  /**
   * @deprecated Figma-size showcase hint only. Never forces fixed width by
   * itself — the 4col/6col/8col fixed-width classes apply only together with an
   * explicit `width="fixed"`.
   */
  size?: ChartCardSize;
  /** Omitted/full fills the parent (dashboard/grid column). Use fixed only for Figma-size showcases. Takes precedence over `size`. */
  width?: CardWidth;
  minHeight?: string;
  className?: string;
}

const fixedWidthClasses: Record<ChartCardSize, string> = {
  "4col": "w-96",
  "6col": "w-[600px]",
  "8col": "w-[800px]",
  full: "w-full",
};

function ThreeDotsVerticalIcon() {
  return <span className="text-fg-black"><MenuDotsBold size={20} /></span>;
}

export function ChartCard({
  title,
  subtitle,
  children,
  footer,
  action,
  onMenuClick,
  size = "full",
  width,
  minHeight = "min-h-80",
  className,
}: ChartCardProps) {
  const widthMode = width ?? "full";

  const actionElement = action ?? (
    <button
      onClick={onMenuClick}
      className="p-3.5 bg-white rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex justify-start items-center gap-2"
    >
      <ThreeDotsVerticalIcon />
    </button>
  );

  return (
    <div
      className={cn(
        "bg-white rounded-card outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex-col justify-start items-start overflow-hidden",
        resolveCardWidthClass(widthMode, fixedWidthClasses[size]),
        minHeight,
        className
      )}
    >
      <div className="self-stretch px-5 pt-5 inline-flex justify-start items-start gap-3">
        <div className="flex-1 inline-flex flex-col justify-start items-start gap-2">
          <div className="self-stretch inline-flex justify-start items-center gap-3">
            <span className="text-fg-black text-sm font-semibold leading-5 tracking-fg">
              {title}
            </span>
          </div>
          {subtitle && (
            <span className="self-stretch text-fg-grey-700 text-xs font-medium leading-4.5 tracking-fg">
              {subtitle}
            </span>
          )}
        </div>
        {actionElement}
      </div>
      <div className="self-stretch flex-1 p-5 flex flex-col justify-start items-center gap-5">
        {children}
        {footer}
      </div>
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { ArrowRightUpLinear } from "../../../icons";

export type ChartTrend = "up" | "down";

export type GroupedBarPoint = {
  label: string;
  values: number[];
};

export type ChartMetricSeries = {
  label: string;
  colorClass: string;
  value?: string;
  trend?: ChartTrend;
  trendValue?: string;
};

export type GroupedBarTooltipItem = {
  label: string;
  value: string;
  colorClass: string;
  trend?: ChartTrend;
};

const defaultYAxis = ["$1.2k", "$1k", "$800", "$600", "$400", "$200", "0"];

function maxValue(points: GroupedBarPoint[]) {
  return Math.max(...points.flatMap((point) => point.values), 1);
}

function TrendArrow({ trend }: { trend?: ChartTrend }) {
  if (!trend) return null;
  return (
    <span
      className={
        trend === "up"
          ? "inline-block size-0 border-x-[4px] border-b-[6px] border-x-transparent border-b-fg-green"
          : "inline-block size-0 border-x-[4px] border-t-[6px] border-x-transparent border-t-fg-red"
      }
    />
  );
}

export function ChartHeader({
  title,
  subtitle,
  tabs = [],
  activeTab,
  defaultTab,
  onTabChange,
  action,
}: {
  title: string;
  subtitle?: string;
  tabs?: string[];
  activeTab?: string;
  defaultTab?: string;
  onTabChange?: (tab: string) => void;
  action?: ReactNode;
}) {
  const [selected, setSelected] = useState(defaultTab ?? tabs[0]);
  const current = activeTab ?? selected;
  return (
    <div className="flex items-start justify-between gap-4">
      <div className="min-w-0">
        <h3 className="text-sm font-semibold leading-5 text-fg-black">{title}</h3>
        {subtitle && <p className="text-xs leading-4 text-fg-grey-700">{subtitle}</p>}
      </div>
      {action ?? (tabs.length > 0 && (
        <div className="inline-flex shrink-0 items-center gap-1 rounded-full bg-fg-grey-100 p-1 text-xs">
          {tabs.map((tab) => (
            <button
              key={tab}
              type="button"
              aria-pressed={tab === current}
              onClick={() => { setSelected(tab); onTabChange?.(tab); }}
              className={
                tab === current
                  ? "rounded-full bg-white px-3 py-1.5 font-semibold text-fg-violet shadow-subtle"
                  : "rounded-full px-3 py-1.5 font-medium text-fg-grey-500"
              }
            >
              {tab}
            </button>
          ))}
        </div>
      ))}
    </div>
  );
}

export function ChartMetricRow({ series }: { series: ChartMetricSeries[] }) {
  return (
    <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
      {series.map((item) => (
        <div key={item.label} className="flex items-center gap-2">
          <span className={`flex size-8 items-center justify-center rounded-full text-white ${item.colorClass}`}>
            <ArrowRightUpLinear size={16} />
          </span>
          <div className="min-w-0">
            <div className="text-xs font-medium leading-4 text-fg-grey-500">{item.label}</div>
            <div className="flex items-center gap-2">
              <span className="text-base font-semibold leading-6 text-fg-black">{item.value}</span>
              {item.trend && (
                <span className={item.trend === "up" ? "text-xs font-bold text-fg-green-500" : "text-xs font-bold text-fg-red"}>
                  {item.trendValue ?? "10%"} <TrendArrow trend={item.trend} />
                </span>
              )}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export function GroupedBarChart({
  data,
  series,
  activeIndex = 6,
  tooltipItems,
  yAxisLabels = defaultYAxis,
  heightClass = "h-56",
}: {
  data: GroupedBarPoint[];
  series: ChartMetricSeries[];
  activeIndex?: number;
  tooltipItems?: GroupedBarTooltipItem[];
  yAxisLabels?: string[];
  heightClass?: string;
}) {
  const max = maxValue(data);

  return (
    <div className={`relative grid grid-cols-[44px_1fr] gap-3 ${heightClass}`}>
      <div className="flex h-full flex-col justify-between py-2 text-xs font-medium text-fg-grey-700">
        {yAxisLabels.map((label) => (
          <span key={label}>{label}</span>
        ))}
      </div>

      <div className="relative flex h-full items-end gap-3 overflow-hidden pt-8">
        <div className="absolute inset-x-0 top-8 bottom-9 flex flex-col justify-between">
          {yAxisLabels.map((label) => (
            <span key={label} className="border-t border-dashed border-fg-grey-200" />
          ))}
        </div>

        {tooltipItems && (
          <div className="absolute left-1/2 top-3 z-20 min-w-36 -translate-x-1/2 rounded-xl bg-fg-black px-3 py-2 text-white shadow-elevated">
            <div className="flex flex-col gap-2">
              {tooltipItems.map((item) => (
                <div key={item.label} className="flex items-center justify-between gap-3 text-xs">
                  <span className="flex items-center gap-2 text-white/70">
                    <span className={`size-2.5 rounded-full ${item.colorClass}`} />
                    {item.label}
                  </span>
                  <span className="font-semibold">
                    {item.value} <TrendArrow trend={item.trend} />
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {data.map((point, pointIndex) => (
          <div key={point.label} className="relative z-10 flex h-full flex-1 flex-col justify-end gap-3">
            {pointIndex === activeIndex && (
              <span className="absolute inset-y-8 left-1/2 w-12 -translate-x-1/2 bg-fg-violet-50" />
            )}
            <div className="relative z-10 flex h-[calc(100%-34px)] items-end justify-center gap-2">
              {point.values.map((value, seriesIndex) => (
                <span
                  key={`${point.label}-${series[seriesIndex]?.label ?? seriesIndex}`}
                  className={`w-3 rounded-full ${series[seriesIndex]?.colorClass ?? "bg-fg-violet"}`}
                  style={{ height: `${Math.max(8, (value / max) * 100)}%` }}
                />
              ))}
            </div>
            <div className={pointIndex === activeIndex ? "relative z-10 text-center text-sm font-semibold text-fg-violet" : "relative z-10 text-center text-sm font-medium text-fg-grey-700"}>
              {point.label}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export function DivergingBarChart({
  data,
  upperColor = "bg-fg-blue",
  lowerColor = "bg-fg-red",
  activeIndex = 6,
  tooltipUpperValue = "$680",
  tooltipLowerValue = "$280",
  heightClass = "h-56",
  upperLabel = "Income",
  lowerLabel = "Expenses",
}: {
  upperLabel?: string;
  lowerLabel?: string;
  data: { label: string; upperValue: number; lowerValue: number }[];
  upperColor?: string;
  lowerColor?: string;
  activeIndex?: number;
  tooltipUpperValue?: string;
  tooltipLowerValue?: string;
  heightClass?: string;
}) {
  const max = Math.max(...data.flatMap((item) => [item.upperValue, item.lowerValue]), 1);

  return (
    <div className={`relative flex items-center gap-3 overflow-hidden ${heightClass}`}>
      <div className="absolute inset-x-0 top-1/2 border-t border-dashed border-fg-grey-200" />
      <div className="absolute inset-x-0 top-6 bottom-8 flex flex-col justify-between">
        {Array.from({ length: 5 }).map((_, index) => (
          <span key={index} className="border-t border-dashed border-fg-grey-100" />
        ))}
      </div>
      <div className="absolute left-1/2 top-6 z-20 min-w-32 -translate-x-1/2 rounded-xl bg-fg-black px-3 py-2 text-white shadow-elevated">
        <div className="flex items-center justify-between gap-3 text-xs">
          <span className="flex items-center gap-2 text-white/70"><span className={`size-2.5 rounded-full ${upperColor}`} />{upperLabel}</span>
          <span className="font-semibold">{tooltipUpperValue}</span>
        </div>
        <div className="mt-1.5 flex items-center justify-between gap-3 text-xs">
          <span className="flex items-center gap-2 text-white/70"><span className={`size-2.5 rounded-full ${lowerColor}`} />{lowerLabel}</span>
          <span className="font-semibold">{tooltipLowerValue}</span>
        </div>
      </div>
      {data.map((item, index) => (
        <div key={item.label} className="relative z-10 flex h-full flex-1 flex-col items-center justify-center">
          {index === activeIndex && <span className="absolute inset-y-6 w-12 bg-fg-violet-50" />}
          <span className={`relative z-10 mb-1 w-3 rounded-full ${upperColor}`} style={{ height: `${Math.max(8, (item.upperValue / max) * 42)}%` }} />
          <span className={`relative z-10 mt-1 w-3 rounded-full ${lowerColor}`} style={{ height: `${Math.max(8, (item.lowerValue / max) * 42)}%` }} />
          <span className={index === activeIndex ? "absolute bottom-0 text-sm font-semibold text-fg-violet" : "absolute bottom-0 text-sm font-medium text-fg-grey-700"}>
            {item.label}
          </span>
        </div>
      ))}
    </div>
  );
}

export type ChartHeaderProps = Parameters<typeof ChartHeader>[0];
export type ChartMetricRowProps = Parameters<typeof ChartMetricRow>[0];
export type GroupedBarChartProps = Parameters<typeof GroupedBarChart>[0];
export type DivergingBarChartProps = Parameters<typeof DivergingBarChart>[0];

