interface ChartStatFooterItem {
  label: string;
  value: string;
  color?: string;
  /** Optional trend text (e.g. "+12%"). If omitted while trendDirection is set, renders arrow only. */
  trend?: string;
  trendDirection?: "up" | "down";
}

interface ChartStatFooterProps {
  items: ChartStatFooterItem[];
  /** When item.color is omitted, derives dot color from this accent's ramp. */
  accent?: AccentColor;
}

export function ChartStatFooter({ items, accent = "blue" }: ChartStatFooterProps) {
  const rampFallback = rampColors(accent, items.length);
  return (
    <div className="self-stretch inline-flex justify-start items-center gap-3">
      {items.map((item, i) => {
        const dotColor = item.color ?? rampFallback[i];
        return (
        <div key={i} className="flex-1 inline-flex flex-col justify-start items-center gap-1">
          <div className="inline-flex justify-center items-center gap-1">
            <div className={cn("w-2.5 h-2.5 rounded-full", dotColor)} />
            <span className="text-fg-grey-700 text-xs font-medium leading-4 tracking-fg">
              {item.label}
            </span>
          </div>
          <div className="inline-flex justify-center items-center gap-1">
            <span className="text-fg-black text-2xl font-semibold leading-8 tracking-fg">
              {item.value}
            </span>
            {item.trendDirection && (
              <span
                className={cn(
                  "inline-flex items-center gap-0.5 text-sm font-bold leading-5 tracking-fg",
                  trendColorClass(item.trendDirection),
                )}
              >
                {item.trend}
                <span>{trendArrow(item.trendDirection)}</span>
              </span>
            )}
          </div>
        </div>
        );
      })}
    </div>
  );
}

import { cn } from "../../../lib/utils";

export interface ChartTooltipItem {
  color: string;
  label?: string;
  value: string;
  trend?: "up" | "down";
}

interface ChartTooltipProps {
  items: ChartTooltipItem[];
  className?: string;
}

export function ChartTooltip({ items, className }: ChartTooltipProps) {
  return (
    <div
      className={cn(
        "rounded-xl bg-fg-black px-4 py-3 shadow-lg",
        className
      )}
    >
      <div className="flex flex-col gap-1.5">
        {items.map((item, i) => (
          <div key={i} className="flex items-center gap-1.5">
            <div
              className={cn("h-2.5 w-2.5 shrink-0 rounded-full", item.color)}
            />
            {item.label && (
              <>
                <span className="text-xs leading-4 tracking-fg text-fg-grey-500">{item.label}</span>
                <span className="text-xs leading-4 tracking-fg text-fg-grey-500">:</span>
              </>
            )}
            <span className="text-xs font-bold leading-4 tracking-fg text-white">{item.value}</span>
            {item.trend && (
              <span
                className={cn(
                  "text-xs",
                  item.trend === "up" ? "text-fg-green-500" : "text-fg-red"
                )}
              >
                {item.trend === "up" ? "↑" : "↓"}
              </span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

