"use client";

/* eslint-disable @next/next/no-img-element */

import { useRef, useState } from "react";
import type { MotionPreference } from "../../lib/motion";
import { useReducedMotion } from "../../internal/motion";
import { ChatReactions, type ChatReaction, type ChatReactionOption } from "../../internal/chat-interactions";
import type { ComposerReply } from "./composer-types";
import { ReplyLinear, ClockCircleLinear, CheckCircleLinear, DangerTriangleLinear, PlayBoldDuotone, DocumentTextLinear, DownloadLinear } from "../../icons";
import { accentColors, type AccentColor } from "./accent-utils";

// Chat-specific color tokens (play button, waveform, file subtitle)
const chatColors: Record<AccentColor, {
  playBtnBg: string;
  playIcon: string;            // explicit Forge icon color
  waveMain: string;            // received primary bars (12)
  waveLightReceived: string;   // received secondary bars (9)
  waveLightSent: string;       // sent secondary bars (9)
  fileSubText: string;         // file size text on sent (colored bg)
  filesPlusBg: string;         // +N tile bg
  filesPlusText: string;       // +N text color
}> = {
  purple: {
    playBtnBg: "bg-fg-violet-100",
    playIcon: "var(--fg-violet)",
    waveMain: "bg-fg-violet",
    waveLightReceived: "bg-fg-violet-300",
    waveLightSent: "bg-fg-violet-400",
    fileSubText: "text-fg-violet-300",
    filesPlusBg: "bg-fg-violet-100",
    filesPlusText: "text-fg-violet",
  },
  blue: {
    playBtnBg: "bg-fg-blue-50",
    playIcon: "var(--fg-blue)",
    waveMain: "bg-fg-blue",
    waveLightReceived: "bg-fg-blue-200",
    waveLightSent: "bg-fg-blue-400",
    fileSubText: "text-fg-blue-300",
    filesPlusBg: "bg-fg-blue-50",
    filesPlusText: "text-fg-blue",
  },
  black: {
    playBtnBg: "bg-fg-grey-200",
    playIcon: "var(--fg-black)",
    waveMain: "bg-fg-black",
    waveLightReceived: "bg-fg-grey-400",
    waveLightSent: "bg-fg-grey-600",
    fileSubText: "text-fg-grey-500",
    filesPlusBg: "bg-fg-grey-200",
    filesPlusText: "text-fg-black",
  },
};

// 21 waveform bar heights (Tailwind h-N classes), per Figma
const WAVE_HEIGHTS = [
  "h-2", "h-5", "h-8", "h-4", "h-2.5", "h-1.5", "h-5", "h-7", "h-3", "h-1.5", "h-7", "h-8",
  "h-5", "h-1.5", "h-3", "h-6", "h-8", "h-5", "h-2.5", "h-4", "h-1",
] as const;

export function ChatBubble({
  type,
  locale = "zh", motion = "auto", reactions = [], reactionOptions = [], onReaction, onReply, replyTo, delivery,
  variant = "text",
  color = "blue",
  content,
  time,
  avatar,
  senderName,
  images,
  extraImageCount,
  fileName,
  fileSize,
  onFileDownload,
  voiceDuration,
  className = "",
}: {
  type: "sent" | "received";
  locale?: "zh" | "en";
  motion?: MotionPreference;
  reactions?: ChatReaction[];
  reactionOptions?: ChatReactionOption[];
  onReaction?: (id: string) => void;
  onReply?: () => void;
  replyTo?: ComposerReply;
  delivery?: "queued" | "sending" | "sent" | "delivered" | "failed";
  variant?: "text" | "voice" | "file" | "image";
  color?: AccentColor;
  content?: string;
  time?: string;
  avatar?: string;
  senderName?: string;
  images?: string[];
  extraImageCount?: number;
  fileName?: string;
  fileSize?: string;
  /** Renders an actionable download button for received file messages. */
  onFileDownload?: () => void;
  voiceDuration?: string;
  className?: string;
}) {
  const drag = useRef<{ x: number; delta: number } | null>(null);
  const [offset, setOffset] = useState(0);
  const [dragging, setDragging] = useState(false);
  const reduced = useReducedMotion(motion);
  const finishDrag = (cancel: boolean) => { const ready = !cancel && (drag.current?.delta ?? 0) >= 60; drag.current = null; setDragging(false); setOffset(0); if (ready) onReply?.(); };
  const deliveryLabel = delivery && (locale === "zh" ? { queued: "等待发送", sending: "发送中", sent: "已发送", delivered: "已送达", failed: "发送失败" } : { queued: "Queued", sending: "Sending", sent: "Sent", delivered: "Delivered", failed: "Failed" })[delivery];
  const isSent = type === "sent";
  const accent = accentColors[color];
  const c = chatColors[color];

  // Per Figma: received bubble misses bottom-left, sent misses bottom-right
  const cornerClass = isSent
    ? "rounded-tl-xl rounded-tr-xl rounded-bl-xl"
    : "rounded-tl-xl rounded-tr-xl rounded-br-xl";

  const bubbleBg = isSent ? accent.bg : "bg-white";
  const bubbleText = isSent ? "text-white" : "text-fg-black";
  const fileSubColor = isSent ? c.fileSubText : "text-fg-grey-700";

  return (
    <div data-motion={reduced ? "none" : motion} data-delivery={delivery} style={{ "--accent": `var(--fg-${color === "purple" ? "violet" : color})` } as import("react").CSSProperties} className={`forge-chat-bubble flex gap-2.5 ${isSent ? "justify-end" : "justify-start"} ${className}`}>
      {!isSent && avatar && (
        <img
          src={avatar}
          alt={senderName ?? ""}
          className="w-8 h-8 rounded-full object-cover shrink-0 mt-1"
        />
      )}

      <div className={`max-w-[70%] flex flex-col gap-1 ${isSent ? "items-end" : "items-start"}`}>
        {!isSent && senderName && (
          <span className="text-xs text-fg-grey-700 font-medium">{senderName}</span>
        )}

        {replyTo && <blockquote className="max-w-full rounded-lg bg-fg-grey-100 px-3 py-2 text-xs text-fg-grey-700"><strong className="font-medium">{replyTo.name}</strong><p className="truncate">{replyTo.content}</p></blockquote>}
        {/* TEXT */}
        {variant === "text" && (
          <div className={`p-3 ${bubbleBg} ${cornerClass} inline-flex justify-start items-start gap-2 overflow-hidden`} style={{ translate: `${offset}px 0`, transition: dragging || reduced ? "none" : "translate 300ms cubic-bezier(.2,.8,.2,1)", touchAction: onReply ? "pan-y" : undefined }}
            onPointerDown={event => { if (!onReply || event.button !== 0) return; setDragging(true); drag.current = { x: event.clientX, delta: 0 }; event.currentTarget.setPointerCapture(event.pointerId); }}
            onPointerMove={event => { if (!drag.current) return; const delta = Math.max(0, event.clientX - drag.current.x); drag.current.delta = delta; setOffset(Math.min(delta, 60) + Math.max(0, delta - 60) * .3); }}
            onPointerUp={() => finishDrag(false)} onPointerCancel={() => finishDrag(true)} onLostPointerCapture={() => finishDrag(true)}>
            <p className={`flex-1 text-sm font-normal leading-5 tracking-fg ${bubbleText}`}>
              {content}
            </p>
          </div>
        )}

        {/* VOICE */}
        {variant === "voice" && (
          <div className={`p-3 ${bubbleBg} ${cornerClass} inline-flex justify-start items-center gap-3 overflow-hidden`}>
            <div className={`p-2.5 ${c.playBtnBg} rounded-full flex justify-center items-center shrink-0`}>
              <PlayBoldDuotone size={20} color={c.playIcon} />
            </div>
            <div className="flex justify-center items-center gap-1.5">
              {WAVE_HEIGHTS.map((h, i) => {
                const isPrimary = i < 12;
                const barColor = isPrimary
                  ? (isSent ? "bg-white" : c.waveMain)
                  : (isSent ? c.waveLightSent : c.waveLightReceived);
                return <div key={i} className={`w-0.5 ${h} ${barColor} rounded-[10px]`} />;
              })}
            </div>
            {voiceDuration && (
              <span className={`text-xs ml-1 ${isSent ? "text-white/80" : "text-fg-grey-500"}`}>
                {voiceDuration}
              </span>
            )}
          </div>
        )}

        {/* FILE */}
        {variant === "file" && (
          <div className={`p-3 ${bubbleBg} ${cornerClass} inline-flex justify-start items-center gap-2 overflow-hidden`}>
            <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${
              isSent ? "bg-white/20" : "bg-fg-grey-100"
            }`}>
              <DocumentTextLinear size={20} color={isSent ? "white" : c.playIcon} />
            </div>
            <div className="inline-flex flex-col justify-center items-start gap-0.5 min-w-0">
              <p className={`text-sm font-semibold leading-5 tracking-fg truncate ${bubbleText}`}>
                {fileName ?? content ?? ""}
              </p>
              {fileSize && (
                <p className={`text-xs font-medium leading-4 tracking-fg ${fileSubColor}`}>
                  {fileSize}
                </p>
              )}
            </div>
            {!isSent && onFileDownload && (
              <button
                type="button"
                aria-label={`${locale === "zh" ? "下载" : "Download"} ${fileName ?? content ?? (locale === "zh" ? "文件" : "file")}`}
                onClick={onFileDownload}
                className="ml-2 shrink-0 opacity-70 hover:opacity-100 transition-opacity"
              >
                <DownloadLinear size={18} color="var(--fg-grey-700)" />
              </button>
            )}
          </div>
        )}

        {/* IMAGE — figma uses 64×64 thumbnails (no bubble bg), with optional +N tile */}
        {variant === "image" && images && images.length > 0 && (
          <div className="inline-flex justify-start items-start gap-3">
            {images.map((src, i) => (
              <img
                key={i}
                src={src}
                alt=""
                className="w-16 h-16 rounded-xl object-cover"
              />
            ))}
            {extraImageCount !== undefined && extraImageCount > 0 && (
              <div className={`w-16 h-16 p-2.5 ${c.filesPlusBg} rounded-xl inline-flex flex-col justify-center items-center gap-2.5 overflow-hidden`}>
                <span className={`text-sm font-semibold leading-5 tracking-fg ${c.filesPlusText}`}>
                  +{extraImageCount}
                </span>
              </div>
            )}
          </div>
        )}

        {onReply && <button type="button" className="inline-flex items-center gap-1 rounded-lg px-1 py-0.5 text-xs text-fg-grey-500 hover:bg-fg-grey-100" onClick={onReply}><ReplyLinear size={14} />{locale === "zh" ? "回复" : "Reply"}</button>}
        {onReaction && <ChatReactions reactions={reactions} options={reactionOptions} onChange={onReaction} locale={locale} motion={motion} />}
        {deliveryLabel && <span role="status" className="inline-flex items-center gap-1 text-xs text-fg-grey-500">{delivery === "queued" || delivery === "sending" ? <ClockCircleLinear size={14} /> : delivery === "failed" ? <DangerTriangleLinear size={14} color="var(--fg-red)" /> : <CheckCircleLinear size={14} />}{deliveryLabel}</span>}
        {time && <span className="text-2xs text-fg-grey-500 px-1">{time}</span>}
      </div>
    </div>
  );
}

export type { ChatReaction, ChatReactionOption } from "../../internal/chat-interactions";

