// ============================================================
// ArtisticIcon - 带渐变/发光装饰的圆形图标容器 (Figma Artistic)
// 固定 w-12 尺寸，两种装饰变体：gradient (双向对角渐变) / orbs (双色发光球)
// ============================================================
const artisticShells = {
  black: "bg-fg-black",
  blue: "bg-fg-blue",
  purple: "bg-fg-violet",
