      </Section>

      {/* ============ Label ============ */}
      <Section title="Label" description="文字标签，7 色 × 3 size × 2 variant。">
        <SubSection title="Variants (blue, md)">
          {labelVariants.map((v) => (
            <Labeled key={v} label={v}>
              <Label color="blue" variant={v} size="md">蓝色</Label>
            </Labeled>
