              <Label color={c} variant="outline" size="md">{c}</Label>
            </Labeled>
          ))}
        </SubSection>

        <SubSection title="Colors (md, solid)">
          {labelColors.map((c) => (
            <Labeled key={c} label={c}>
              <Label color={c} variant="solid" size="md">{c}</Label>
            </Labeled>
          ))}
        </SubSection>
