export function cn(...classes: (string | undefined | null | false)[]) {
  return classes.filter(Boolean).join(" ");
}

"use client";

import { type ReactNode, useState, useRef, useEffect, useId } from "react";
import { cn } from "../../../lib/utils";
import { MagniferLinear, AddCircleLinear } from "../../../icons";
import { formAccents, type FormAccentColor } from "./form-utils";

// ============================================================
// Icon Selector — 3 sub-components from Figma:
// 1. ColorPicker — row of color dots
// 2. IconPicker — grid of icons with color picker popover
// 3. IconSelector — full component: preview circle + popover with search + icon grid
// ============================================================

export type IconSelectorColor = FormAccentColor;

export function filterIconIndexes(
  labels: string[] | undefined,
  query: string,
  iconCount = labels?.length ?? 0,
): number[] {
  const indexes = Array.from({ length: iconCount }, (_, index) => index);
  const normalizedQuery = query.trim().toLocaleLowerCase();
  if (!normalizedQuery || !labels) return indexes;
  return indexes.filter((index) => labels[index]?.toLocaleLowerCase().includes(normalizedQuery));
}

// ── Color Picker ──────────────────────────────────────────

const defaultPalette = [
  "bg-fg-violet",
  "bg-fg-green-500",
  "bg-fg-cyan-500",
  "bg-fg-yellow",
  "bg-fg-red",
  "bg-fg-blue",
  "bg-fg-grey-700",
  "bg-fg-black",
];

export function ColorPicker({
  colors = defaultPalette,
  selectedIndex,
  onChange,
  className,
}: {
  colors?: string[];
  selectedIndex?: number;
  onChange?: (index: number) => void;
  className?: string;
}) {
  return (
    <div className={cn("flex items-center gap-2 flex-wrap", className)}>
      {colors.map((color, i) => {
        const isSelected = i === selectedIndex;
        return (
          <button
            key={i}
            type="button"
            aria-label={`颜色 ${i + 1}`}
            aria-pressed={isSelected}
            onClick={() => onChange?.(i)}
            className={cn(
              "p-0.5 rounded-full flex items-center gap-2 cursor-pointer",
              isSelected && "outline outline-1 outline-offset-[-1px] outline-fg-grey-200",
            )}
          >
            <div className={cn("w-5 h-5 rounded-full relative", color)}>
              {isSelected && (
                <svg className="absolute inset-0 m-auto" width="8" height="6" viewBox="0 0 8 6" fill="none">
                  <path d="M1 3L3 5L7 1" stroke="white" strokeWidth="1.25" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
            </div>
          </button>
        );
      })}
    </div>
  );
}

// ── Icon Picker (grid) ────────────────────────────────────

export function IconPicker({
  icons,
  labels,
  selectedIndex,
  onChange,
  color = "blue",
  className,
}: {
  icons: ReactNode[];
  labels?: string[];
  selectedIndex?: number;
  onChange?: (index: number) => void;
  color?: IconSelectorColor;
  className?: string;
}) {
  const accent = formAccents[color];

  return (
    <div className={cn("flex flex-wrap gap-2 content-start", className)}>
      {icons.map((icon, index) => {
        const isSelected = index === selectedIndex;
        return (
          <button
            key={index}
            type="button"
            aria-label={labels?.[index] ?? `图标 ${index + 1}`}
            aria-pressed={isSelected}
            onClick={() => onChange?.(index)}
            className={cn(
              "p-2 rounded-[10px] flex items-center justify-center cursor-pointer transition-colors",
              isSelected
                ? cn("outline outline-1 outline-offset-[-1px]", accent.outline, accent.text)
                : "text-fg-grey-700 hover:bg-fg-grey-200",
            )}
          >
            <div className="w-6 h-6 flex items-center justify-center">
              {icon}
            </div>
          </button>
        );
      })}
    </div>
  );
}

// ── Icon Selector (full) ──────────────────────────────────

export function IconSelector({
  icons,
  selectedIndex,
  onChange,
  labels,
  label,
  color = "blue",
  searchPlaceholder = "搜索图标...",
  className,
}: {
  icons: ReactNode[];
  selectedIndex?: number;
  onChange?: (index: number) => void;
  /** Searchable accessible names aligned with `icons`. Without labels, search leaves all icons visible. */
  labels?: string[];
  label?: string;
  color?: IconSelectorColor;
  searchPlaceholder?: string;
  className?: string;
}) {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const dialogId = useId();
  const labelId = useId();
  const accent = formAccents[color];

  // Move focus into the popover and support dismissal from the keyboard or pointer.
  useEffect(() => {
    if (!open) return;
    searchInputRef.current?.focus();

    function handleClick(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    function handleEscape(e: KeyboardEvent) {
      if (e.key !== "Escape") return;
      e.preventDefault();
      setOpen(false);
      triggerRef.current?.focus();
    }
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [open]);

  const hasSelection = selectedIndex !== undefined && selectedIndex >= 0;
  const filteredIndexes = filterIconIndexes(labels, search, icons.length);

  return (
    <div className={cn("inline-flex flex-col items-start gap-1", className)} ref={containerRef}>
      {label && (
        <div className="self-stretch flex items-start gap-2">
          <span id={labelId} className="flex-1 text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">{label}</span>
        </div>
      )}
      <div className="self-stretch relative inline-flex items-center gap-3">
        {/* Preview circle */}
        <div
          className={cn(
            "w-16 h-16 p-5 bg-fg-grey-200 rounded-full flex justify-center items-center gap-2 overflow-hidden",
            open && cn("outline outline-1 outline-offset-[-1px]", accent.outline),
          )}
        >
          {hasSelection ? (
            <div className={cn("w-8 h-8 flex items-center justify-center", accent.text)}>
              {icons[selectedIndex!]}
            </div>
          ) : (
            <span className="text-fg-grey-700"><AddCircleLinear size={32} /></span>
          )}
        </div>

        {/* Select / Close button */}
        <button
          ref={triggerRef}
          type="button"
          onClick={() => setOpen(!open)}
          aria-expanded={open}
          aria-haspopup="dialog"
          aria-controls={dialogId}
          className={cn("flex items-start gap-1 cursor-pointer", accent.text)}
        >
          <AddCircleLinear size={20} />
          <span className="text-sm font-bold leading-5 tracking-fg">
            {open ? "关闭" : "选择"}
          </span>
        </button>

        {/* Popover */}
        {open && (
          <div
            id={dialogId}
            role="dialog"
            aria-modal="false"
            aria-labelledby={label ? labelId : undefined}
            aria-label={label ? undefined : "图标选择器"}
            className="absolute left-[76px] top-[50px] w-80 max-w-[calc(100vw-2rem)] z-50 rounded-2xl outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex flex-col overflow-hidden bg-white shadow-[0px_4px_30px_0px_rgba(77,84,100,0.05)]"
          >
            {/* Search */}
            <div className="self-stretch p-4 border-b border-fg-grey-200 flex flex-col gap-2">
              <div className="self-stretch px-4 py-3 bg-white rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 inline-flex items-center gap-1 overflow-hidden">
                <div className="w-6 h-6 flex justify-center items-center text-fg-grey-700">
                  <MagniferLinear size={20} />
                </div>
                <input
                  ref={searchInputRef}
                  type="text"
                  aria-label={searchPlaceholder}
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder={searchPlaceholder}
                  className="flex-1 h-6 text-fg-grey-700 text-sm font-normal leading-5 tracking-fg bg-transparent outline-none placeholder:text-fg-grey-700"
                />
              </div>
            </div>

            {/* Icon grid */}
            <div className="self-stretch p-3 flex flex-wrap gap-2 content-start max-h-72 overflow-y-auto">
              {filteredIndexes.map((index) => {
                const icon = icons[index];
                const isSelected = index === selectedIndex;
                return (
                  <button
                    key={index}
                    type="button"
                    aria-label={labels?.[index] ?? `图标 ${index + 1}`}
                    aria-pressed={isSelected}
                    onClick={() => {
                      onChange?.(index);
                    }}
                    className={cn(
                      "p-2 rounded-[10px] flex items-center justify-center cursor-pointer transition-colors",
                      isSelected
                        ? cn("outline outline-1 outline-offset-[-1px]", accent.outline, accent.text)
                        : "text-fg-grey-700 hover:bg-fg-grey-200",
                    )}
                  >
                    <div className="w-6 h-6 flex items-center justify-center">
                      {icon}
                    </div>
                  </button>
                );
              })}
              {filteredIndexes.length === 0 && (
                <p className="w-full py-6 text-center text-sm text-fg-grey-700">未找到匹配图标</p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { cn } from "../../lib/utils";

// ==================================================================
// Style Guide — atomic display components for Color / Typography case
// ==================================================================

// ── ColorSwatch ─────────────────────────────────────────────────────
// Tile with label top-left + hex pill bottom-right. Pure-white swatch
// gets an outline + grey hex pill (per Figma).
//
// size:
//   - sm (default): 112×80 — compact, fits 10 swatches in ~1120px
//   - md: 144×112
//   - lg: 192×160 — matches Figma style-guide frame exactly

export type ColorSwatchSize = "sm" | "md" | "lg";

const SWATCH_SIZE: Record<ColorSwatchSize, {
  box: string;
  label: string;
  pill: string;
  inset: string;
}> = {
  sm: {
    box: "h-16 w-24",
    label: "text-[10px] font-semibold leading-3",
    pill: "px-1.5 py-0.5 text-[10px] font-semibold leading-3",
    inset: "left-1.5 top-1.5 bottom-1.5 right-1.5",
  },
  md: {
    box: "h-28 w-36",
    label: "text-sm font-semibold leading-5",
    pill: "px-3 py-1 text-xs font-semibold leading-4",
    inset: "left-3 top-3 bottom-3 right-3",
  },
  lg: {
    box: "w-full max-w-48 aspect-[6/5]",
    label: "text-sm font-semibold leading-5",
    pill: "px-4 py-2 text-sm font-semibold leading-5",
    inset: "left-4 top-4 bottom-4 right-4",
  },
};

export function ColorSwatch({
  label,
  hex,
  tone,
  size = "sm",
}: {
  label: string;
  hex: string;
  tone: "dark" | "light";
  size?: ColorSwatchSize;
}) {
  const normalizedHex = hex.trim().toLowerCase();
  const hexLabel = normalizedHex.startsWith("var(") ? hex : hex.replace("#", "").toUpperCase();
  const shortWhiteHex = ["#", "fff"].join("");
  const longWhiteHex = ["#", "ffffff"].join("");
  const isPureWhite =
    normalizedHex === "var(--fg-white)" ||
    normalizedHex === shortWhiteHex ||
    normalizedHex === longWhiteHex;
  const s = SWATCH_SIZE[size];
  // inset shortcuts pulled from SWATCH_SIZE so the label/pill padding
  // scales with the box.
  const [left, top, bottom, right] = s.inset.split(" ");
  return (
    <div
      className={cn(
        "relative",
        s.box,
        isPureWhite && "outline outline-1 -outline-offset-1 outline-fg-grey-200",
      )}
      style={{ backgroundColor: hex }}
    >
      <span
        className={cn(
          "absolute tracking-tight",
          left, top,
          s.label,
          tone === "dark" ? "text-fg-black" : "text-white",
        )}
      >
        {label}
      </span>
      <span
        className={cn(
          "absolute rounded-full tracking-tight text-fg-black",
          right, bottom,
          s.pill,
          isPureWhite ? "bg-fg-grey-100" : "bg-white",
        )}
      >
        {hexLabel}
      </span>
    </div>
  );
}

// ── ColorSection (title + 10 swatches) ──────────────────────────────
export interface ColorScaleStop {
  shade: string; // "50", "100", ..., "900"
  hex: string;
}

export function ColorSection({
  title,
  scale,
  darkLabelUntil,
  swatchSize = "sm",
}: {
  title: string;
  scale: ColorScaleStop[];
  /** Shades ≤ this value get dark text; above get white text. */
  darkLabelUntil: number;
  swatchSize?: ColorSwatchSize;
}) {
  return (
    <div className="flex flex-col items-start gap-4 w-full">
      <h3 className="text-xl font-semibold tracking-tight text-fg-black">{title}</h3>
      <div className="w-full overflow-x-auto">
        <div className="inline-flex items-stretch">
          {scale.map(({ shade, hex }) => (
            <ColorSwatch
              key={shade}
              label={`${title} ${shade}`}
              hex={hex}
              tone={Number(shade) <= darkLabelUntil ? "dark" : "light"}
              size={swatchSize}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

// ── TypefaceBlock (Aa + font name) ──────────────────────────────────
export function TypefaceBlock({
  name,
  sample = "Aa",
}: {
  name: string;
  sample?: string;
}) {
  return (
    <div className="flex w-full min-w-0 max-w-full flex-col items-start gap-4">
      <span className="text-xl font-medium font-display leading-8 tracking-tight text-fg-grey-700">
        Typeface
      </span>
      <div className="w-full min-w-0 max-w-full overflow-x-auto">
        <div className="inline-flex items-center gap-4">
        <span className="text-8xl font-semibold font-display leading-[140px] tracking-wide text-fg-black">
          {sample}
        </span>
        <span className="text-xl font-medium font-display leading-8 tracking-tight text-fg-violet">
          {name}
        </span>
        </div>
      </div>
    </div>
  );
}

// ── TypographyWeightSample (single weight cell) ─────────────────────
type FontWeight = 700 | 600 | 500 | 400;

const WEIGHT_CLASS: Record<FontWeight, string> = {
  700: "font-bold",
  600: "font-semibold",
  500: "font-medium",
  400: "font-normal",
};

export function TypographyWeightSample({
  text,
  weight,
  sizeClass,
}: {
  text: string;
  weight: FontWeight;
  sizeClass: string;
}) {
  return (
    <div className="inline-flex w-40 flex-col items-start gap-2">
      <span className={cn("font-sans tracking-tight text-fg-black", sizeClass, WEIGHT_CLASS[weight])}>
        {text}
      </span>
      <span className="text-sm font-medium font-display leading-5 tracking-tight text-fg-grey-700">
        {weight}
      </span>
    </div>
  );
}

// ── TypographySizeRow (size label + 4 weights) ──────────────────────
export function TypographySizeRow({
  label,
  text,
  sizeClass,
}: {
  label: string;
  text: string;
  sizeClass: string;
}) {
  return (
    <div className="flex w-full min-w-0 max-w-full flex-col items-start gap-4">
      <span className="text-base font-medium font-display leading-6 tracking-tight text-fg-grey-700">
        {label}
      </span>
      <div className="w-full min-w-0 max-w-full overflow-x-auto">
        <div className="inline-flex items-start gap-12">
        {([700, 600, 500, 400] as const).map((w) => (
          <TypographyWeightSample key={w} text={text} weight={w} sizeClass={sizeClass} />
        ))}
        </div>
      </div>
    </div>
  );
}

import { cn } from "../../lib/utils";

// ==================================================================
// Style Guide — atomic display components for Color / Typography case
// ==================================================================

// ── ColorSwatch ─────────────────────────────────────────────────────
// Tile with label top-left + hex pill bottom-right. Pure-white swatch
// gets an outline + grey hex pill (per Figma).
//
// size:
//   - sm (default): 112×80 — compact, fits 10 swatches in ~1120px
//   - md: 144×112
//   - lg: 192×160 — matches Figma style-guide frame exactly

export type ColorSwatchSize = "sm" | "md" | "lg";

const SWATCH_SIZE: Record<ColorSwatchSize, {
  box: string;
  label: string;
  pill: string;
  inset: string;
}> = {
  sm: {
    box: "h-16 w-24",
    label: "text-[10px] font-semibold leading-3",
    pill: "px-1.5 py-0.5 text-[10px] font-semibold leading-3",
    inset: "left-1.5 top-1.5 bottom-1.5 right-1.5",
  },
  md: {
