  /** Stable selected row identities. Pair with getRowKey for sort/filter-safe selection. */
  selectedRowKeys?: ReadonlySet<Key>;
  /** Receives a new Set after a stable-key selection change. The input Set is never mutated. */
  onSelectedRowKeysChange?: (keys: Set<Key>) => void;
  /** @deprecated Prefer selectedRowKeys for selection that survives sorting and filtering. */
  selectedRows?: Set<number>;
  onSelectRow?: (index: number, checked: boolean) => void;
  onSelectAll?: (checked: boolean) => void;
  onSort?: (columnKey: string) => void;
  sortColumnKey?: string;
  sortDirection?: "asc" | "desc";
  getRowKey?: (row: T, index: number) => Key;
  emptyState?: ReactNode;
  footerLeft?: ReactNode;
  footerRight?: ReactNode;
  showPagination?: boolean;
  currentPage?: number;
  totalPages?: number;
  onPageChange?: (page: number) => void;
  paginationLabel?: string;
  /** Minimum width of the table content. Overflow stays inside the component. */
  tableMinWidth?: CSSProperties["minWidth"];
  className?: string;
};

function getPageNumbers(
  totalPages: number,
  currentPage: number
): (number | "...")[] {
  if (totalPages <= 5) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }
  const pages: (number | "...")[] = [1];
  if (currentPage > 3) pages.push("...");
  const start = Math.max(2, currentPage - 1);
  const end = Math.min(totalPages - 1, currentPage + 1);
  for (let i = start; i <= end; i++) pages.push(i);
  if (currentPage < totalPages - 2) pages.push("...");
  pages.push(totalPages);
  return pages;
}

export function getPaginationSummary({
  currentPage,
  pageSize,
  rowCount,
  totalRows,
}: {
  currentPage: number;
  pageSize: number;
  rowCount: number;
  totalRows?: number;
}): string {
  if (rowCount <= 0) return totalRows === undefined ? "暂无数据" : `显示 0，共 ${totalRows} 条`;
  const start = (Math.max(1, currentPage) - 1) * pageSize + 1;
  const end = start + rowCount - 1;
  return totalRows === undefined ? `显示 ${start}-${end}` : `显示 ${start}-${end}，共 ${totalRows} 条`;
}

type TableGridProps<T> = Pick<
  DataTableProps<T>,
  | "columns"
  | "rows"
  | "showCheckbox"
  | "checkboxColor"
  | "selectedRowKeys"
  | "selectedRows"
  | "onSelectedRowKeysChange"
  | "onSelectRow"
  | "onSelectAll"
  | "onSort"
  | "sortColumnKey"
  | "sortDirection"
  | "getRowKey"
  | "emptyState"
  | "tableMinWidth"
>;

function TableGrid<T>({
  columns,
  rows,
  showCheckbox = false,
  checkboxColor = "black",
  selectedRowKeys,
  selectedRows,
  onSelectedRowKeysChange,
  onSelectRow,
  onSelectAll,
  onSort,
  sortColumnKey,
  sortDirection,
  getRowKey,
  emptyState = "暂无数据",
  tableMinWidth,
}: TableGridProps<T>) {
  const getKey = (row: T, rowIndex: number) => getRowKey?.(row, rowIndex) ?? rowIndex;
  const isRowSelected = (row: T, rowIndex: number) => (
    selectedRowKeys?.has(getKey(row, rowIndex))
    ?? selectedRows?.has(rowIndex)
    ?? false
  );
  const allSelected = rows.length > 0 && rows.every(isRowSelected);

  const updateKeySelection = (checked: boolean, rowIndexes: number[]) => {
    if (selectedRowKeys == null) return;
    const nextSelectedRowKeys = new Set(selectedRowKeys);
    for (const rowIndex of rowIndexes) {
      const rowKey = getKey(rows[rowIndex], rowIndex);
      if (checked) nextSelectedRowKeys.add(rowKey);
      else nextSelectedRowKeys.delete(rowKey);
    }
    onSelectedRowKeysChange?.(nextSelectedRowKeys);
  };

  return (
    <div data-forge-table-scroll className="self-stretch overflow-x-auto">
      <table
        data-forge-table-content
        className="w-full border-collapse"
        style={{
          minWidth: tableMinWidth ?? getDefaultTableMinWidth(columns, showCheckbox),
        }}
      >
        <thead>
          <tr className="border-t border-b border-fg-grey-200">
            {showCheckbox && (
              <th className="w-14 px-6 py-4 bg-white text-left">
                <Checkbox
                  aria-label="选择全部行"
                  checked={allSelected}
                  color={checkboxColor}
                  onChange={(checked) => {
                    updateKeySelection(checked, rows.map((_, rowIndex) => rowIndex));
                    if (selectedRowKeys == null) onSelectAll?.(checked);
                  }}
                />
              </th>
            )}
            {columns.map((col, colIndex) => {
              const align = resolveTableColumnAlign(col);
              const sortButton = col.sortable ? (
                <button
                  type="button"
                  aria-label={`按${typeof col.header === "string" ? col.header : col.key}排序`}
                  onClick={() => onSort?.(col.key)}
                  className={cn(
                    "w-4 h-4 flex items-center justify-center cursor-pointer text-fg-grey-500",
                    sortColumnKey === col.key && sortDirection === "asc" && "rotate-180",
                  )}
                >
                  <AltArrowDownLinear size={10} />
                </button>
              ) : null;
              return (
                <th
                  key={col.key}
                  data-forge-table-identity={isTableIdentityColumn(col, colIndex) ? "" : undefined}
                  {...columnAlignDataAttrs(col)}
                  aria-sort={
                    col.sortable && sortColumnKey === col.key
                      ? sortDirection === "asc"
                        ? "ascending"
                        : sortDirection === "desc"
                          ? "descending"
                          : "none"
                      : undefined
                  }
                  className={tableColumnClass(col, colIndex, "header")}
                  style={tableColumnStyle(col, colIndex)}
                >
                  <div
                    className={cn(
                      "flex w-full min-w-0 items-center gap-2",
                      align === "right" ? "justify-end" : "justify-start",
                    )}
                  >
                    {align === "right" ? sortButton : null}
                    <span className="min-w-0">{col.header}</span>
                    {align === "right" ? null : sortButton}
                  </div>
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <tr key={getKey(row, rowIndex)} className="border-b border-fg-grey-200 bg-white">
              {showCheckbox && (
                <td className="w-14 px-6 py-4">
                  <Checkbox
                    aria-label={`选择第 ${rowIndex + 1} 行`}
                    checked={isRowSelected(row, rowIndex)}
                    color={checkboxColor}
                    onChange={(checked) => {
                      updateKeySelection(checked, [rowIndex]);
                      if (selectedRowKeys == null) onSelectRow?.(rowIndex, checked);
                    }}
                  />
                </td>
              )}
              {columns.map((col, colIndex) => (
                <td
                  key={col.key}
                  data-forge-table-identity={isTableIdentityColumn(col, colIndex) ? "" : undefined}
                  {...columnAlignDataAttrs(col)}
                  className={tableColumnClass(col, colIndex, "body")}
                  style={tableColumnStyle(col, colIndex)}
                >
                  <TableColumnAlignContext.Provider
                    value={{ align: resolveTableColumnAlign(col), columnKey: col.key }}
                  >
                    {col.render(row, rowIndex)}
                  </TableColumnAlignContext.Provider>
                </td>
              ))}
            </tr>
          ))}
          {rows.length === 0 && (
            <tr className="border-b border-fg-grey-200 bg-white">
              <td
                colSpan={columns.length + (showCheckbox ? 1 : 0)}
                className="px-5 py-10 text-center text-sm text-fg-grey-700"
              >
                {emptyState}
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

function PaginationControls({
  color,
  currentPage,
  totalPages,
  onPageChange,
}: {
  color: DataTableColor;
  currentPage: number;
  totalPages: number;
  onPageChange?: (page: number) => void;
}) {
  return (
    <div className="flex justify-start items-start gap-2">
      <button
        type="button"
        onClick={() => onPageChange?.(Math.max(1, currentPage - 1))}
        disabled={currentPage <= 1}
        className="p-2.5 rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex justify-center items-center gap-1 overflow-hidden cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
      >
        <AltArrowLeftLinear size={20} color="var(--fg-grey-500)" />
      </button>
      {getPageNumbers(totalPages, currentPage).map((page, index) =>
        page === "..." ? (
          <span
            key={`ellipsis-${index}`}
            className="w-10 h-10 p-2 rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex justify-center items-center gap-1 overflow-hidden"
          >
            <span className="flex-1 text-center text-fg-grey-700 text-sm font-semibold leading-5 tracking-fg">
              ...
            </span>
          </span>
        ) : (
          <button
            key={page}
            type="button"
            onClick={() => onPageChange?.(page)}
            className={cn(
              "w-10 h-10 p-2 rounded-full flex justify-center items-center gap-1 overflow-hidden cursor-pointer",
              page === currentPage
                ? cn(headerActiveColors[color], "text-white")
                : "outline outline-1 outline-offset-[-1px] outline-fg-grey-200 text-fg-grey-700",
            )}
          >
            <span className="flex-1 text-center text-sm font-semibold leading-5 tracking-fg">
              {page}
            </span>
          </button>
        ),
      )}
      <button
        type="button"
        onClick={() => onPageChange?.(Math.min(totalPages, currentPage + 1))}
        disabled={currentPage >= totalPages}
        className="p-2.5 rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex justify-center items-center gap-1 overflow-hidden cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
      >
        <AltArrowRightLinear size={20} color="var(--fg-grey-500)" />
      </button>
    </div>
  );
}

export function DataTable<T>({
  title,
  subtitle,
  badge,
  columns,
  rows,
  headerActions,
  color = "black",
  showCheckbox = false,
  checkboxColor = "black",
  selectedRowKeys,
  onSelectedRowKeysChange,
  selectedRows,
  onSelectRow,
  onSelectAll,
  onSort,
  sortColumnKey,
  sortDirection,
  getRowKey,
  emptyState = "暂无数据",
  footerLeft,
  footerRight,
  showPagination = false,
  currentPage = 1,
  totalPages = 1,
  onPageChange,
  paginationLabel,
  tableMinWidth,
  className,
}: DataTableProps<T>) {
  return (
    <div
      data-forge-data-table
      className={cn(
        "w-full rounded-card outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex flex-col justify-start items-start overflow-hidden",
        className
      )}
    >
      {/* Header */}
      {(title || headerActions) && (
        <div className="self-stretch p-5 bg-white flex justify-start items-center gap-3">
          {(title || subtitle || badge) && (
            <div className="flex-1 flex justify-start items-center gap-4">
              <div className="inline-flex flex-col justify-center items-start gap-2">
                {title && (
                  <div className="justify-start text-fg-black text-sm font-semibold leading-5 tracking-fg">
                    {title}
                  </div>
                )}
                {subtitle && (
                  <div className="justify-start text-fg-grey-700 text-xs font-medium leading-4.5 tracking-fg">
                    {subtitle}
                  </div>
                )}
              </div>
              {badge}
            </div>
          )}
          {headerActions}
        </div>
      )}

      <TableGrid
        columns={columns}
        rows={rows}
        showCheckbox={showCheckbox}
        checkboxColor={checkboxColor}
        selectedRowKeys={selectedRowKeys}
        selectedRows={selectedRows}
        onSelectedRowKeysChange={onSelectedRowKeysChange}
        onSelectRow={onSelectRow}
        onSelectAll={onSelectAll}
        onSort={onSort}
        sortColumnKey={sortColumnKey}
        sortDirection={sortDirection}
        getRowKey={getRowKey}
        emptyState={emptyState}
        tableMinWidth={tableMinWidth}
      />

      {/* Footer */}
      {(showPagination || footerLeft || footerRight) && (
        <div className="self-stretch p-5 bg-white flex justify-start items-center gap-3">
          {paginationLabel ? (
            <div className="flex-1 justify-start text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
              {paginationLabel}
            </div>
          ) : (
            footerLeft && <div className="flex-1">{footerLeft}</div>
          )}
          {showPagination && (
            <PaginationControls
              color={color}
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={onPageChange}
            />
          )}
          {footerRight && !showPagination && (
            <div>{footerRight}</div>
          )}
        </div>
      )}
    </div>
  );
}

// FullWidthTable: same row/cell shape as DataTable, but adds the "Show N" rows-per-page
// selector and defaults showCheckbox to true — used for full-screen data management pages.

export type FullWidthTableProps<T> = DataTableProps<T> & {
  showRowCount?: boolean;
  rowCountOptions?: number[];
  currentRowCount?: number;
  onRowCountChange?: (count: number) => void;
  /** Exact total record count. Omit it when the data source does not provide one. */
  totalRows?: number;
};

export function FullWidthTable<T>({
  title,
  subtitle,
  badge,
  columns,
  rows,
  headerActions,
  color = "black",
  showCheckbox = true,
  checkboxColor = "black",
  selectedRowKeys,
  onSelectedRowKeysChange,
  selectedRows,
  onSelectRow,
  onSelectAll,
  onSort,
  sortColumnKey,
  sortDirection,
  getRowKey,
  emptyState = "暂无数据",
  footerLeft,
  footerRight,
  showPagination = true,
  currentPage = 1,
  totalPages = 1,
  onPageChange,
  paginationLabel,
  tableMinWidth,
  showRowCount = false,
  rowCountOptions = [10, 25, 50],
  currentRowCount = 10,
  onRowCountChange,
  totalRows,
  className,
}: FullWidthTableProps<T>) {
  return (
    <div
      data-forge-full-width-table
      className={cn(
        "w-full rounded-card outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex flex-col justify-start items-start overflow-hidden",
        className
      )}
    >
      {/* Header */}
      {(title || headerActions) && (
        <div className="self-stretch p-5 bg-white flex justify-start items-center gap-4">
          <div className="flex-1 flex justify-start items-center gap-4">
            <div className="inline-flex flex-col justify-center items-start gap-2">
              {title && (
                <div className="justify-start text-fg-black text-sm font-semibold leading-5 tracking-fg">
                  {title}
                </div>
              )}
              {subtitle && (
                <div className="justify-start text-fg-grey-700 text-xs font-medium leading-4.5 tracking-fg">
                  {subtitle}
                </div>
              )}
            </div>
            {badge}
          </div>
          {headerActions}
          {showRowCount && (
            <div className="flex justify-start items-center gap-2">
              <span className="justify-start text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
                显示
              </span>
              <select
                value={currentRowCount}
                onChange={(e) => onRowCountChange?.(Number(e.target.value))}
                className="w-20 px-4 py-3 bg-white rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 text-center text-fg-black text-sm font-normal leading-5 tracking-fg cursor-pointer"
              >
                {rowCountOptions.map((n) => (
                  <option key={n} value={n}>
                    {n}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>
      )}

      <TableGrid
        columns={columns}
        rows={rows}
        showCheckbox={showCheckbox}
        checkboxColor={checkboxColor}
        selectedRowKeys={selectedRowKeys}
        selectedRows={selectedRows}
        onSelectedRowKeysChange={onSelectedRowKeysChange}
        onSelectRow={onSelectRow}
        onSelectAll={onSelectAll}
        onSort={onSort}
        sortColumnKey={sortColumnKey}
        sortDirection={sortDirection}
        getRowKey={getRowKey}
        emptyState={emptyState}
        tableMinWidth={tableMinWidth}
      />

      {/* Footer */}
      <div className="self-stretch p-5 bg-white flex justify-start items-center gap-3">
        {paginationLabel ? (
          <div className="flex-1 justify-start text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
            {paginationLabel}
          </div>
        ) : footerLeft ? (
          <div className="flex-1">{footerLeft}</div>
        ) : (
          <div className="flex-1 justify-start text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
            {getPaginationSummary({ currentPage, pageSize: currentRowCount, rowCount: rows.length, totalRows })}
          </div>
        )}
        {showPagination && (
          <PaginationControls
            color={color}
            currentPage={currentPage}
            totalPages={totalPages}
            onPageChange={onPageChange}
          />
        )}
        {footerRight && !showPagination && <div>{footerRight}</div>}
      </div>
    </div>
  );
}

