/* eslint-disable @next/next/no-img-element */

import { ReplyLinear } from "../../icons";

export type CommentReply = {
  avatar: string;
  name: string;
  date: string;
  content: string;
  onReply?: () => void;
  replyLabel?: string;
};

export type CommentData = CommentReply & {
  images?: string[];
  replies?: CommentReply[];
  className?: string;
};

function CommentInner({
  name,
  date,
  content,
  images,
  onReply,
  replyLabel = "回复",
}: {
  name: string;
  date: string;
  content: string;
  images?: string[];
  onReply?: () => void;
  replyLabel?: string;
}) {
  return (
    <div className="flex-1 min-w-0 inline-flex flex-col justify-center items-start gap-2">
