          </div>
        </SubSection>
      </Section>

      <Section title="AgentFlowchart" description="点节点看选中态。">
        <SubSection title="补货" stack>
          <div className="max-w-lg">
            <AgentFlowchart
              title="补货流程"
              nodes={[
                { id: "spike", kind: "trigger", title: "周末收银数据峰值", body: "薄荷巧克力销量超过 80 份。" },
