import { fileIconDataUrls } from "../../../assets/_inlined";

const extToIcon: Record<string, string> = {
  pdf: "pdf",
  doc: "doc", docx: "doc",
  txt: "txt", rtf: "txt",
  xls: "xls", xlsx: "xls", csv: "xls",
  ppt: "ppt", pptx: "ppt",
  png: "png", webp: "png",
  jpg: "jpg", jpeg: "jpg",
