  mp4: "mp4", mov: "mov", avi: "avi", mkv: "mkv",
  mp3: "mp3", wav: "wav", flac: "mp3",
  zip: "zip", tar: "zip", gz: "zip",
  rar: "rar",
  fig: "fig", psd: "psd", ai: "ai",
  folder: "folder",
};

function getFileExt(name: string): string {
  const parts = name.toLowerCase().split(".");
  // Fallback to full name so callers can pass bare keywords like "folder".
  return parts.length > 1 ? parts[parts.length - 1] : parts[0];
}

export function FileTypeIcon({ fileName, dim = false, className }: {
  fileName: string;
  dim?: boolean;
  className?: string;
}) {
  const ext = getFileExt(fileName);
  const iconName = extToIcon[ext] ?? "txt";
  const src = fileIconDataUrls[iconName] ?? fileIconDataUrls.txt;

  return (
    /* eslint-disable-next-line @next/next/no-img-element */
    <img
      src={src}
      alt={ext}
      className={cn("w-12 h-12 shrink-0 object-contain", dim && "opacity-50", className)}
    />
  );
}

// ── FileCard ─────────────────────────────────────────────

export function FileCard({
  file,
  onRemove,
  onRetry,
  locale = "zh",
  color = "blue",
  className,
}: {
  file: FileItem;
  locale?: "zh" | "en";
  color?: FileUploadColor;
  onRemove?: (id: string) => void;
  onRetry?: (id: string) => void;
  className?: string;
}) {
  const state = file.state ?? "uploaded";
  const isUploading = state === "uploading";
  const isSuccess = state === "success";
  const isError = state === "error";
  const progress = typeof file.progress === "number" && Number.isFinite(file.progress) ? Math.max(0, Math.min(100, file.progress)) : undefined;
  const en = locale === "en";

  return (
    <div
      className={cn(
        "self-stretch p-4 bg-white rounded-xl outline outline-1 outline-offset-[-1px] outline-fg-grey-200 inline-flex items-center gap-3 overflow-hidden",
        className,
      )}
    >
      <FileTypeIcon fileName={file.name} dim={isUploading} />

      <div className="flex-1 inline-flex flex-col justify-center items-start gap-1 min-w-0">
        <span className="self-stretch text-fg-black text-sm font-semibold leading-5 tracking-fg truncate">
          {file.name}
        </span>
        <div className="self-stretch inline-flex items-center gap-1">
          <span className="text-fg-grey-700 text-xs font-medium leading-4 tracking-fg">
            {file.size}
          </span>
          {(isSuccess || isUploading || isError) && (
            <>
              <span className="text-fg-grey-700 text-xs font-medium leading-4 tracking-fg">-</span>
              <div className="flex items-center gap-1">
                {isSuccess && (
                  <>
                    <div className="p-1 bg-fg-green-500 rounded-full flex items-center justify-center">
                      <CheckCircleLinear size={12} color="currentColor" />
                    </div>
                    <span className="text-fg-green-500 text-xs font-medium leading-4 tracking-fg">
                      {en ? "Uploaded" : "已上传"}
                    </span>
                  </>
                )}
                {isUploading && (
                  <>
                    <div className="p-1 bg-fg-yellow rounded-full flex items-center justify-center text-white">
                      <RefreshLinear size={10} />
                    </div>
                    <span className="text-fg-yellow text-xs font-medium leading-4 tracking-fg">
                      {en ? "Uploading" : "上传中"}
                    </span>
                  </>
                )}
                {isError && (
                  <>
                    <div className="p-1 bg-fg-red rounded-full flex items-center justify-center text-white">
                      <CloseCircleLinear size={10} />
                    </div>
                    <span className="text-fg-red text-xs font-medium leading-4 tracking-fg">
                      {en ? "Upload failed" : "上传失败"}
                    </span>
                  </>
                )}
              </div>
            </>
          )}
        </div>
        {progress !== undefined && <div className="w-full mt-1" data-file-progress={progress}>
          <div className="mb-1 flex justify-between text-xs text-fg-grey-700"><span>{file.uploadedBytes !== undefined && file.totalBytes !== undefined ? `${new Intl.NumberFormat(locale).format(file.uploadedBytes)} / ${new Intl.NumberFormat(locale).format(file.totalBytes)} B` : en ? "Upload progress" : "上传进度"}</span><span>{Math.round(progress)}%</span></div>
          <div role="progressbar" aria-label={`${file.name} ${en ? "upload progress" : "上传进度"}`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress} className="h-1 w-full overflow-hidden rounded-full bg-fg-grey-200"><div className={cn("h-full rounded-full transition-[width] motion-reduce:transition-none", accentColors[color].bg)} style={{ width: `${progress}%` }} /></div>
        </div>}
      </div>

      <div className="flex items-center gap-2 shrink-0">
        {isError && onRetry && (
          <button
            type="button"
            aria-label={`${en ? "Retry upload" : "重试上传"} ${file.name}`}
            title={en ? "Retry upload" : "重试上传"}
            onClick={() => onRetry(file.id)}
            className="w-5 h-5 flex items-center justify-center text-fg-grey-700 cursor-pointer hover:text-fg-black"
          >
            <RefreshLinear size={16} />
          </button>
        )}
        {onRemove && (
          <button
            type="button"
            aria-label={`${en ? "Remove attachment" : "移除附件"} ${file.name}`}
            title={en ? "Remove attachment" : "移除附件"}
            onClick={() => onRemove(file.id)}
            className="w-5 h-5 flex items-center justify-center text-fg-grey-700 cursor-pointer hover:text-fg-black"
          >
            <CloseCircleLinear size={16} />
          </button>
        )}
      </div>
    </div>
  );
}

// ── FileUpload ───────────────────────────────────────────

export function FileUpload({
  files = [],
  label,
  buttonLabel,
  locale = "zh",
  color = "blue",
  onUpload,
  onRemove,
  onRetry,
  className,
}: {
  files?: FileItem[];
  label?: string;
  buttonLabel?: string;
  locale?: "zh" | "en";
  color?: FileUploadColor;
  onUpload?: (files: FileList) => void;
  onRemove?: (id: string) => void;
  onRetry?: (id: string) => void;
  className?: string;
}) {
  const inputRef = useRef<HTMLInputElement>(null);
  const accent = accentColors[color];
  const [dragOver, setDragOver] = useState(false);

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files.length > 0) onUpload?.(e.dataTransfer.files);
  }

  return (
    <div className={cn("flex w-full max-w-72 flex-col gap-2", className)}>
      {label && (
        <span className="text-sm font-medium text-fg-grey-700 leading-5 tracking-fg">
          {label}
        </span>
      )}

      <div
        className={cn(
          "self-stretch flex flex-col gap-4 p-4 rounded-xl border-2 border-dashed transition-colors",
          dragOver ? cn("border-accent bg-accent-soft") : "border-transparent",
        )}
        onDrop={handleDrop}
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
      >
        {files.length > 0 && (
          <div className="self-stretch flex flex-col gap-3 overflow-hidden">
            {files.map((file) => (
              <FileCard
                key={file.id}
                file={file}
                locale={locale}
                color={color}
                onRemove={onRemove}
                onRetry={onRetry}
              />
            ))}
          </div>
        )}

        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          className={cn(
            "px-4 py-3.5 rounded-full flex justify-center items-center overflow-hidden cursor-pointer self-start",
            accent.bg,
          )}
        >
          <span className="text-white text-sm font-bold leading-5 tracking-fg">
            {buttonLabel ?? (locale === "en" ? "Add files" : "添加文件")}
          </span>
        </button>

        <input
          ref={inputRef}
          type="file"
          multiple
          className="hidden"
          onChange={(e) => {
            if (e.target.files && e.target.files.length > 0) onUpload?.(e.target.files);
            e.target.value = "";
          }}
        />
      </div>
    </div>
  );
}

"use client";

import { useId, useState, type ReactNode } from "react";
import {
  AddSquareLinear,
  MinusSquareLinear,
  FiltersLinear,
} from "../../icons";
import { accentColors, type AccentColor } from "./accent-utils";

export type FilterGroupColor = AccentColor;

export type FilterGroupCheckboxOption = {
  value: string;
  label: string;
  checked?: boolean;
  colorDot?: string;
};

export type FilterGroupRadioOption = {
  value: string;
  label: string;
  checked?: boolean;
};

export type FilterGroupContent =
  | { type: "empty" }
  | {
      type: "checkbox";
      options: FilterGroupCheckboxOption[];
      onToggle?: (value: string, checked: boolean) => void;
    }
  | {
      type: "radio";
      options: FilterGroupRadioOption[];
      onSelect?: (value: string) => void;
    }
  | {
      type: "range";
      minLabel?: string;
      maxLabel?: string;
      minPlaceholder?: string;
      maxPlaceholder?: string;
      minValue?: string;
      maxValue?: string;
      onMinChange?: (value: string) => void;
      onMaxChange?: (value: string) => void;
    };

export function FilterGroup({
  title = "筛选分组",
  color = "blue",
  content = { type: "empty" },
  defaultOpen,
  hasSelection,
}: {
  title?: string;
  color?: FilterGroupColor;
  content?: FilterGroupContent;
  defaultOpen?: boolean;
  hasSelection?: boolean;
}) {
  const computedDefaultOpen = defaultOpen ?? content.type !== "empty";
  const [open, setOpen] = useState(computedDefaultOpen);
  const radioName = useId();

  // range 分组在 Figma 中不展示右侧 accent bar
  const selectionVisible =
    content.type === "range"
      ? false
      : (hasSelection ??
        (content.type === "checkbox"
          ? content.options.some((o) => o.checked)
          : content.type === "radio"
            ? content.options.some((o) => o.checked)
            : false));

  return (
    <div className="self-stretch bg-fg-grey-50 rounded-xl outline outline-1 outline-offset-[-1px] outline-fg-grey-200 flex flex-col overflow-hidden">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="self-stretch px-4 py-3 border-b border-fg-grey-200 inline-flex justify-start items-center gap-2"
      >
        <span className="flex-1 text-left text-fg-black text-sm font-semibold leading-5 tracking-fg">
          {title}
        </span>
        <span className="inline-flex text-fg-grey-700">
          {open ? (
            <MinusSquareLinear size={20} />
          ) : (
            <AddSquareLinear size={20} />
          )}
        </span>
      </button>

      {open && content.type !== "empty" && (
        <div className="self-stretch bg-white flex justify-start items-stretch">
          <div className="flex-1 p-4 flex flex-col gap-4">
            {content.type === "checkbox" &&
              content.options.map((option) => (
                <CheckboxRow
                  key={option.value}
                  color={color}
                  option={option}
                  onToggle={(checked) => content.onToggle?.(option.value, checked)}
                />
              ))}
            {content.type === "radio" &&
              content.options.map((option) => (
                <RadioRow
                  key={option.value}
                  color={color}
                  name={radioName}
                  option={option}
                  onSelect={() => content.onSelect?.(option.value)}
                />
              ))}
            {content.type === "range" && (
              <>
                <RangeField
                  label={content.minLabel ?? "最小值"}
                  placeholder={content.minPlaceholder ?? "请输入最小值"}
                  value={content.minValue ?? ""}
                  onChange={content.onMinChange}
                />
                <RangeField
                  label={content.maxLabel ?? "最大值"}
                  placeholder={content.maxPlaceholder ?? "请输入最大值"}
                  value={content.maxValue ?? ""}
                  onChange={content.onMaxChange}
                />
              </>
            )}
          </div>
          <AccentBar color={color} visible={selectionVisible} />
        </div>
      )}
    </div>
  );
}

function AccentBar({ color, visible }: { color: FilterGroupColor; visible: boolean }) {
  return (
    <div className="self-stretch w-2 bg-fg-grey-100 flex flex-col items-start overflow-hidden">
      {visible && <div className={`w-1 h-14 ${accentColors[color].bg}`} />}
    </div>
  );
}

function CheckboxRow({
  color,
  option,
  onToggle,
}: {
  color: FilterGroupColor;
  option: FilterGroupCheckboxOption;
  onToggle: (checked: boolean) => void;
}) {
  const checked = option.checked ?? false;
  return (
    <label className="self-stretch inline-flex items-start gap-2 cursor-pointer">
      <CheckboxBox color={color} checked={checked} />
      <input
        type="checkbox"
        className="sr-only"
        checked={checked}
        onChange={(e) => onToggle(e.target.checked)}
      />
      <span className="flex items-start gap-1">
        {option.colorDot && (
          <span
            aria-hidden
            className={`w-5 h-5 rounded-full inline-block ${option.colorDot}`}
          />
        )}
        <SelectionLabel color={color} checked={checked}>
          {option.label}
        </SelectionLabel>
      </span>
    </label>
  );
}

function CheckboxBox({
  color,
  checked,
}: {
  color: FilterGroupColor;
  checked: boolean;
}) {
  if (!checked) {
    return (
      <span className="w-5 h-5 bg-white rounded-md border-2 border-fg-grey-200 inline-block" />
    );
  }
  return (
    <span className={`w-5 h-5 rounded-md relative inline-block ${accentColors[color].bg}`}>
      <svg
        className="absolute inset-0 w-full h-full text-white"
        viewBox="0 0 20 20"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden
      >
        <polyline points="5 10 9 14 15 7" />
      </svg>
    </span>
  );
}

function RadioRow({
  color,
  name,
  option,
  onSelect,
}: {
  color: FilterGroupColor;
  name: string;
  option: FilterGroupRadioOption;
  onSelect: () => void;
}) {
  const checked = option.checked ?? false;
  return (
    <label className="self-stretch inline-flex items-start gap-2 cursor-pointer">
      {checked ? (
        <span className={`p-[5px] rounded-full flex items-start ${accentColors[color].bg}`}>
          <span className="w-2.5 h-2.5 bg-white rounded-full" />
        </span>
      ) : (
        <span className="w-5 h-5 bg-white rounded-full border-2 border-fg-grey-200 inline-block" />
      )}
      <input
        type="radio"
        name={name}
        value={option.value}
        className="sr-only"
        checked={checked}
        onChange={() => onSelect()}
      />
      <SelectionLabel color={color} checked={checked}>
        {option.label}
      </SelectionLabel>
    </label>
  );
}

function SelectionLabel({
  color,
  checked,
  children,
}: {
  color: FilterGroupColor;
  checked: boolean;
  children: ReactNode;
}) {
  return (
    <span
      className={`flex-1 text-sm leading-5 tracking-fg ${
        checked ? `${accentColors[color].text} font-bold` : "text-fg-grey-700 font-semibold"
      }`}
    >
      {children}
    </span>
  );
}

function RangeField({
  label,
  placeholder,
  value,
  onChange,
}: {
  label: string;
  placeholder: string;
  value: string;
  onChange?: (value: string) => void;
}) {
  return (
    <div className="self-stretch flex flex-col gap-1.5">
      <span className="text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
        {label}
      </span>
      <div className="self-stretch px-4 py-3 bg-white rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 inline-flex items-center gap-2">
        <span className="inline-flex text-fg-grey-700">
          <FiltersLinear size={20} />
        </span>
        <input
          type="text"
          value={value}
          placeholder={placeholder}
          onChange={(e) => onChange?.(e.target.value)}
          className="flex-1 bg-transparent outline-none text-sm leading-5 text-fg-black placeholder:text-fg-grey-500"
        />
      </div>
    </div>
  );
}

