"use client";

import { useState } from "react";
import {
  FilterGroup,
  FilterPanel,
  FilterTrigger,
  type FilterGroupColor,
} from "@forge-ui-official/core";
import { PageHeading, Section, SubSection, Labeled } from "../_shared";

const colors = ["purple", "blue", "black"] as const satisfies readonly FilterGroupColor[];

const labelByColor: Record<FilterGroupColor, string> = {
  purple: "紫色",
  blue: "蓝色",
  black: "黑色",
};

const checkboxOptions = [
  { value: "a", label: "选项文字", checked: false },
  { value: "b", label: "选项文字", checked: true },
  { value: "c", label: "选项文字", checked: false },
  { value: "d", label: "选项文字", checked: false },
  { value: "e", label: "选项文字", checked: false },
];

const colorCheckboxOptions = [
  { value: "blue", label: "选项文字", checked: false, colorDot: "bg-blue-700" },
  { value: "green", label: "选项文字", checked: true, colorDot: "bg-emerald-700" },
  { value: "amber", label: "选项文字", checked: false, colorDot: "bg-amber-500" },
  { value: "red", label: "选项文字", checked: true, colorDot: "bg-fg-red" },
  { value: "rose", label: "选项文字", checked: false, colorDot: "bg-rose-200" },
];

const radioOptions = [
  { value: "1", label: "选项文字", checked: false },
  { value: "2", label: "选项文字", checked: false },
  { value: "3", label: "选项文字", checked: true },
  { value: "4", label: "选项文字", checked: false },
  { value: "5", label: "选项文字", checked: false },
];

export default function FilterCasePage() {
  return (
    <div className="flex flex-col gap-8">
      <PageHeading title="筛选" hint="用分组条件和筛选面板缩小结果范围，支持重置和应用。" />

      <Section
        title="Filter Group"
        description="可折叠卡片，3 色 × 3 variant（empty / checkbox / range）。radio 和 color-checkbox 是组件能力，仅在 Filter 面板内嵌演示"
      >
        {colors.map((color) => (
          <SubSection key={color} title={labelByColor[color]}>
            <Labeled label="empty">
              <div className="w-72">
                <FilterGroup color={color} content={{ type: "empty" }} />
              </div>
            </Labeled>
            <Labeled label="checkbox">
              <div className="w-72">
                <FilterGroup
                  color={color}
                  content={{ type: "checkbox", options: checkboxOptions }}
                />
              </div>
            </Labeled>
            <Labeled label="range">
              <div className="w-72">
                <FilterGroup
                  color={color}
                  content={{ type: "range", minValue: "", maxValue: "" }}
                  hasSelection
                />
              </div>
            </Labeled>
          </SubSection>
        ))}
      </Section>

      <Section
        title="筛选"
        description="Trigger pill 4 状态 + 完整 Panel（FilterGroup 容器 + Reset + Cancel/Apply）"
      >
        {colors.map((color) => (
          <SubSection key={color} title={`${labelByColor[color]} · triggers`}>
            <Labeled label="closed">
              <FilterTrigger color={color} />
            </Labeled>
            <Labeled label="closed · count">
              <FilterTrigger color={color} count={8} />
            </Labeled>
            <Labeled label="open">
              <FilterTrigger color={color} open />
            </Labeled>
            <Labeled label="open · count">
              <FilterTrigger color={color} open count={8} />
            </Labeled>
          </SubSection>
        ))}

        {colors.map((color) => (
          <SubSection key={color} title={`${labelByColor[color]} · panel`}>
            <FilterPanelDemo color={color} />
          </SubSection>
        ))}

        <SubSection title="Interactive · trigger + panel wired">
          <Labeled label="click to open">
            <FilterTrigger
              color="blue"
              count={8}
              panel={(close) => (
                <FilterPanel color="blue" onReset={() => {}} onCancel={close} onApply={close}>
                  <FilterGroup
                    color="blue"
                    title="状态"
                    defaultOpen
                    content={{
                      type: "checkbox",
                      options: checkboxOptions,
                      onToggle: () => {},
                    }}
                  />
                </FilterPanel>
              )}
            />
          </Labeled>
        </SubSection>
      </Section>
    </div>
  );
}

function FilterPanelDemo({ color }: { color: FilterGroupColor }) {
  const [minValue, setMinValue] = useState("");
  const [maxValue, setMaxValue] = useState("");

  return (
    <FilterPanel color={color} onReset={() => {}} onCancel={() => {}} onApply={() => {}}>
      <FilterGroup
        color={color}
        content={{ type: "checkbox", options: checkboxOptions }}
      />
      <FilterGroup
        color={color}
        content={{
          type: "range",
          minValue,
          maxValue,
          onMinChange: setMinValue,
          onMaxChange: setMaxValue,
        }}
      />
      <FilterGroup
        color={color}
        content={{ type: "checkbox", options: colorCheckboxOptions }}
      />
      <FilterGroup
        color={color}
        content={{ type: "radio", options: radioOptions }}
      />
    </FilterPanel>
  );
}

