  gray: "bg-fg-grey-500",
  black: "bg-fg-black",
};

export function HistoryGrouped({
  title,
  subtitle,
  badge,
  items,
  action,
  progressHeight = "30%",
  color = "blue",
  className = "",
}: {
  title: string;
  subtitle?: string;
  badge?: ReactNode;
  items: HistoryItemProps[];
  action?: ReactNode;
  progressHeight?: string;
  color?: HistoryItemColor;
  className?: string;
}) {
