import {
  HistoryItem,
  HistoryGrouped,
  Label,
  FileCard,
  TaskCard,
  StyledLink,
  IconButton,
  ImageGrid,
  ProductRow,
  RatingStars,
} from "@forge-ui-official/core";
import type {
  HistoryItemColor,
  HistoryItemProps,
  HistoryItemVariant,
  HistoryItemShowDatetime,
} from "@forge-ui-official/core";
import {
  CheckCircleBold,
  StarLinear,
  AltArrowRightLinear,
  CartBoldDuotone,
  MenuDotsBold,
} from "@forge-ui-official/core/icons";
import { PageHeading, Section, SubSection } from "../_shared";

// ─────────────────────────────────────────────────────────────
// Constants / mock content
// ─────────────────────────────────────────────────────────────

const ALL_COLORS: HistoryItemColor[] = ["purple", "blue", "gray"];

const GROUPED_COLORS: HistoryItemColor[] = ["purple", "blue", "black"];

const DATETIME = "DD/MM/YY, 00:00";

const avatarUrls = [
  "https://i.pravatar.cc/100?img=1",
  "https://i.pravatar.cc/100?img=2",
  "https://i.pravatar.cc/100?img=3",
  "https://i.pravatar.cc/100?img=4",
];

// description with inline violet link (matches Figma "Lorem #302012 ipsum...")
const DESC_LINKED = (
  <>
    <span className="text-fg-grey-700">项目更新 </span>
    <StyledLink href="#" color="blue" className="text-sm font-semibold">
      #302012
    </StyledLink>
    <span className="text-fg-grey-700"> 项目进度已同步</span>
  </>
);

const DESC_SIMPLE = (
  <span className="text-fg-grey-700">查看最新进展及待处理事项</span>
);

// 2 Labels + arrow (Red → Yellow) — status change
const TAGS_STATUS = (
  <>
    <Label color="red" size="sm" variant="outline">红色</Label>
    <span className="text-fg-grey-700 inline-flex">
      <AltArrowRightLinear size={16} color="currentColor" />
    </span>
    <Label color="yellow" size="sm" variant="outline">黄色</Label>
  </>
);

// 4-image grid (Figma 64×64 thumbnails)
const IMG_GRID = (
  <ImageGrid
    size="md"
    images={[1, 2, 3, 4].map((i) => `https://picsum.photos/seed/history${i}/64/64`)}
  />
);

// Small product row (Figma "Product Title · 3 Variant")
const PRODUCT_ROW = (
  <ProductRow
    image="https://picsum.photos/seed/history-product/44/44"
    title="商品名称"
    subtitle="3 种规格"
  />
);

// 4/5 rating stars
const RATING = <RatingStars value={4.0} total={5} />;

const FILE_ROW = (
  <FileCard file={{ id: "f1", name: "会议纪要.doc", size: "300 KB" }} />
);

const TASK_ROW = (
  <TaskCard
    labelText="Label"
    labelColor="red"
    title="项目概览"
    progress={0}
    progressColor="blue"
    avatars={avatarUrls.slice(0, 2)}
    overflowCount={1}
    date="2026 年 10 月 21 日"
    className="max-w-xs"
  />
);

function descWithExtra(extra: React.ReactNode) {
  return (
    <div className="flex flex-col gap-2">
      <div>{DESC_LINKED}</div>
      {extra}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// 6 content rows × 4 column structure variants
// ─────────────────────────────────────────────────────────────

type ContentRow = {
  key: string;
  description: React.ReactNode;
  tags?: React.ReactNode;
};

const CONTENT_ROWS: ContentRow[] = [
  { key: "text+tags", description: DESC_LINKED, tags: TAGS_STATUS },
  { key: "images", description: descWithExtra(IMG_GRID) },
  { key: "product", description: descWithExtra(PRODUCT_ROW) },
  { key: "file", description: descWithExtra(FILE_ROW) },
  { key: "rating", description: descWithExtra(RATING) },
  { key: "task", description: descWithExtra(TASK_ROW) },
];

// 4 structure columns: (datetime position) × (connector on/off)
type StructCol = {
  key: string;
  showDatetime: HistoryItemShowDatetime;
  showConnector: boolean;
  label: string;
};

const STRUCT_COLS: StructCol[] = [
  { key: "inline-conn", showDatetime: "inline", showConnector: true, label: "时间与连接线" },
];

// ─────────────────────────────────────────────────────────────
// Full variant matrix — 4 cols × 6 rows = 24 items per variant
// ─────────────────────────────────────────────────────────────

function VariantMatrix({
  variant,
  color = "blue",
  icon,
}: {
  variant: HistoryItemVariant;
  color?: HistoryItemColor;
  icon?: React.ReactNode;
}) {
  return (
    <div className="grid min-w-0 grid-cols-1 gap-x-8 gap-y-6 md:grid-cols-2">
      {/* Column headers */}
      {STRUCT_COLS.map((col) => (
        <div
          key={`h-${col.key}`}
          className="text-[10px] font-bold uppercase tracking-fg text-fg-grey-700"
        >
          {col.label}
        </div>
      ))}

      {/* Rows: each content type × 4 structure columns */}
      {CONTENT_ROWS.map((row) =>
        STRUCT_COLS.map((col) => (
          <div key={`${row.key}-${col.key}`} className="min-w-0">
            <HistoryItem
              variant={variant}
              color={color}
              title="标题"
              description={row.description}
              tags={row.tags}
              datetime={DATETIME}
              showDatetime={col.showDatetime}
              showConnector={col.showConnector}
              icon={icon}
              avatar={variant === "profile" ? avatarUrls[0] : undefined}
            />
          </div>
        ))
      )}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Page
// ─────────────────────────────────────────────────────────────

export default function HistoryCasePage() {
  return (
    <div className="flex flex-col gap-10">
      <PageHeading
        title="历史记录"
        hint="按时间展示操作和事件，支持分组和进度信息。"
      />

      {/* ───────── 1. Regular ───────── */}
      <Section
        title="1. Regular"
        description="variant=regular · 圆点 indicator"
      >
        <SubSection title="Indicator · 8 colors (single row example)">
          <div className="w-full max-w-md flex flex-col">
            {ALL_COLORS.map((color, i) => (
              <HistoryItem
                key={color}
                variant="regular"
                color={color}
                title={`Title · ${color}`}
                description={DESC_LINKED}
                tags={TAGS_STATUS}
                datetime={DATETIME}
                showDatetime="inline"
                showConnector={i < ALL_COLORS.length - 1}
              />
            ))}
          </div>
        </SubSection>

        <SubSection title="Full matrix · 6 种内容示例 (purple)">
          <VariantMatrix variant="regular" color="blue" />
        </SubSection>
      </Section>

      {/* ───────── 2. Badge ───────── */}
      <Section
        title="2. Badge"
        description="variant=badge · icon 徽章 indicator"
      >
        <SubSection title="Indicator · 8 colors (single row example)">
          <div className="w-full max-w-md flex flex-col">
            {ALL_COLORS.map((color, i) => (
              <HistoryItem
                key={color}
                variant="badge"
                color={color}
                title={`Title · ${color}`}
                description={DESC_LINKED}
                tags={TAGS_STATUS}
                datetime={DATETIME}
                showDatetime="inline"
                icon={<CheckCircleBold size={20} color="currentColor" />}
                showConnector={i < ALL_COLORS.length - 1}
              />
            ))}
          </div>
        </SubSection>

        <SubSection title="Full matrix · 6 种内容示例 (purple)">
          <VariantMatrix
            variant="badge"
            color="blue"
            icon={<CartBoldDuotone size={20} color="currentColor" />}
          />
        </SubSection>
      </Section>

      {/* ───────── 3. Profile ───────── */}
      <Section
        title="3. Profile"
        description="variant=profile · 头像 indicator"
      >
        <SubSection title="Full matrix · 6 种内容示例 (purple)">
          <VariantMatrix variant="profile" color="blue" />
        </SubSection>
      </Section>

      {/* ───────── 4. HistoryGrouped ───────── */}
      <Section
        title="4. HistoryGrouped"
        description="Card 容器 + 右侧 progress bar · color 强制透给内部 items"
      >
        <SubSection title="3 colors × 3 items composition">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full">
            {GROUPED_COLORS.map((color) => (
              <HistoryGrouped
                key={color}
                title="标题"
                subtitle="示例文本"
                color={color}
                progressHeight="40%"
