    {
      variant: "profile",
      title: "标题",
      description: DESC_LINKED,
      datetime: DATETIME,
      showDatetime: "bottom",
      avatar: avatarUrls[0],
    },
    {
      variant: "regular",
      title: "标题",
      description: descWithExtra(PRODUCT_ROW),
      datetime: DATETIME,
      showDatetime: "bottom",
    },
    {
      variant: "badge",
      title: "标题",
      description: descWithExtra(RATING),
      datetime: DATETIME,
      showDatetime: "bottom",
      icon: <CheckCircleBold size={20} color="currentColor" />,
    },
    {
      variant: "profile",
      title: "标题",
      description: descWithExtra(TASK_ROW),
      datetime: DATETIME,
      showDatetime: "bottom",
