      {extra}
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// 6 content rows × 4 column structure variants
// ─────────────────────────────────────────────────────────────

type ContentRow = {
  key: string;
  description: React.ReactNode;
  tags?: React.ReactNode;
};

const CONTENT_ROWS: ContentRow[] = [
  { key: "text+tags", description: DESC_LINKED, tags: TAGS_STATUS },
