function compositionItems(
  kind: "short" | "mixed" | "long",
): HistoryItemProps[] {
  const base: HistoryItemProps[] = [
    {
      variant: "regular",
      title: "标题",
      description: DESC_LINKED,
      tags: TAGS_STATUS,
      datetime: DATETIME,
      showDatetime: "bottom",
    },
    {
      variant: "badge",
      title: "标题",
      description: descWithExtra(IMG_GRID),
      datetime: DATETIME,
      showDatetime: "bottom",
      icon: <StarLinear size={20} color="currentColor" />,
    },
    {
      variant: "regular",
      title: "标题",
      description: descWithExtra(FILE_ROW),
      datetime: DATETIME,
      showDatetime: "bottom",
    },
    {
      variant: "profile",
      title: "标题",
      description: DESC_LINKED,
      datetime: DATETIME,
      showDatetime: "bottom",
      avatar: avatarUrls[0],
    },
    {
      variant: "regular",
      title: "标题",
      description: descWithExtra(PRODUCT_ROW),
      datetime: DATETIME,
      showDatetime: "bottom",
    },
    {
      variant: "badge",
      title: "标题",
      description: descWithExtra(RATING),
      datetime: DATETIME,
      showDatetime: "bottom",
      icon: <CheckCircleBold size={20} color="currentColor" />,
    },
    {
      variant: "profile",
      title: "标题",
      description: descWithExtra(TASK_ROW),
      datetime: DATETIME,
      showDatetime: "bottom",
      avatar: avatarUrls[1],
    },
    {
      variant: "regular",
      title: "标题",
      description: DESC_SIMPLE,
      datetime: DATETIME,
      showDatetime: "bottom",
    },
  ];

  if (kind === "short") return base.slice(0, 3);
  if (kind === "mixed") return base.slice(0, 6);
  return base.slice(0, 5);
}

