/* eslint-disable @next/next/no-img-element */
import { type ReactNode } from "react";
import { AltArrowUpBold, AltArrowDownBold } from "../../icons";
import { cn } from "../../lib/utils";
import {
  CircleIcon,
  type CircleIconColor,
  type CircleIconSize,
  type CircleIconVariant,
} from "./badge";
import { Avatar, type AvatarSize } from "./avatar";
import { SwipeRow } from "../../internal/swipe-row";
import type { MotionPreference } from "../../lib/motion";

export type ListItemIconLead = {
  kind: "icon";
  icon: ReactNode;
  color?: CircleIconColor;
  variant?: CircleIconVariant;
  size?: CircleIconSize;
};

export type ListItemAvatarLead = {
  kind: "avatar";
  src?: string;
  initials?: string;
  alt?: string;
  online?: boolean;
  size?: AvatarSize;
};

// Square image lead — Figma "Square Img" 类型，w-11 h-11 rounded-lg
export type ListItemImageLead = {
  kind: "image";
  src: string;
  alt?: string;
};

export type ListItemLead =
  | ListItemIconLead
  | ListItemAvatarLead
  | ListItemImageLead;

export function ListItem({
  lead,
  title,
  subtitle,
  value,
  trend,
  trendDirection = "up",
  tailSubtext,
  trailing,
  className,
  onSwipeAction, swipeActionLabel = "删除", motion = "auto",
}: {
  lead?: ListItemLead;
  title: string;
  subtitle?: string;
  value?: string;
  trend?: string;
  trendDirection?: "up" | "down";
  tailSubtext?: string;
  trailing?: ReactNode;
  className?: string;
  onSwipeAction?: () => void;
  swipeActionLabel?: string;
  motion?: MotionPreference;
}) {
  const content = (
    <div className={cn("inline-flex items-center gap-2 w-full", className)}>
