"use client";

import {
  MapCard,
  type MapVariant,
  type MapRegion,
  type AccentColor,
} from "@forge-ui-official/core";
import { PageHeading, Section, SubSection, Labeled } from "../_shared";

const mapColors: AccentColor[] = ["purple", "blue", "black"];

const demoRegions: MapRegion[] = [
  { name: "美国", flag: "https://flagcdn.com/w80/us.png", salesLabel: "340 Sales", value: "$17,678" },
  { name: "德国", flag: "https://flagcdn.com/w80/de.png", salesLabel: "220 Sales", value: "$11,420" },
  { name: "印度尼西亚", flag: "https://flagcdn.com/w80/id.png", salesLabel: "180 Sales", value: "$9,210" },
  { name: "法国", flag: "https://flagcdn.com/w80/fr.png", salesLabel: "售出 140 件", value: "$7,450" },
  { name: "西班牙", flag: "https://flagcdn.com/w80/es.png", salesLabel: "98 Sales", value: "$5,120" },
];

export default function MapCasePage() {
  return (
    <div className="flex flex-col gap-10">
      <PageHeading
        title="地图"
        hint="在世界地图上高亮区域，并展示对应的统计数据。"
      />

      {/* ============ Variants × Colors ============ */}
      <Section
        title="Variants (sm / md)"
        description="紧凑版和中号控制内部地图高度；宽度默认填满父级列。3 色全铺。"
      >
        {(["sm", "md"] as MapVariant[]).map((v) => (
          <SubSection key={v} title={`Variant: ${v}`} >
            {mapColors.map((c) => (
              <Labeled key={c} label={c}>
                <MapCard
                  variant={v}
                  color={c}
                  title="主要地区"
                  subtitle="按地区统计销售额"
                  regions={v === "sm" ? demoRegions : demoRegions.slice(0, 4)}
                  highlights={["north-america", "oceania"]}
                  onMenuClick={() => {}}
                />
              </Labeled>
            ))}
          </SubSection>
        ))}
      </Section>

      {/* ============ Large variant (full-width with search) ============ */}
      <Section
        title="Variant: lg"
        description="整页大地图 + 右上浮层搜索面板，3 色。"
      >
        {mapColors.map((c) => (
          <SubSection key={c} title={`Color: ${c}`} >
            <MapCard
              variant="lg"
              color={c}
              title="全球销售额"
              subtitle="本月表现最佳的地区"
              regions={demoRegions}
              highlights={["north-america", "europe", "asia"]}
              onMenuClick={() => {}}
            />
          </SubSection>
        ))}
      </Section>

      {/* ============ Highlights variations ============ */}
      <Section
        title="重点区域"
        description="highlights prop 按大洲组合高亮——可自由挑几个大洲着色。"
      >
        <SubSection title="Different continent combos (purple, sm)" >
          <Labeled label="仅美洲">
            <MapCard
              variant="sm"
              color="blue"
              regions={demoRegions.slice(0, 3)}
              highlights={["north-america", "south-america"]}
            />
          </Labeled>
          <Labeled label="欧洲与亚洲">
            <MapCard
              variant="sm"
              color="blue"
              regions={demoRegions.slice(0, 3)}
              highlights={["europe", "asia"]}
            />
          </Labeled>
          <Labeled label="全部地区">
            <MapCard
              variant="sm"
              color="blue"
              regions={demoRegions.slice(0, 3)}
              highlights={[
                "north-america",
                "south-america",
                "europe",
                "africa",
                "asia",
                "oceania",
              ]}
            />
          </Labeled>
        </SubSection>
      </Section>
    </div>
  );
}

