}

import type { MotionPreference } from "../../lib/motion";
/* eslint-disable @next/next/no-img-element */
import { type ReactNode } from "react";
import { AltArrowDownLinear } from "../../icons";
import { cn } from "../../lib/utils";
import { accentColors, type AccentColor } from "./accent-utils";

export type MenuItemAccent = AccentColor;
export type MenuItemSurface = "default" | "onColoredBg";
export type MenuItemIntent = "default" | "danger";
export type MenuItemKind = "single" | "submenu" | "dropdown";
export type MenuItemState = "idle" | "hover" | "active" | "disabled";

export type MenuItemLead =
  | { kind: "icon"; icon: ReactNode }
  | { kind: "image"; src: string; alt?: string };

export function MenuItem({
  accent = "blue",
  surface = "default",
  intent = "default",
  kind = "single",
  state = "idle",
  active,
  lead,
  label,
  badge,
  href,
  ariaLabel,
  expanded,
  className,
  motion = "auto",
  onClick,
}: {
  accent?: MenuItemAccent;
  surface?: MenuItemSurface;
  intent?: MenuItemIntent;
  kind?: MenuItemKind;
  state?: MenuItemState;
  /** shortcut for state='active' */
  active?: boolean;
  lead?: MenuItemLead;
  label?: string;
  badge?: number;
  href?: string;
  ariaLabel?: string;
  expanded?: boolean;
  className?: string;
  motion?: MotionPreference;
  onClick?: () => void;
}) {
  const resolvedState = active ? "active" : state;
  const accentTheme = accentColors[accent];
  const hasText = label !== undefined && label !== "";
  const showLead = kind !== "submenu" && lead !== undefined;
  const showBadge = badge !== undefined && badge > 0;
  const showSubmenuArrow = kind === "dropdown" && hasText;
  const showLeftLine =
    resolvedState === "active" && (kind === "dropdown" || kind === "submenu" || kind === "single");

  // Padding: icon-only gets p-3; labeled row gets px-3.5 py-3
  const basePadding = hasText ? "px-3.5 py-3" : "p-3";
  const submenuPadding = hasText ? "pl-11 pr-3.5 py-3.5" : "p-3";

  // Colors — by surface × state × intent
  const stateClass = (() => {
    if (intent === "danger") {
      // Danger items: red text on default surface; on colored bg falls back to white
      if (surface === "onColoredBg") {
        return resolvedState === "active"
          ? "bg-white/25 text-white font-bold"
          : resolvedState === "hover"
            ? "bg-white/10 text-white"
            : resolvedState === "disabled"
              ? "text-white/40 cursor-not-allowed"
              : "text-white/75 hover:bg-white/10";
      }
      return resolvedState === "active"
        ? cn(accentTheme.bg, "text-white")
        : resolvedState === "hover"
          ? "bg-fg-red-50 text-fg-red"
          : resolvedState === "disabled"
            ? "text-fg-red/40 cursor-not-allowed"
            : "text-fg-red hover:bg-fg-red-50";
    }

    if (surface === "onColoredBg") {
      return resolvedState === "active"
        ? "bg-white/25 text-white font-bold"
        : resolvedState === "hover"
          ? "bg-white/10 text-white"
          : resolvedState === "disabled"
            ? "text-white/40 cursor-not-allowed"
            : "text-white/75 hover:bg-white/10";
    }

    // default surface
    return resolvedState === "active"
      ? cn(accentTheme.bg, "text-white")
      : resolvedState === "hover"
        ? "bg-fg-grey-200 text-fg-grey-700"
        : resolvedState === "disabled"
          ? "text-fg-grey-300 cursor-not-allowed"
          : "text-fg-grey-700 hover:bg-fg-grey-200";
  })();

  const labelWeight = resolvedState === "active" ? "font-bold" : "font-semibold";

  const content = (
    <>
      {showLeftLine && (
        <span
          aria-hidden
          className={cn(
            "absolute left-[-16px] top-0 w-1 h-12 rounded-tr-lg rounded-br-lg",
            surface === "onColoredBg" ? "bg-white" : accentTheme.bg
          )}
        />
      )}

      {showLead && lead && (
        <span className="w-6 h-6 flex items-center justify-center shrink-0">
          {lead.kind === "icon" ? (
            lead.icon
          ) : (
            <img
              src={lead.src}
              alt={lead.alt ?? ""}
              className="w-5 h-5 rounded-full object-cover"
            />
          )}
        </span>
      )}

      {hasText && (
        <span
          className={cn(
            "flex-1 text-left text-sm leading-5 tracking-fg line-clamp-1",
            labelWeight
          )}
        >
          {label}
        </span>
      )}

      {showBadge && (
        <span
          aria-label={`${badge} 条未读`}
          className={cn(
            "rounded-full bg-fg-red text-white text-[10px] font-semibold leading-4 tracking-fg px-1.5 py-0.5",
            !hasText && "absolute top-1 right-1"
          )}
        >
          {badge}
        </span>
      )}

      {showSubmenuArrow && (
        <span
          aria-hidden
          data-motion={motion}
          data-expanded={expanded}
          className={cn(
            "forge-chevron w-6 h-6 flex items-center justify-center shrink-0",

            resolvedState === "active"
              ? "text-white"
              : surface === "onColoredBg"
                ? "text-white/75"
                : "text-fg-grey-700"
          )}
        >
          <AltArrowDownLinear size={16} />
        </span>
      )}
    </>
  );

  const interactiveClassName = cn(
    "forge-menu-item relative rounded-full inline-flex items-center gap-2",
    hasText && "w-full",
    kind === "submenu" ? submenuPadding : basePadding,
    stateClass,
    className,
  );

  if (href && resolvedState !== "disabled") {
    return (
      <a
        data-motion={motion}
        href={href}
        aria-label={ariaLabel}
        aria-current={resolvedState === "active" ? "page" : undefined}
        onClick={onClick}
        className={interactiveClassName}
      >
        {content}
      </a>
    );
  }

  return (
    <button
      data-motion={motion}
      type="button"
      aria-label={ariaLabel}
      aria-expanded={kind === "dropdown" ? expanded : undefined}
      onClick={onClick}
      disabled={resolvedState === "disabled"}
      className={interactiveClassName}
    >
      {content}
    </button>
  );
}

import { cn } from "../../../lib/utils";
import { TrendText, rampColors } from "./chart-utils";
import { type AccentColor } from "../accent-utils";

interface MeterSegment {
  value: number;
  color?: string;
}

interface MeterChartProps {
  segments: MeterSegment[];
  accent?: AccentColor;
  trend?: string;
  trendDirection?: "up" | "down";
  subtitle?: string;
  /** Meter bar height class. Default h-24 (96px) per figma. */
  height?: string;
}

export function MeterChart({
  segments,
  accent = "blue",
  trend,
  trendDirection,
  subtitle,
  height = "h-24",
}: MeterChartProps) {
  const rampFallback = rampColors(accent, segments.length);
  const total = segments.reduce((sum, s) => sum + s.value, 0);
  // When values sum to ≤100, treat as absolute percent (leave remainder as grey track).
  // When sum > 100, normalize so segments fill the full bar.
  const useNormalized = total > 100;

  return (
    <div className="flex w-full flex-col gap-2">
      <div className={cn("flex w-full overflow-hidden rounded-xl", height)}>
        {segments.map((segment, i) => {
          const pct = total > 0
            ? useNormalized
              ? (segment.value / total) * 100
              : segment.value
            : 0;
          return (
            <div
              key={i}
              className={cn(
                "flex items-center justify-center overflow-hidden px-1 text-center text-sm font-bold leading-5 tracking-fg text-white line-clamp-1",
                segment.color ?? rampFallback[i],
              )}
              style={{ width: `${pct}%` }}
            >
              {pct >= 8 && `${Math.round(pct)}%`}
            </div>
          );
        })}
        {!useNormalized && total < 100 && <div className="flex-1 bg-fg-grey-200" />}
      </div>
      {(subtitle || trend) && (
        <div className="flex items-center justify-between">
          {subtitle && (
            <span className="flex-1 text-sm font-medium leading-5 tracking-fg text-fg-grey-700">
              {subtitle}
            </span>
          )}
          {trend && <TrendText trend={trend} trendDirection={trendDirection} />}
        </div>
      )}
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import type { MotionPreference } from "../../lib/motion";
import { DialogSurface } from "../../internal/dialog-surface";
import { CloseCircleLinear } from "../../icons";
import { IconButton } from "./icon-button";
import { Button } from "./button";
import { CloseIcon } from "./plain-icons";

export interface ModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  ariaLabel?: string;
  variant?: "default" | "template";
  width?: string;
  children: ReactNode;
  footer?: ReactNode;
  motion?: MotionPreference;
  locale?: "zh" | "en";
  closeLabel?: string;
  className?: string;
}

export function Modal({ open, onOpenChange, title, ariaLabel, variant = "default", width = "w-[560px]", children, footer, motion = "auto", locale = "zh", closeLabel, className }: ModalProps) {
  const label = title || ariaLabel || (locale === "zh" ? "弹窗" : "Dialog");
  if (variant === "template") {
    if (!open) return null;
    return <DialogSurface open={open} onOpenChange={onOpenChange} label={label} motion="none" appearance="template" className={`${width} ${className ?? ""}`}>
      <div className="overflow-hidden flex flex-col">
        {title && <>
          <div className="flex items-center justify-between pt-6 px-6">
            <h3 className="text-xl font-semibold text-fg-black leading-8 tracking-fg">{title}</h3>
            <Button variant="unstyled" aria-label={closeLabel ?? (locale === "zh" ? "关闭弹窗" : "Close dialog")} onClick={() => onOpenChange(false)} className="w-7 h-7 flex items-center justify-center bg-transparent cursor-pointer text-fg-black"><CloseIcon size={20} /></Button>
          </div>
          <div className="h-px w-full bg-fg-grey-200 mt-6" />
        </>}
        {children}
        {footer}
      </div>
    </DialogSurface>;
  }
  return <DialogSurface open={open} onOpenChange={onOpenChange} label={label} motion={motion} className={className}>
    <div className="flex flex-col gap-6 p-6">
      <div className="flex items-center justify-between gap-4"><h2 className="text-xl font-semibold">{title}</h2><IconButton variant="ghost" size="sm" motion={motion} aria-label={closeLabel ?? (locale === "zh" ? "关闭弹窗" : "Close dialog")} onClick={() => onOpenChange(false)}><CloseCircleLinear size={20} /></IconButton></div>
      <div>{children}</div>
      {footer && <div className="flex flex-wrap justify-end gap-3">{footer}</div>}
    </div>
  </DialogSurface>;
}

