  md: "w-9 h-9 p-2",
  sm: "w-8 h-8 p-1.5",
  xs: "w-6 h-6 p-1",
} as const;

const circleIconVariants = {
  solid: {
    purple: { bg: "bg-fg-violet", icon: "text-white" },
    blue: { bg: "bg-fg-blue", icon: "text-white" },
