// ============================================================
const artisticShells = {
  black: "bg-fg-black",
  blue: "bg-fg-blue",
  purple: "bg-fg-violet",
  green: "bg-fg-green-500",
  red: "bg-fg-red",
  yellow: "bg-fg-yellow",
  cyan: "bg-fg-cyan-500",
} as const;

