          ))}
        </SubSection>
      </Section>

      {/* ============ ArtisticIcon ============ */}
      <Section title="Artistic Icon" description="渐变 / 发光装饰圆形图标，7 色 × 2 variant。">
        <SubSection title="Variants (blue)">
          {artisticVariants.map((v) => (
            <Labeled key={v} label={v}>
