          ))}
        </SubSection>

        <SubSection title="Colors (orbs)">
          {artisticColors.map((c) => (
            <Labeled key={c} label={c}>
              <ArtisticIcon color={c} variant="orbs">
                <DemoGlyph size={24} color="#FFFFFF" />
              </ArtisticIcon>
            </Labeled>
          ))}
        </SubSection>
      </Section>
    </div>
  );
}

