// ── ToolbarSearchInput ──────────────────────────────────────

export function ToolbarSearchInput({
  placeholder = "搜索...",
  value,
  defaultValue,
  onChange,
  onSubmit,
  ariaLabel,
  className,
}: {
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  onSubmit?: (value: string) => void;
  ariaLabel?: string;
  className?: string;
}) {
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <form
      role="search"
      onSubmit={(event) => {
        event.preventDefault();
