// ── ToolbarPillTabs ─────────────────────────────────────────
// Pill-style tab group used in Toolbar rows (not to be confused with
// TabBar which renders an underlined bar). Active pill adopts the
// toolbar color; inactive pills stay grey.

export interface ToolbarPillTab {
  label: string;
  active?: boolean;
}

export function ToolbarPillTabs({
  tabs,
  color = "blue",
  onChange,
  className,
  motion = "auto",
}: {
  tabs: ToolbarPillTab[];
  color?: ToolbarColor;
  onChange?: (index: number) => void;
  className?: string;
  motion?: MotionPreference;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const activeIndex = tabs.findIndex((tab) => tab.active);
  const indicator = useMovingIndicator(rootRef, "[aria-pressed='true']", activeIndex);
  return (
    <div ref={rootRef} data-motion={motion}
      className={cn(
        "relative isolate inline-flex max-w-full items-start justify-start overflow-x-auto rounded-full bg-white p-1 outline outline-1 outline-offset-[-1px] outline-fg-grey-200",
        className,
      )}
    >
      <span ref={indicator} aria-hidden className={cn("forge-moving-indicator forge-pill-indicator rounded-full", toolbarPillActive[color])} />
      {tabs.map((tab, index) => (
        <button
          key={index}
          type="button"
          aria-pressed={!!tab.active}
          onClick={() => onChange?.(index)}
          className={cn(
            "relative z-[1] flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-full px-3.5 py-2.5 text-sm leading-5 tracking-fg",
            tab.active
              ? cn(toolbarPillActive[color].split(" ").filter((value) => !value.startsWith("bg-")).join(" "), "font-bold")
              : "text-fg-grey-700 font-semibold",
          )}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}

// ── PageTitleToolbar ────────────────────────────────────────

export type PageTitleToolbarVariant = "overview" | "collection" | "detail" | "action";

export interface PageTitleToolbarAction {
  label: string;
  icon?: ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  form?: string;
  ariaLabel?: string;
  testId?: string;
}

export interface PageTitleToolbarDateAction {
  label?: string;
  onClick?: () => void;
  enablePopover?: boolean;
}

export interface PageTitleToolbarMenuAction {
  onClick?: () => void;
  ariaLabel?: string;
}

interface PageTitleToolbarPresetBase {
  /** Optional Ask AI action, with the same configuration as PageHeader. */
  askAi?: AskAiProps;
  title: string;
  breadcrumbItems: BreadcrumbItem[];
  color?: ToolbarColor;
}

interface PageTitleToolbarOverviewProps extends PageTitleToolbarPresetBase {
  variant: "overview";
  subtitle?: string;
  dateAction?: PageTitleToolbarDateAction;
  primaryAction?: PageTitleToolbarAction;
  secondaryAction?: never;
  menuAction?: never;
}

interface PageTitleToolbarCollectionProps extends PageTitleToolbarPresetBase {
  variant: "collection";
  subtitle?: string;
  dateAction?: PageTitleToolbarDateAction;
  secondaryAction?: PageTitleToolbarAction;
  primaryAction?: PageTitleToolbarAction;
  menuAction?: never;
}

interface PageTitleToolbarDetailProps extends PageTitleToolbarPresetBase {
  variant: "detail";
  subtitle?: string;
  dateAction?: never;
  menuAction?: PageTitleToolbarMenuAction;
  secondaryAction?: PageTitleToolbarAction;
  primaryAction?: PageTitleToolbarAction;
}

interface PageTitleToolbarActionProps extends PageTitleToolbarPresetBase {
  variant: "action";
  subtitle?: never;
  dateAction?: never;
  menuAction?: never;
  secondaryAction: PageTitleToolbarAction;
  primaryAction: PageTitleToolbarAction;
}

export type PageTitleToolbarPresetProps =
  | PageTitleToolbarOverviewProps
  | PageTitleToolbarCollectionProps
  | PageTitleToolbarDetailProps
  | PageTitleToolbarActionProps;

interface PageTitleToolbarLegacyProps {
  /** Optional Ask AI action, with the same configuration as PageHeader. */
  askAi?: AskAiProps;
  /** @deprecated Use a fixed `variant` with `breadcrumbItems` and typed actions. */
  variant?: never;
  title: string;
  subtitle?: string;
  breadcrumbs?: ReactNode;
  actions?: ReactNode;
  className?: string;
}

export type PageTitleToolbarProps = PageTitleToolbarPresetProps | PageTitleToolbarLegacyProps;

export function PageTitleToolbar(props: PageTitleToolbarProps) {
  if (props.variant) {
    const {
      variant,
      title,
      subtitle,
      breadcrumbItems,
      color = "blue",
      dateAction,
      menuAction,
      secondaryAction,
      primaryAction,
      askAi,
    } = props;
    const hasActions = Boolean(askAi || dateAction || menuAction || secondaryAction || primaryAction);

    return (
      <PageTitleToolbarFrame
        title={title}
        subtitle={subtitle}
        breadcrumbs={
          <Breadcrumbs
            items={breadcrumbItems}
            color={color}
            className="flex-wrap gap-y-1 [&>span]:whitespace-nowrap"
          />
        }
        actions={hasActions ? (
          <ToolbarActions className="w-full flex-wrap sm:w-auto sm:shrink-0">
            {askAi && <AskAi {...askAi} />}
            {dateAction ? (
              <ToolbarDatepicker
                label={dateAction.label}
                onClick={dateAction.onClick}
                enablePopover={dateAction.enablePopover}
              />
            ) : null}
            {menuAction ? (
              <ToolbarKebabButton
                onClick={menuAction.onClick}
                ariaLabel={menuAction.ariaLabel}
              />
            ) : null}
            {secondaryAction ? (
              <PageTitleActionButton action={secondaryAction} color="grey" variant="tertiary" />
            ) : null}
            {primaryAction ? (
              <PageTitleActionButton action={primaryAction} color={color} variant="primary" />
            ) : null}
          </ToolbarActions>
        ) : undefined}
        className="flex-col items-stretch gap-3 sm:flex-row sm:items-end sm:gap-4 [&>div:first-child]:min-w-0 [&>div:first-child]:w-full"
        variant={variant}
      />
    );
  }

  const { title, subtitle, breadcrumbs, actions, className, askAi } = props;

  return (
    <PageTitleToolbarFrame
      title={title}
      subtitle={subtitle}
      breadcrumbs={breadcrumbs}
      actions={askAi ? <ToolbarActions><AskAi {...askAi} />{actions}</ToolbarActions> : actions}
      className={className}
    />
  );
}

function PageTitleActionButton({
  action,
  color,
  variant,
}: {
  action: PageTitleToolbarAction;
  color: ToolbarColor | "grey";
  variant: "primary" | "tertiary";
}) {
  return (
    <Button
      color={color}
      variant={variant}
      size="lg"
      iconLeft={action.icon}
      onClick={action.onClick}
      disabled={action.disabled}
      type={action.type}
      form={action.form}
      aria-label={action.ariaLabel}
      data-testid={action.testId}
    >
      {action.label}
    </Button>
  );
}

function PageTitleToolbarFrame({
  title,
  subtitle,
  breadcrumbs,
  actions,
  className,
  variant,
}: {
  title: string;
  subtitle?: string;
  breadcrumbs?: ReactNode;
  actions?: ReactNode;
  className?: string;
  variant?: PageTitleToolbarVariant;
}) {
  const hasSubContent = subtitle || breadcrumbs;

  return (
    <div
      data-forge-page-title-variant={variant}
      className={cn(
        "flex w-full self-stretch justify-start items-end gap-4",
        !hasSubContent && "items-center",
        className,
      )}
    >
      <div className="flex-1 inline-flex flex-col justify-start items-start gap-2">
        <h1 className="self-stretch justify-start text-fg-black text-2xl font-semibold leading-8 tracking-fg">
          {title}
        </h1>
        {subtitle && (
          <div className="self-stretch justify-start text-fg-grey-700 text-sm font-medium leading-5 tracking-fg">
            {subtitle}
          </div>
        )}
        {breadcrumbs}
      </div>
      {actions}
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import { motion as animated } from "motion/react";
import { cn } from "../../lib/utils";
import type { MotionPreference } from "../../lib/motion";
import { useMovingIndicator, useReducedMotion } from "../../internal/motion";
import { AltArrowLeftLinear, AltArrowRightLinear } from "../../icons";
import { PageDot, type PageDotColor } from "./page-dot";

// ============================================================
// Pagination - 分页器
// 复合组件：prev/next + PageDot 数字 + ellipsis
// color: purple, blue, black（继承自 PageDot）
// ============================================================

export type PaginationColor = PageDotColor;

const activeColors = { purple: "bg-fg-violet", blue: "bg-fg-blue", black: "bg-fg-black" } as const;

// Figma pattern: active 起头向后展开 5 个页码窗口，左右按需 ellipsis，不强制 first/last
function getPageNumbers(totalPages: number, currentPage: number, visible = 5): (number | "...")[] {
  const clamped = Math.min(totalPages, Math.max(1, currentPage));
  const end = Math.min(totalPages, clamped + visible - 1);

  const pages: (number | "...")[] = [];
  if (clamped > 1) pages.push("...");
  for (let i = clamped; i <= end; i++) pages.push(i);
  if (end < totalPages) pages.push("...");
  return pages;
}

export function Pagination({
  totalPages,
  currentPage,
  onPageChange,
  color = "blue",
  className,
  locale = "zh",
  motion = "auto",
}: {
  totalPages: number;
  currentPage: number;
  onPageChange?: (page: number) => void;
  color?: PaginationColor;
  className?: string;
  /** 无障碍标签的语言，默认中文。 */
  locale?: "zh" | "en";
  /** auto 跟随系统的减弱动效设置。 */
  motion?: MotionPreference;
}) {
  const root = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(5);
  const reduced = useReducedMotion(motion);
  const pages = getPageNumbers(totalPages, currentPage, visible);
  const indicator = useMovingIndicator(root, "[aria-current='page']", `${totalPages}:${currentPage}:${visible}`);
  const zh = locale === "zh";
  const activeIndex = pages.indexOf(currentPage);

  useLayoutEffect(() => {
    const parent = root.current?.parentElement;
    if (!parent) return;
    function fit() {
      if (!parent) return;
      const style = window.getComputedStyle(parent);
      const available = parent.clientWidth - (Number.parseFloat(style.paddingLeft) || 0) - (Number.parseFloat(style.paddingRight) || 0);
      if (available <= 0) return;
      let count = 5;
      // Keep PageDot's 40px hit area and 8px spacing. Observe the parent so
      // changing the number of pages cannot trigger a resize feedback loop.
      while (count > 1) {
        const slots = getPageNumbers(totalPages, currentPage, count).length + 2;
        if (slots * 40 + (slots - 1) * 8 <= available) break;
        count--;
      }
      setVisible(previous => previous === count ? previous : count);
    }
    fit();
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(fit);
    observer?.observe(parent);
    window.addEventListener("resize", fit);
    return () => { observer?.disconnect(); window.removeEventListener("resize", fit); };
  }, [totalPages, currentPage]);

  return (
    <div ref={root} role="navigation" aria-label={zh ? "分页" : "Pagination"} data-motion={reduced ? "none" : motion}
      className={cn("relative isolate flex w-full min-w-0 max-w-full items-center gap-2 overflow-x-auto", className)}>
      <span ref={indicator} aria-hidden className={cn("forge-moving-indicator rounded-full", activeColors[color])}
        style={{
          // A deterministic server fallback keeps the active page visible before hydration.
          // The shared observer then measures the actual button, including custom layout.
          "--forge-indicator-x": `${(activeIndex + 1) * 48}px`,
          "--forge-indicator-y": "0px",
          "--forge-indicator-width": "40px",
          "--forge-indicator-height": "40px",
          visibility: activeIndex < 0 ? "hidden" : "visible",
          transition: reduced ? "none" : "translate 420ms cubic-bezier(.22, 1, .36, 1)",
        } as CSSProperties} />
      <animated.button
        type="button"
        aria-label={zh ? "上一页" : "Previous page"}
        onClick={() => onPageChange?.(Math.max(1, currentPage - 1))}
        disabled={currentPage <= 1}
        whileTap={reduced || currentPage <= 1 ? undefined : { scale: .94 }}
        className="relative shrink-0 p-2.5 rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed text-fg-grey-700"
      >
        <AltArrowLeftLinear size={20} />
      </animated.button>

      {pages.map((page, i) =>
        page === "..." ? (
          <PageDot key={`ellipsis-${i}`} color={color} className="relative shrink-0">
            ...
          </PageDot>
        ) : (
          <animated.button
            key={page}
            type="button"
            aria-current={page === currentPage ? "page" : undefined}
            aria-label={zh ? `第 ${page} 页` : `Page ${page}`}
            onClick={() => onPageChange?.(page)}
            whileTap={reduced ? undefined : { scale: .94 }}
            className={cn("relative z-[1] w-10 h-10 p-2 rounded-full shrink-0 inline-flex items-center justify-center text-sm font-semibold cursor-pointer",
              page === currentPage ? "text-white" : "outline outline-1 outline-offset-[-1px] outline-fg-grey-200 text-fg-grey-700")}
          >
            {page}
          </animated.button>
        )
      )}

      <animated.button
        type="button"
        aria-label={zh ? "下一页" : "Next page"}
        onClick={() => onPageChange?.(Math.min(totalPages, currentPage + 1))}
        disabled={currentPage >= totalPages}
        whileTap={reduced || currentPage >= totalPages ? undefined : { scale: .94 }}
        className="relative shrink-0 p-2.5 rounded-full outline outline-1 outline-offset-[-1px] outline-fg-grey-200 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed text-fg-grey-700"
      >
        <AltArrowRightLinear size={20} />
      </animated.button>
    </div>
  );
}

