import { type ReactNode } from "react";
import { cn } from "../../lib/utils";
import { cardThemes, CardGlow, resolveCardTheme, resolveCardWidthClass, type CardTheme, type CardWidth, type LegacyCardTheme } from "./card-utils";

// ============================================================
// ProgressCard — Figma "Progress Card" (node 304:56383)
// Circular progress ring + breakdown legend.
// Uses cardThemes for bg/text/glow (8-color matrix).
// ============================================================

type ProgressCardTheme = CardTheme | LegacyCardTheme;

// Map from cardTheme bg to the "solid" bg class needed for the
// inner circle (the donut hole must match the card bg exactly).
const innerBgMap: Record<CardTheme, string> = {
  white: "bg-white",
  black: "bg-fg-black",
  purple: "bg-fg-violet",
  blue: "bg-fg-blue",
  green: "bg-fg-green-500",
  red: "bg-fg-red",
  yellow: "bg-fg-yellow",
  cyan: "bg-fg-cyan-500",
};

export function ProgressCard({
  title,
  value,
  subtitle,
  theme = "white",
  progress,
  progressColor,
  items,
  action,
  width,
  className,
}: {
  title: string;
  value: string;
  subtitle: string;
  theme?: ProgressCardTheme;
  /** 0-100 */
  progress: number;
  /** CSS color for the conic-gradient fill (e.g. "var(--fg-violet)") */
  progressColor: string;
  items: { label: string; value: string; color: string }[];
  action?: ReactNode;
  /** Use full to fill dashboard/grid columns. Use fixed only for Figma-size showcases. */
  width?: CardWidth;
  className?: string;
}) {
  const themeKey = resolveCardTheme(theme);
  const cfg = cardThemes[themeKey];
  const isWhite = themeKey === "white";
  const trackColor = isWhite ? "var(--fg-grey-200)" : "rgba(255,255,255,0.2)";

  return (
    <div
      className={cn(
        "p-5 rounded-card flex-col gap-5 overflow-hidden relative",
        resolveCardWidthClass(width, "w-80"),
        cfg.bg,
        className,
      )}
    >
      <CardGlow theme={cfg} />

      <div className="flex items-center justify-between relative z-10">
        <span className={cn("text-sm font-medium leading-5 tracking-fg", cfg.titleColor)}>{title}</span>
        {action && <div className="shrink-0">{action}</div>}
      </div>

      <div className="flex items-center justify-center relative z-10">
        <div className="relative w-40 h-40">
          <div
            className="w-full h-full rounded-full"
            style={{ background: `conic-gradient(${progressColor} ${progress * 3.6}deg, ${trackColor} ${progress * 3.6}deg)` }}
          />
          <div className={cn("absolute inset-3 rounded-full flex flex-col items-center justify-center", innerBgMap[themeKey])}>
            <span className={cn("text-display-l font-semibold tracking-fg", cfg.valueColor)}>{value}</span>
            <span className={cn("text-sm leading-5", cfg.titleColor)}>{subtitle}</span>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-2 relative z-10">
        {items.map((item, i) => (
          <div key={`${item.label}-${i}`} className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: item.color }} />
              <span className={cn("text-sm leading-5", cfg.titleColor)}>{item.label}</span>
            </div>
            <span className={cn("text-sm font-medium leading-5", cfg.valueColor)}>{item.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { cn } from "../../lib/utils";
import type { MotionPreference } from "../../lib/motion";
import type { ReactNode } from "react";

// ============================================================
// ProgressBar
//   color         — 8 hues, aligned to Figma fg-* primitive ramp
//   size          — sm (h-2) / md (h-3)
//   label         — optional text left of percentage
//   labelVariant  — "default" (grey medium, e.g. "Progress")
//                   "value"   (black semibold, e.g. "$400")
//   labelSize     — "xs" (text-xs) / "sm" (text-sm)
//   showPercentage
//   onDark        — render on dark surface: translucent track, white label/%
// ============================================================

const progressColors = {
  purple: "bg-fg-violet",        // Figma Purple 500
  blue:   "bg-fg-blue-500",      // Figma Blue 500
  green:  "bg-fg-green-500",     // Figma Green 500
  red:    "bg-fg-red",           // Figma Red 500
  orange: "bg-fg-red",           // alias → Figma uses orange-600 which is Red 500 hex
  yellow: "bg-fg-yellow",        // Figma Yellow 500
  cyan:   "bg-fg-cyan-500",      // Figma Cyan 500
  gray:   "bg-fg-grey-700",
  black: "bg-fg-black",
} as const;

const progressTextColors = {
  purple: "text-fg-violet",
  blue:   "text-fg-blue-500",
  green:  "text-fg-green-500",
  red:    "text-fg-red",
  orange: "text-fg-red",
  yellow: "text-fg-yellow",
  cyan:   "text-fg-cyan-500",
  gray:   "text-fg-grey-700",
  black: "text-fg-black",
} as const;

const progressSizes = {
  sm: "h-2",
  md: "h-3",
} as const;

export type ProgressColor = keyof typeof progressColors;
export type ProgressSize = keyof typeof progressSizes;
export type ProgressLabelVariant = "default" | "value";
export type ProgressLabelSize = "xs" | "sm";

export function ProgressBar({
  value = 0,
  color = "blue",
  size = "sm",
  label,
  labelVariant = "default",
  labelSize = "sm",
  showPercentage = false,
  onDark = false,
  variant = "linear", indeterminate = false, motion = "auto", locale = "zh", children, className,
}: {
  value?: number;
  color?: ProgressColor;
  size?: ProgressSize;
  label?: string;
  labelVariant?: ProgressLabelVariant;
  labelSize?: ProgressLabelSize;
  showPercentage?: boolean;
  onDark?: boolean;
  variant?: "linear" | "ring";
  indeterminate?: boolean;
  motion?: MotionPreference;
  locale?: "zh" | "en";
  /** Content centered in a ring, such as a remaining-time label. */
  children?: ReactNode;
  className?: string;
}) {
  const clampedValue = Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 0;

  const labelTextSize = labelSize === "xs" ? "text-xs leading-4" : "text-sm leading-5";

  // Light mode: grey medium "Progress" / black semibold "$400".
  // Dark mode: both variants read as 75%-white with their own weight.
  const labelClass = onDark
    ? labelVariant === "value"
      ? "text-white/75 font-semibold"
      : "text-white/75 font-medium"
    : labelVariant === "value"
      ? "text-fg-black font-semibold"
      : "text-fg-grey-700 font-medium";

  // Figma keeps percentage color-matched in light mode, but switches to white on dark.
  const percentClass = onDark
    ? "text-white font-bold"
    : cn(progressTextColors[color], "font-bold");

  const trackClass = onDark ? "bg-fg-grey-200/25" : "bg-fg-grey-200";

  if (variant === "ring") return <div className={cn("forge-progress-ring", progressTextColors[color], className)} data-motion={motion} data-indeterminate={indeterminate || undefined} role="progressbar" aria-label={label ?? (locale === "en" ? "Progress" : "进度")} aria-valuemin={0} aria-valuemax={100} aria-valuenow={indeterminate ? undefined : clampedValue}>
    <svg viewBox="0 0 100 100" aria-hidden><circle className="forge-progress-ring-track" cx="50" cy="50" r="44" /><circle className="forge-progress-ring-fill" cx="50" cy="50" r="44" pathLength="100" strokeDasharray="100" strokeDashoffset={indeterminate ? 65 : 100 - clampedValue} /></svg>
    <span>{children ?? (showPercentage && !indeterminate ? `${clampedValue}%` : null)}</span>
  </div>;

  return (
    <div className={cn("forge-progress w-full flex flex-col justify-start items-start gap-2", className)} data-motion={motion} data-indeterminate={indeterminate || undefined}>
      {(label || showPercentage) && (
        <div className="self-stretch inline-flex justify-start items-start gap-2">
          {label && (
            <span className={cn("flex-1 tracking-fg", labelTextSize, labelClass)}>
              {label}
            </span>
          )}
          {showPercentage && !indeterminate && (
            <span className={cn("tracking-fg", labelTextSize, percentClass)}>
              {clampedValue}%
            </span>
          )}
        </div>
      )}
      <div
        role="progressbar"
        aria-label={label ?? (locale === "en" ? "Progress" : "进度")}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={indeterminate ? undefined : clampedValue}
        className={cn("self-stretch rounded-full overflow-hidden", progressSizes[size], trackClass)}
      >
        <div
          className={cn("forge-progress-fill rounded-full transition-all", progressSizes[size], progressColors[color])}
          style={{ width: indeterminate ? "35%" : `${clampedValue}%` }}
        />
      </div>
    </div>
  );
}

