                />
              </div>
            </Labeled>
          ))}
        </SubSection>
        <SubSection title="value label ($400 65%)" >
          {progressColors.map((c) => (
            <Labeled key={c} label={c}>
              <div className="w-64">
                <ProgressBar
                  value={65}
                  color={c}
                  label="$400"
                  labelVariant="value"
                  showPercentage
                />
              </div>
            </Labeled>
          ))}
        </SubSection>
      </Section>

      {/* ============ On Dark ============ */}
      <Section
        title="Progress Bar — On Dark"
        description="深色卡片背景上使用，track 半透明，label / % 变白。"
      >
        <SubSection title="深色背景" >
          {progressColors.map((c) => (
            <div key={c} className="p-5 bg-fg-black rounded-xl w-64">
              <ProgressBar
                value={65}
                color={c}
                label="进度"
                labelVariant="default"
                showPercentage
                onDark
              />
            </div>
          ))}
        </SubSection>
      </Section>

      {/* ============ Progress Values ============ */}
      <Section
        title="Progress Bar — Value Range"
        description="0 / 25 / 50 / 75 / 100 各档。"
      >
        <SubSection title="Purple, sm" >
          {[0, 25, 50, 75, 100].map((v) => (
            <Labeled key={v} label={`${v}%`}>
              <div className="w-64">
                <ProgressBar value={v} color="blue" showPercentage />
              </div>
            </Labeled>
          ))}
        </SubSection>
      </Section>
    </div>
  );
}

