import { cn } from "../../../lib/utils";
import { AltArrowDownLinear, CheckCircleLinear } from "../../../icons";
import { formAccents, type FormAccentColor } from "./form-utils";
import { FieldFrame, FieldTag } from "./field-utils";

// ============================================================
// SelectOption — from Figma "Select Option" page (node 605:104748)
// 1:1 replica of spec with all variants:
//   type: general | single | multiple | image
//   shape: rounded (corner-12) | pill (full-rounded)
//   color: purple | blue | black
//   state: idle | focus | disabled | error
//   bgVariant: white | grey
// ============================================================

export type SelectOptionState = "idle" | "focus" | "disabled" | "error";
export type SelectOptionShape = "rounded" | "pill";
export type SelectOptionColor = FormAccentColor;
export type SelectOptionType = "general" | "single" | "multiple" | "image";
export type SelectOptionBgVariant = "white" | "grey";

export interface SelectOptionItem {
  value: string;
  label: string;
  image?: string;
  /** 图标建议使用 Solar；image 类型传入 image 时优先显示图片。 */
  icon?: ReactNode;
  /** 菜单项与单选触发器中的辅助说明。 */
  description?: string;
}

// ── Option Item (dropdown row) ──────────────────────────────

function OptionItem({
  item,
  selected,
  color,
  isImage,
  onClick,
  reduced,
}: {
  item: SelectOptionItem;
  selected: boolean;
  color: SelectOptionColor;
  isImage?: boolean;
  onClick: () => void;
  reduced: boolean;
}) {
  const accent = formAccents[color];
  return (
    <button
      type="button"
      role="option"
      tabIndex={-1}
      aria-selected={selected}
      onClick={onClick}
      className={cn("flex w-full shrink-0 cursor-pointer items-center gap-2 px-4 text-left transition-colors hover:bg-fg-grey-100 outline-none", item.description ? "min-h-12 py-2" : "h-12 py-3")}
    >
      {isImage && item.image ? (
        /* eslint-disable-next-line @next/next/no-img-element */
        <img src={item.image} alt="" className="size-5 shrink-0 rounded-full object-cover" />
      ) : item.icon ? (
        <span aria-hidden className={cn("inline-flex size-5 shrink-0 items-center justify-center", selected ? accent.text : "text-fg-grey-700")}>{item.icon}</span>
      ) : null}
      <span className="min-w-0 flex-1 text-left">
        <span
          className={cn(
            "block truncate text-sm leading-5 tracking-fg",
            selected ? cn("font-bold", accent.text) : "font-semibold text-fg-grey-700",
          )}
        >{item.label}</span>
        {item.description && <span className="block whitespace-normal break-words text-xs font-normal leading-4 tracking-fg text-fg-grey-600">{item.description}</span>}
      </span>
      {/* Reserve the same check column for all rows. */}
      <span
        className={cn("inline-flex size-[22px] shrink-0 items-center justify-center", accent.text)}
        aria-hidden
        style={{ opacity: selected ? 1 : 0, scale: selected ? 1 : .65, transition: reduced ? "none" : "opacity 160ms ease, scale 320ms cubic-bezier(.34,1.16,.64,1)" }}
      >
        <CheckCircleLinear size={22} />
      </span>
    </button>
  );
}

// ── SelectOption (main) ─────────────────────────────────────

type BaseProps = {
  options: SelectOptionItem[];
  motion?: MotionPreference;
  placeholder?: string;
  label?: string;
  errorMessage?: string;
  state?: SelectOptionState;
  shape?: SelectOptionShape;
  color?: SelectOptionColor;
  type?: SelectOptionType;
  bgVariant?: SelectOptionBgVariant;
  /** Trigger width. Defaults: single=200px, multiple=248px. Accepts any CSS width (e.g. "320px", "100%"). */
  width?: string;
  className?: string;
  headerAction?: ReactNode;
};

type SingleProps = BaseProps & {
  type?: "general" | "single" | "image";
  value?: string;
  onChange?: (value: string) => void;
};

type MultipleProps = BaseProps & {
  type: "multiple";
  value?: string[];
  onChange?: (value: string[]) => void;
};

export type SelectOptionProps = SingleProps | MultipleProps;

