          ref={triggerRef}
          role="combobox"
          tabIndex={isDisabled ? -1 : 0}
          aria-expanded={isOpen}
          aria-controls={listboxId}
          aria-haspopup="listbox"
          aria-label={label ?? placeholder}
          aria-disabled={isDisabled}
          aria-invalid={isError}
          data-motion={effectiveMotion}
