        return;
      case "Tab":
        closeMenu();
        return;
      case "ArrowDown":
        nextIndex = (currentIndex + 1) % optionElements.length;
        break;
      case "ArrowUp":
        nextIndex = (currentIndex - 1 + optionElements.length) % optionElements.length;
