                  reduced={reduced}
                  isImage={isImage}
                  onClick={() => { if (isOpen) { if (isMultiple) toggleMultiple(option.value); else selectSingle(option.value); } }}
                />
              ))}
            </MotionMenu>
          </MotionPresence>
      </div>
    </FieldFrame>
  );
}

