"use client";

import { useId } from "react";
import { chartDomain, chartPoints, bandPath, stackedBounds, linePath } from "../../../internal/chart-geometry";
import { useAnimatedChartValues } from "../../../internal/animated-chart-values";
import type { MotionPreference } from "../../../lib/motion";
import { cn } from "../../../lib/utils";
import { ChartTooltip, type ChartTooltipItem } from "./chart-tooltip";
import { ChartTooltipPosition } from "../../../internal/chart-tooltip-position";
import { resolveColor, rampColors } from "./chart-utils";
import { type AccentColor } from "../accent-utils";

interface LineSeries {
  data: number[];
  /** Optional override. When omitted, derived from `accent` ramp. */
  color?: string;
  fillArea?: boolean;
  label?: string;
  /** Index at which the forecast becomes a dashed line. */
  forecastFrom?: number;
}

interface SmoothLineChartProps {
  series: LineSeries[];
  stacked?: boolean;
  bands?: { lower: number[]; upper: number[]; color?: string }[];
  motion?: MotionPreference;
  onActiveIndexChange?: (index: number | undefined) => void;
  ariaLabel?: string;
  interpolation?: "smooth" | "linear";
  highlightToActive?: boolean;
  markers?: { index: number; label: string }[];
  accent?: AccentColor;
  activeIndex?: number;
  showTooltip?: boolean;
  tooltipItems?: ChartTooltipItem[];
  showYAxis?: boolean;
  yAxisLabels?: string[];
  xAxisLabels?: string[];
  /** Optional [min, max] for y-axis. Default: auto from data. */
  yDomain?: [number, number];
  height?: string;
}

const VIEWBOX_W = 400;
const VIEWBOX_H = 120;

// Catmull-Rom → Cubic Bezier. /6 = standard uniform CR (tension 0.5), matches
// Figma's smooth wave shape.
const TENSION_DIVISOR = 6;
function smoothPath(points: [number, number][]): string {
  if (points.length < 2) return "";
  let d = `M ${points[0][0]} ${points[0][1]}`;
  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1] ?? points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] ?? p2;
    const cp1x = p1[0] + (p2[0] - p0[0]) / TENSION_DIVISOR;
    const cp1y = p1[1] + (p2[1] - p0[1]) / TENSION_DIVISOR;
    const cp2x = p2[0] - (p3[0] - p1[0]) / TENSION_DIVISOR;
    const cp2y = p2[1] - (p3[1] - p1[1]) / TENSION_DIVISOR;
    d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2[0]} ${p2[1]}`;
  }
  return d;
}

export function SmoothLineChart({
  series,
  stacked = false, bands = [], motion = "auto", onActiveIndexChange, ariaLabel = "趋势图", interpolation = "smooth", highlightToActive = false, markers = [],
  accent = "blue",
  activeIndex,
  showTooltip = false,
  tooltipItems,
  showYAxis = false,
  yAxisLabels,
  xAxisLabels,
  yDomain,
  height = "h-32",
}: SmoothLineChartProps) {
  const gradientId = useId();
  const animated = useAnimatedChartValues([...series.flatMap(s => s.data), ...bands.flatMap(b => [...b.lower, ...b.upper])], motion);
  const animatedSeries = series.map((s, index) => { const offset = series.slice(0, index).reduce((sum, previous) => sum + previous.data.length, 0); return { ...s, data: animated.slice(offset, offset + s.data.length) }; });
  const seriesLength = series.reduce((sum, s) => sum + s.data.length, 0);
  const animatedBands = bands.map((b, index) => { const offset = seriesLength + bands.slice(0, index).reduce((sum, previous) => sum + previous.lower.length + previous.upper.length, 0); return { ...b, lower: animated.slice(offset, offset + b.lower.length), upper: animated.slice(offset + b.lower.length, offset + b.lower.length + b.upper.length) }; });
  const bounds = stackedBounds(animatedSeries.map(s => s.data));
  const allValues = [...(stacked ? bounds.flatMap(b => [...b.lower, ...b.upper]) : animatedSeries.flatMap(s => s.data)), ...animatedBands.flatMap(b => [...b.lower, ...b.upper])];
  const autoMax = allValues.length > 0 ? Math.max(...allValues) : 1;
  const autoMin = allValues.length > 0 ? Math.min(...allValues) : 0;
  const [min, max] = chartDomain([autoMin, autoMax], yDomain);
  const rampFallback = rampColors(accent, series.length);

  const seriesGeometry = animatedSeries.map((s, i) => {
    const points = chartPoints(stacked ? bounds[i].upper : s.data, [min, max]);
    const linePath = interpolation === "linear" ? points.map(([x,y], j) => `${j ? "L" : "M"}${x},${y}`).join(" ") : smoothPath(points);
    const areaPath = stacked ? bandPath(points, chartPoints(bounds[i].lower, [min, max])) : points.length
      ? `${linePath} L ${points[points.length - 1][0]} ${VIEWBOX_H} L ${points[0][0]} ${VIEWBOX_H} Z`
      : "";
    return { points, linePath, areaPath, color: resolveColor(s.color ?? rampFallback[i]), fillArea: s.fillArea ?? true, forecastFrom: s.forecastFrom };
  });

  const primary = seriesGeometry[0];
  const markerPoint =
    activeIndex != null && primary?.points[activeIndex] ? primary.points[activeIndex] : null;

  const chartArea = (
    <div className={cn("relative w-full", height)} role={onActiveIndexChange ? "slider" : "img"} aria-label={ariaLabel} tabIndex={onActiveIndexChange ? 0 : undefined} aria-valuemin={onActiveIndexChange ? 0 : undefined} aria-valuemax={onActiveIndexChange ? Math.max(0, (primary?.points.length ?? 1) - 1) : undefined} aria-valuenow={onActiveIndexChange ? activeIndex ?? Math.max(0, (primary?.points.length ?? 1) - 1) : undefined}
      onPointerMove={event => { if (!onActiveIndexChange || !primary?.points.length) return; const rect = event.currentTarget.getBoundingClientRect(); onActiveIndexChange(Math.round(Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width)) * (primary.points.length - 1))); }}
      onPointerLeave={() => onActiveIndexChange?.(undefined)} onBlur={() => onActiveIndexChange?.(undefined)} onKeyDown={event => { if (!onActiveIndexChange || !primary?.points.length) return; const last = primary.points.length - 1, at = activeIndex ?? last; const next = event.key === "ArrowLeft" ? at - 1 : event.key === "ArrowRight" ? at + 1 : event.key === "Home" ? 0 : event.key === "End" ? last : undefined; if (event.key === "Escape") { onActiveIndexChange(undefined); return; } if (next === undefined) return; event.preventDefault(); onActiveIndexChange(Math.max(0, Math.min(last, next))); }}>
      <svg
        viewBox={`0 0 ${VIEWBOX_W} ${VIEWBOX_H}`}
        preserveAspectRatio="none"
        className="absolute inset-0 h-full w-full overflow-visible"
      >
        <defs>
          <clipPath id={`${gradientId}-active`}><rect x="0" y="-10" width={markerPoint?.[0] ?? VIEWBOX_W} height={VIEWBOX_H + 20} /></clipPath>
          {seriesGeometry.map((g, i) => (
            <linearGradient key={i} id={`${gradientId}-${i}`} x1="0" y1="0" x2="0" y2="1">
              {/* Figma: bg-gradient-to-b from-{color}/5 to-{color}/0 */}
              <stop offset="0%" stopColor={g.color} stopOpacity="0.05" />
              <stop offset="100%" stopColor={g.color} stopOpacity="0" />
            </linearGradient>
          ))}
        </defs>
        {animatedBands.map((band, i) => <path key={`band-${i}`} data-chart-band="true" d={bandPath(chartPoints(band.upper, [min,max]), chartPoints(band.lower, [min,max]))} fill={resolveColor(band.color ?? rampFallback[0])} fillOpacity=".15" />)}
        {seriesGeometry.map((g, i) => (
          <g key={i}>
            {g.fillArea && <path d={g.areaPath} fill={stacked ? g.color : `url(#${gradientId}-${i})`} fillOpacity={stacked ? .8 : undefined} clipPath={highlightToActive ? `url(#${gradientId}-active)` : undefined} />}
            {highlightToActive && <path d={g.linePath} stroke="var(--fg-grey-200)" strokeWidth="2" fill="none" vectorEffect="non-scaling-stroke" />}
            <path
              d={g.forecastFrom === undefined ? g.linePath : linePath(g.points.slice(0, g.forecastFrom + 1))}
              clipPath={highlightToActive ? `url(#${gradientId}-active)` : undefined}
              stroke={g.color}
              strokeWidth="2"
              fill="none"
              vectorEffect="non-scaling-stroke"
            />
            {g.forecastFrom !== undefined && <path d={linePath(g.points.slice(g.forecastFrom))} fill="none" stroke={g.color} strokeWidth="2" strokeDasharray="5 4" vectorEffect="non-scaling-stroke" />}
          </g>
        ))}
        {markers.map(marker => { const point = primary?.points[marker.index]; return point ? <circle key={`${marker.index}-${marker.label}`} cx={point[0]} cy={point[1]} r="3" fill="var(--fg-white)" stroke={primary.color} strokeWidth="2" vectorEffect="non-scaling-stroke"><title>{marker.label}</title></circle> : null; })}
      </svg>

      {markerPoint && showTooltip && (
        <>
          <div
            className="pointer-events-none absolute bottom-0 top-0 w-px -translate-x-1/2 rounded-sm bg-fg-grey-300"
            style={{ left: `${(markerPoint[0] / VIEWBOX_W) * 100}%` }}
          />
          <div
            className="absolute h-2.5 w-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white"
            style={{
              left: `${(markerPoint[0] / VIEWBOX_W) * 100}%`,
              top: `${(markerPoint[1] / VIEWBOX_H) * 100}%`,
              backgroundColor: primary.color,
            }}
          />
          {tooltipItems && tooltipItems.length > 0 && (
            <ChartTooltipPosition left={(markerPoint[0] / VIEWBOX_W) * 100} top={(markerPoint[1] / VIEWBOX_H) * 100}>
              <ChartTooltip items={tooltipItems} />
            </ChartTooltipPosition>
          )}
        </>
      )}
    </div>
  );

  if (!showYAxis && !xAxisLabels) return chartArea;

  return (
    <div className="flex w-full">
      {showYAxis && yAxisLabels && (
        <div className="mr-3 flex flex-col justify-between py-1">
          {yAxisLabels.map((label, i) => (
            <span key={i} className="text-right text-xs leading-4 tracking-fg text-fg-grey-500">
              {label}
            </span>
          ))}
        </div>
      )}
      <div className="flex min-w-0 flex-1 flex-col">
        <div className="relative">
          {showYAxis && yAxisLabels && (
            <div className="pointer-events-none absolute inset-0 flex flex-col justify-between">
              {yAxisLabels.map((_, i) => (
                <div key={i} className="border-t border-fg-grey-200" />
              ))}
            </div>
          )}
          {chartArea}
        </div>
        {xAxisLabels && (
          <div className="mt-2 flex justify-between">
            {xAxisLabels.map((label, i) => {
              const isActive = i === activeIndex;
              return (
                <span
                  key={i}
                  className={cn(
                    "text-xs leading-4 tracking-fg",
                    isActive ? "font-bold" : "text-fg-grey-500",
                  )}
                  style={isActive && primary ? { color: primary.color } : undefined}
                >
                  {label}
                </span>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

import type { CardDensity } from "./card-utils";
import { type ReactNode } from "react";
import { AnimatedNumber } from "../../internal/animated-number";
import type { MotionPreference } from "../../lib/motion";
import { cn } from "../../lib/utils";
import {
  cardThemes,
  statCardSizes,
  CardGlow,
  CardTrend,
  CardIconChip,
  CardKebabButton,
  resolveCardTheme,
  resolveCardWidthClass,
  type CardTheme,
  type CardBadgeVariant,
  type CardWidth,
  type TrendDirection,
  type StatCardSize,
} from "./card-utils";

// ============================================================
// StatCard — Figma "Regular Statistic Card" (node 657:107046)
// Variants:
//   size: sm (258×152) | lg (360×264) | wide (column-filling)
//   theme: 8 colors via card-utils
//   action: none | button | kebab (lg only — Figma "Action=Button / Kebab Menu")
//   icon (optional) — renders colored circle chip next to title (sm/lg)
//                     or in the top-right (wide)
// ============================================================

type LegacyTheme = "dark" | "orange";
type StatCardTheme = CardTheme | LegacyTheme;

export function StatCard({
  title,
  value,
  animateValue = false,
  locale = "zh-CN",
  numberFormat,
  motion = "auto",
  trend,
  trendDirection = "up",
  subtitle,
  theme = "white",
  size = "sm",
  icon,
  badgeVariant,
  action,
  onKebabClick,
  density = "default",
  width,
  className,
}: {
  title: string;
  value: ReactNode;
  /** Roll numeric values when they change. Strings and custom content stay unchanged. */
  animateValue?: boolean;
  /** Locale for numeric values when animation or numberFormat is enabled. */
  locale?: string;
  numberFormat?: Intl.NumberFormatOptions;
  motion?: MotionPreference;
  trend?: string;
  trendDirection?: TrendDirection;
  subtitle?: string;
  theme?: StatCardTheme;
  size?: StatCardSize;
  icon?: ReactNode;
  /** Badge style for the icon chip. Defaults to the theme's iconChipBg in
   * sm/lg, and to "opacity" (themed 10% bg + colored icon) in wide. */
  badgeVariant?: CardBadgeVariant;
  /** Custom action slot (e.g. button). Takes priority over onKebabClick. */
  action?: ReactNode;
  /** If set, renders the built-in kebab-menu button. */
  onKebabClick?: () => void;
  /** Use compact inside dense dashboards while preserving the default Figma showcase scale. */
  density?: CardDensity;
  /** Use full to fill dashboard/grid columns. Use fixed only for Figma-size showcases. */
  width?: CardWidth;
  className?: string;
}) {
  const themeKey = resolveCardTheme(theme);
  const cfg = cardThemes[themeKey];
  const sz = statCardSizes[size];
  const isWide = size === "wide";
  const isCompact = density === "compact";
  const iconSize = size === "lg" ? 48 : 40;
  const renderedValue = typeof value === "number" && (animateValue || numberFormat)
    ? <AnimatedNumber value={value} locale={locale} formatOptions={numberFormat} motion={animateValue ? motion : "none"} />
    : value;

  const actionNode = action ?? (onKebabClick ? <CardKebabButton theme={cfg} onClick={onKebabClick} /> : null);

  return (
    <div
      className={cn(
        "rounded-card flex-col justify-start items-start overflow-hidden relative",
        isCompact ? "gap-3 p-4" : cn("gap-4", sz.wrapper),
        resolveCardWidthClass(isWide ? "full" : width, sz.fixedWidth),
        cfg.bg,
        className,
      )}
    >
      <CardGlow theme={cfg} />

      {isWide ? (
        <>
          <div className="self-stretch inline-flex justify-between items-center gap-2 relative z-10">
            <span className={cn("flex-1 text-sm font-medium leading-5 tracking-fg truncate", cfg.titleColor)}>
              {title}
            </span>
            {icon ? (
              <CardIconChip
                icon={icon}
                theme={cfg}
                themeKey={themeKey}
                variant={badgeVariant ?? "opacity"}
                size={iconSize}
              />
            ) : actionNode ? (
              <div className="shrink-0">{actionNode}</div>
            ) : null}
          </div>
          <div className={cn("self-stretch font-semibold tracking-fg relative z-10", isCompact ? "text-2xl leading-8" : sz.value, cfg.valueColor)}>
            {renderedValue}
          </div>
        </>
      ) : (
        <div className="self-stretch inline-flex justify-start items-start gap-2 relative z-10">
          <div className={cn("flex-1 inline-flex flex-col justify-start items-start min-w-0", "gap-4")}>
            <div className="self-stretch inline-flex justify-start items-center gap-2">
              {icon && <CardIconChip icon={icon} theme={cfg} themeKey={themeKey} variant={badgeVariant} size={iconSize} />}
              <span className={cn("flex-1 text-sm font-medium leading-5 tracking-fg truncate", cfg.titleColor)}>
                {title}
              </span>
            </div>
            <div className={cn("self-stretch font-semibold tracking-fg", isCompact && size !== "lg" ? "text-2xl leading-8" : sz.value, cfg.valueColor)}>
              {renderedValue}
            </div>
          </div>
          {actionNode && <div className="shrink-0">{actionNode}</div>}
        </div>
      )}

      <CardTrend trend={trend} direction={trendDirection} subtitle={subtitle} theme={cfg} />
    </div>
  );
}

