// ── Trend indicator (used in StatCard & variants) ────────────

export type TrendDirection = "up" | "down";

export function CardTrend({
  trend,
  direction = "up",
  subtitle,
  theme,
}: {
  trend?: string;
  direction?: TrendDirection;
  subtitle?: string;
  theme: CardThemeConfig;
