  badge,
  columns,
  rows,
  headerActions,
  color = "black",
  showCheckbox = false,
  checkboxColor = "black",
  selectedRowKeys,
  onSelectedRowKeysChange,
  selectedRows,
  onSelectRow,
  onSelectAll,
  onSort,
  sortColumnKey,
  sortDirection,
  getRowKey,
  emptyState = "暂无数据",
  footerLeft,
  footerRight,
