"use client";
import NextLink from "next/link";
import { type ReactNode } from "react";
import { useActionEffect } from "../../internal/action-effect";
import type { MotionPreference } from "../../lib/motion";

// ============================================================
// StyledLink - 文字链接
// color: purple, dark, blue, green, red, orange, yellow, cyan, gray
// state: default, disabled
// icon: left, right, none
// ============================================================

// Figma: 每个基色在 hover 下切到深色 token（violet-800 / blue-800 / ...），
// disabled 用 stone-500（fg-grey-700）。这里把 base + hover 拆成两类。
const linkColors = {
  purple: "text-fg-violet hover:text-fg-violet-800",
  dark: "text-fg-violet-800 hover:text-fg-violet-900",
  blue: "text-fg-blue hover:text-fg-blue-800",
  green: "text-fg-green-500 hover:text-fg-green-700",
  red: "text-fg-red hover:text-fg-red-800",
  orange: "text-fg-yellow-900 hover:text-fg-yellow-800",
  yellow: "text-fg-yellow-900 hover:text-fg-yellow-800",
  cyan: "text-fg-cyan-500 hover:text-fg-cyan-600",
  gray: "text-fg-grey-900 hover:text-fg-black",
} as const;

export type LinkColor = keyof typeof linkColors;

export function StyledLink({
  children,
  href,
  color = "blue",
  disabled = false,
  iconLeft,
  iconRight,
  className = "",
  effect, motion = "auto",
}: {
  children: ReactNode;
  href: string;
  color?: LinkColor;
  disabled?: boolean;
  iconLeft?: ReactNode;
  iconRight?: ReactNode;
  className?: string;
  effect?: "magnetic" | "roll";
  motion?: MotionPreference;
}) {
  const effects = useActionEffect(effect, motion, disabled);
  if (disabled) {
    return (
      <span
        className={`inline-flex items-start gap-1 opacity-60 ${linkColors[color]} text-sm font-bold leading-5 tracking-fg ${className}`}
      >
        {iconLeft && <span className="w-5 h-5 flex items-center justify-center">{iconLeft}</span>}
        <span>{children}</span>
        {iconRight && <span className="w-5 h-5 flex items-center justify-center">{iconRight}</span>}
      </span>
    );
  }

  return (
    <NextLink
      href={href}
      data-effect={effect} data-motion={motion}
      onPointerMove={effects.move} onPointerLeave={effects.leave}
      className={`forge-styled-link inline-flex items-start gap-1 ${linkColors[color]} text-sm font-bold leading-5 tracking-fg hover:underline ${className}`}
    >
      {iconLeft && <span className="w-5 h-5 flex items-center justify-center">{iconLeft}</span>}
      <span className="forge-action-label">{effect === "roll" && typeof children === "string" ? <><span className="sr-only">{children}</span>{Array.from(children).map((letter, index) => <span aria-hidden="true" className="forge-roll-letter" key={index} data-letter={letter} style={{ transitionDelay: `${index * 18}ms` }}>{letter === " " ? "\u00a0" : letter}</span>)}</> : children}</span>
      {iconRight && <span className="w-5 h-5 flex items-center justify-center">{iconRight}</span>}
    </NextLink>
  );
}

"use client";
import { type ReactNode, type HTMLAttributes } from "react";
import { cn } from "../../lib/utils";
import { useReducedMotion } from "../../internal/motion";
import type { MotionPreference } from "../../lib/motion";

export type SurfaceCardPadding = "none" | "sm" | "md" | "lg";

const paddingClasses: Record<SurfaceCardPadding, string> = {
  none: "p-0",
  sm: "p-4",
  md: "p-5",
  lg: "p-6",
};

export function SurfaceCard({
  title,
  subtitle,
  action,
  children,
  footer,
  padding = "md",
  className,
  headerClassName,
  contentClassName,
  footerClassName,
  effect, motion = "auto", ...props
}: {
  title?: ReactNode;
  subtitle?: ReactNode;
  action?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  padding?: SurfaceCardPadding;
  className?: string;
  headerClassName?: string;
  contentClassName?: string;
  footerClassName?: string;
  effect?: "tilt" | "layered";
  motion?: MotionPreference;
} & Omit<HTMLAttributes<HTMLElement>, "title">) {
  const hasHeader = title || subtitle || action;
  const reduced = useReducedMotion(motion);

  return (
    <section
      {...props}
      data-effect={effect}
      data-motion={motion}
      onPointerMove={(event) => {
        props.onPointerMove?.(event);
        if (!effect || reduced || event.pointerType === "touch") return;
        const rect = event.currentTarget.getBoundingClientRect();
        const x = (event.clientX - rect.left) / Math.max(1, rect.width) - .5;
        const y = (event.clientY - rect.top) / Math.max(1, rect.height) - .5;
        event.currentTarget.style.setProperty("--forge-tilt-x", `${-y * 8}deg`);
        event.currentTarget.style.setProperty("--forge-tilt-y", `${x * 8}deg`);
        event.currentTarget.style.setProperty("--forge-pointer-x", `${(x + .5) * 100}%`);
        event.currentTarget.style.setProperty("--forge-pointer-y", `${(y + .5) * 100}%`);
      }}
      onPointerLeave={(event) => {
        props.onPointerLeave?.(event);
        event.currentTarget.style.setProperty("--forge-tilt-x", "0deg");
        event.currentTarget.style.setProperty("--forge-tilt-y", "0deg");
      }}
      className={cn(
        "forge-surface-card rounded-card bg-white outline outline-1 outline-offset-[-1px] outline-fg-grey-200",
        className
      )}
    >
      {hasHeader && (
        <div
          className={cn(
            "flex items-start justify-between gap-4 border-b border-fg-grey-200 px-5 py-4",
            headerClassName
          )}
        >
          <div className="min-w-0">
            {title && (
              <h2 className="text-sm font-semibold leading-5 tracking-fg text-fg-black">
                {title}
              </h2>
            )}
            {subtitle && (
              <p className="mt-1 text-xs font-medium leading-4.5 tracking-fg text-fg-grey-700">
                {subtitle}
              </p>
            )}
          </div>
          {action && <div className="shrink-0">{action}</div>}
        </div>
      )}

      <div className={cn(paddingClasses[padding], contentClassName)}>
        {children}
      </div>

      {footer && (
        <div className={cn("border-t border-fg-grey-200 px-5 py-4", footerClassName)}>
          {footer}
        </div>
      )}
    </section>
  );
}

