  { checkbox: true, color: "blue", sort: false, label: "blue" },
  { checkbox: true, color: "black", sort: true, label: "black + sort" },
  { checkbox: true, color: "black", sort: false, label: "black" },
];

const headerRows: HeaderRow[] = [
