        if (drag.current?.pointerId !== event.pointerId) return;
        skipClick.current = true;
        cancelDrag();
      }}
      onLostPointerCapture={event => {
        if (drag.current?.pointerId !== event.pointerId) return;
        skipClick.current = true;
        cancelDrag();
      }}
      onKeyDown={event => {
        if (event.key === "Escape") { skipClick.current = true; cancelDrag(); }
