export type ToggleProps = {
  checked?: boolean;
  /** Initial value when checked is not supplied. */
  defaultChecked?: boolean;
  motion?: MotionPreference;
  onChange?: (checked: boolean) => void;
  color?: ControlColor;
  disabled?: boolean;
  size?: "sm" | "md";
  ariaLabel?: string;
  /** Allow dragging the thumb; clicking and keyboard activation remain available. */
  draggable?: boolean;
  thumbIcon?: ReactNode;
};

type ToggleDrag = {
  pointerId: number;
  startX: number;
  scale: number;
  travel: number;
  startChecked: boolean;
  moved: boolean;
  offset: number;
};

export function Toggle({
  checked,
  defaultChecked = false,
  motion = "auto",
  onChange,
  color = "blue",
  disabled = false,
  size = "md",
  ariaLabel = "开关",
  draggable = false,
  thumbIcon,
