        ))}
      </Section>

      {/* ============ Additional Toolbar combos ============ */}
      <Section
        title="Toolbar Layout - Other Combos"
        description="左侧 pill tabs + 搜索，右侧 favorite / kebab / primary。"
      >
        <SubSection title="With favorite + kebab (purple)" stack>
          <Toolbar
            left={
              <div className="flex items-center gap-3">
