"use client";

import { useState } from "react";
import {
  ThinkingTrace,
  StreamingAnswer,
  ApprovalCard,
  ToolChips,
  AgentTaskRows,
  ChatInputBar,
  ContextCards,
  RecommendationCard,
  AgentDiffTable,
  AgentCodeBlock,
  InsightCards,
  CommandSearch,
  AgentFlowchart,
} from "@forge-ui-official/core";
import { PageHeading, Section, SubSection } from "../_shared";
import { StreamingAnswerDemo } from "./_streaming-demo";

const TASKS = [
  {
    id: "1",
