    ],
  },
  {
    id: "2",
    title: "生成补货任务清单",
    status: "running" as const,
    meta: "7 种商品",
    children: [
      { label: "读取收银导出数据", value: "3 个文件", status: "running" as const },
      { label: "评估缺货风险", value: "68%" },
    ],
  },
