                },
              ]}
            />
            {insightPrompt && <p role="status" className="mt-3 text-sm text-fg-grey-700">已生成追问草稿：{insightPrompt}</p>}
          </div>
        </SubSection>
      </Section>

      <Section title="CommandSearch" description="输入过滤命令。">
