        state === "active"
          ? "bg-fg-grey-200 text-fg-grey-700"
          : "text-fg-grey-500 hover:bg-fg-grey-200 hover:text-fg-grey-700",
        className
      )}
    >
      <span className="w-3.5 h-3.5 flex items-center justify-center">{icon}</span>
    </button>
  );
