export interface WalletGoalCardProps {
  title: string;
  date: string;
  amount: string;
  progress: number;
  progressColor: "purple" | "green" | "blue" | "red" | "orange" | "yellow" | "cyan";
  showActions?: boolean;
  onEdit?: () => void;
  onTopUp?: () => void;
  onWithdraw?: () => void;
  topUpLabel?: string;
  withdrawLabel?: string;
  editLabel?: string;
  iconBg?: string;
  icon?: ReactNode;
}

export function WalletGoalCard({
  title,
  date,
  amount,
  progress,
  progressColor,
  showActions = false,
  onEdit,
  onTopUp,
  onWithdraw,
  topUpLabel = "Top Up",
  withdrawLabel = "Withdraw",
  editLabel = "Edit",
  iconBg = "var(--fg-violet-50)",
  icon,
}: WalletGoalCardProps) {
  return (
    <div className="rounded-2xl border border-fg-grey-200 p-4 flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
