export default function CustomersPage() {
  const router = useRouter();
  const [page, setPage] = useState(1);
  const [selectedRows, setSelectedRows] = useState<Set<number>>(new Set());
  const [customerList, setCustomerList] =
    useState<CustomerItem[]>(initialCustomerList);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editTarget, setEditTarget] = useState<CustomerItem | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<CustomerItem | null>(null);
  const [uploadedProfileImageUrl, setUploadedProfileImageUrl] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [addCustomerFormValue, setAddCustomerFormValue] =
    useState<AddCustomerFormValue>({
      name: "",
      email: "",
      phone: "",
      address: "",
    });
  const [editCustomerFormValue, setEditCustomerFormValue] =
    useState<AddCustomerFormValue>({
      name: "",
      email: "",
      phone: "",
      address: "",
    });

  const updateFormField = useCallback(
    (field: keyof AddCustomerFormValue, value: string) => {
      setAddCustomerFormValue((prev) => ({ ...prev, [field]: value }));
    },
    []
  );

  const handleOpenDeleteModal = useCallback((record: CustomerItem) => {
    setDeleteTarget(record);
    setIsDeleteModalOpen(true);
  }, []);

  const handleCloseDeleteModal = useCallback(() => {
    setDeleteTarget(null);
    setIsDeleteModalOpen(false);
  }, []);

  const handleDeleteCustomer = useCallback((customerId: string) => {
    setCustomerList((prev) => prev.filter((item) => item.id !== customerId));
  }, []);

  const handleCloseAddModal = useCallback(() => {
    setIsAddModalOpen(false);
    if (uploadedProfileImageUrl) {
      URL.revokeObjectURL(uploadedProfileImageUrl);
    }
    setUploadedProfileImageUrl("");
    setAddCustomerFormValue({ name: "", email: "", phone: "", address: "" });
  }, [uploadedProfileImageUrl]);

  const handleSubmitAddCustomer = useCallback(() => {
    handleCloseAddModal();
  }, [handleCloseAddModal]);

  const handleOpenEditModal = useCallback((record: CustomerItem) => {
    setEditTarget(record);
    setEditCustomerFormValue({
      name: record.name,
      email: record.email,
      phone: record.phone,
      address: "1833 Bel Meadow Drive, Fontana, California 92335, USA",
    });
  }, []);

  const handleCloseEditModal = useCallback(() => {
    setEditTarget(null);
  }, []);

  const updateEditFormField = useCallback(
    (field: keyof AddCustomerFormValue, value: string) => {
      setEditCustomerFormValue((prev) => ({ ...prev, [field]: value }));
    },
    []
  );

  const handleSubmitEditCustomer = useCallback(() => {
    if (!editTarget) return;
    setCustomerList((prev) =>
      prev.map((item) =>
        item.id === editTarget.id
          ? {
              ...item,
              name: editCustomerFormValue.name,
              email: editCustomerFormValue.email,
              phone: editCustomerFormValue.phone,
            }
          : item
      )
    );
    handleCloseEditModal();
  }, [editTarget, editCustomerFormValue, handleCloseEditModal]);

  const handleUploadProfileImage = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !file.type.startsWith("image/")) return;
      const objectUrl = URL.createObjectURL(file);
      setUploadedProfileImageUrl((prev) => {
        if (prev) URL.revokeObjectURL(prev);
        return objectUrl;
      });
    },
    []
  );

  const columns = useMemo<ColumnDef<CustomerItem>[]>(
    () => [
      {
        key: "name",
        header: "Customer Name",
        sortable: true,
        width: "w-60",
        render: (row) => (
          <div
            className="cursor-pointer"
            onClick={() => router.push(`/templates/ecommerce/customers/${row.id}`)}
          >
            <CellImageText
              src={row.avatarUrl}
              title={row.name}
              subtitle={row.email}
              rounded="full"
            />
          </div>
        ),
      },
      {
        key: "phone",
        header: "Phone",
        sortable: false,
        width: "w-40",
        render: (row) => <CellMuted>{row.phone}</CellMuted>,
      },
      {
        key: "orders",
        header: "Orders",
        sortable: true,
        width: "w-28",
        render: (row) => <CellText>{row.orders.toLocaleString()}</CellText>,
      },
      {
        key: "balance",
        header: "Balance",
        sortable: true,
        width: "w-28",
        render: (row) => <CellText>{row.balance}</CellText>,
      },
      {
        key: "status",
        header: "Status",
        sortable: true,
        width: "w-28",
        render: (row) => (
          <StatusBadge
            label={row.status === "online" ? "Online" : "Offline"}
            color={row.status === "online" ? "green" : "red"}
          />
        ),
      },
      {
        key: "created",
        header: "Created",
        sortable: false,
        width: "w-32",
        render: (row) => <CellMuted>{row.created}</CellMuted>,
      },
      {
        key: "actions",
        header: "",
        width: "w-36",
        render: (row) => (
          <div className="flex items-center justify-end gap-2 h-10">
            <IconButton variant="ghost" shape="square" size="sm">
              <LetterLinear size={16} />
            </IconButton>
            <IconButton variant="ghost" shape="square" size="sm">
              <PhoneCallingLinear size={16} />
            </IconButton>
            <IconButton variant="ghost" shape="square" size="sm">
              <ChatRoundLinear size={16} />
            </IconButton>
            <IconButton
              variant="ghost"
              shape="square"
              size="sm"
              onClick={() => handleOpenEditModal(row)}
            >
              <PenLinear size={16} />
            </IconButton>
            <IconButton
              variant="ghost"
              shape="square"
              size="sm"
              onClick={() => handleOpenDeleteModal(row)}
            >
              <TrashBinMinimalisticLinear size={16} />
            </IconButton>
          </div>
        ),
      },
    ],
    [handleOpenDeleteModal, handleOpenEditModal, router]
  );

  const totalPages = Math.ceil(100 / 10);

  return (
    <div className="space-y-6">
      {/* Delete Confirmation Modal */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30">
          <ConfirmationDialog
            title="Delete Customer?"
            description="Do you want to delete this customer? This action can't be undone"
            color="red"
            icon={<TrashBinMinimalisticLinear size={32} color={"var(--fg-red-600)"} />}
            confirmLabel="Delete"
            cancelLabel="Cancel"
            onCancel={handleCloseDeleteModal}
            onConfirm={() => {
              if (!deleteTarget) return;
              handleDeleteCustomer(deleteTarget.id);
              handleCloseDeleteModal();
            }}
          />
        </div>
      )}

      {/* Add Customer Modal */}
      <Modal
        open={isAddModalOpen}
        onClose={handleCloseAddModal}
        title="Add Customer"
        width="w-[640px]"
      >
        <div className="px-6 py-6">
          <div className="space-y-4">
            <div>
              <p className="mb-1 text-sm font-medium text-fg-grey-700">
                Profile Image
              </p>
              <div className="flex items-center gap-3">
                <Avatar
                  src={uploadedProfileImageUrl || undefined}
                  initials="N"
                  size="lg"
                />
                <FileInput
                  ref={fileInputRef}

                  accept="image/*"
                  className="hidden"
                  onChange={handleUploadProfileImage}
                />
                <Button
                  variant="tertiary"
                  size="sm"
                  iconLeft={<PlusIcon size={16} />}
                  onClick={() => fileInputRef.current?.click()}
                >
                  Upload
                </Button>
              </div>
            </div>
            <TextField
              label="Name"
              placeholder="Type name here..."
              value={addCustomerFormValue.name}
              shape="pill"
              onChange={(val) => updateFormField("name", val)}
            />
            <TextField
              label="Email"
              placeholder="Type email here..."
              value={addCustomerFormValue.email}
              shape="pill"
              onChange={(val) => updateFormField("email", val)}
            />
            <TextField
              label="Phone"
              placeholder="Type phone here..."
              value={addCustomerFormValue.phone}
              shape="pill"
              onChange={(val) => updateFormField("phone", val)}
            />
            <TextArea
              label="Address"
              placeholder="Type address here..."
              value={addCustomerFormValue.address}
              rows={4}
              onChange={(val) => updateFormField("address", val)}
            />
          </div>
        </div>
        <div className="px-6 pb-6 flex items-center justify-between">
          <Button variant="tertiary" onClick={handleCloseAddModal}>
            Cancel
          </Button>
          <Button onClick={handleSubmitAddCustomer}>Submit</Button>
        </div>
      </Modal>

      {/* Edit Customer Modal */}
      <Modal
        open={editTarget !== null}
        onClose={handleCloseEditModal}
        title="Edit Customer"
        width="w-[640px]"
      >
        <div className="px-6 py-6">
          <div className="space-y-4">
            <div>
              <p className="mb-1 text-sm font-medium text-fg-grey-700">
                Profile Image
              </p>
              <div className="flex items-center gap-3">
                <Avatar
                  src={editTarget?.avatarUrl}
                  initials={editTarget?.name?.[0] ?? "?"}
                  size="lg"
                />
                <Button
                  variant="tertiary"
                  size="sm"
                  iconLeft={<PlusIcon size={16} />}
                >
                  Upload
                </Button>
              </div>
            </div>
            <TextField
              label="Name"
              value={editCustomerFormValue.name}
              shape="pill"
              onChange={(val) => updateEditFormField("name", val)}
            />
            <TextField
              label="Email"
              value={editCustomerFormValue.email}
              shape="pill"
              onChange={(val) => updateEditFormField("email", val)}
            />
            <TextField
              label="Phone"
              value={editCustomerFormValue.phone}
              shape="pill"
              onChange={(val) => updateEditFormField("phone", val)}
            />
            <TextArea
              label="Address"
              value={editCustomerFormValue.address}
              rows={4}
              onChange={(val) => updateEditFormField("address", val)}
            />
          </div>
        </div>
        <div className="px-6 pb-6 flex items-center justify-between">
          <Button variant="tertiary" onClick={handleCloseEditModal}>
            Cancel
          </Button>
          <Button onClick={handleSubmitEditCustomer}>Save</Button>
        </div>
      </Modal>

      {/* Header */}
      <div className="flex items-start justify-between max-sm:flex-col max-sm:items-stretch max-sm:gap-3 max-sm:[&>div]:min-w-0 max-sm:[&>div]:max-w-full max-sm:[&>div]:flex-wrap">
        <div className="flex flex-col gap-1">
          <h1 className="text-display-l font-semibold text-fg-black leading-9 tracking-fg">Customers</h1>
          <Breadcrumbs
            items={[
              { label: "Dashboard", href: "/templates/ecommerce" },
              { label: "Customers" },
            ]}
          />
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant="tertiary"
            iconLeft={<DownloadMinimalisticLinear size={16} />}
          >
            Export
