          }}
          showPagination
          currentPage={page}
          totalPages={Math.ceil(filteredOrders.length / 10) || 1}
          onPageChange={setPage}
          paginationLabel={`Showing 1-${filteredOrders.length} from ${filteredOrders.length}`}
        />
