const priorityColor: Record<ActionRow["priority"], StatusBadgeColor> = {
  High: "red",
  Medium: "yellow",
  Low: "grey",
};

const statusColor: Record<ActionRow["status"], StatusBadgeColor> = {
  Open: "blue",
  "In Review": "yellow",
  Done: "green",
  Blocked: "red",
};

export default function MicellaneousActionsPage() {
