      <TemplateDeleteDialog open={modal === "delete"} title="Delete Attachment?" description="Are you sure you want to delete this attachment?" onClose={() => setModal(null)} />
    </ProjectTemplateShell>
  );
}



function Info({ label, value }: { label: string; value: string }) {
  return <div><div className="text-sm text-fg-grey-500">{label}</div><div className="mt-0.5 text-fg-black">{value}</div></div>;
}

function Metric({ title, value, progress, color = "purple" }: { title: string; value: string; progress: number; color?: "purple" | "red" }) {
  return <ProjectSection className={projectPanelClass} title={title}><CellMuted>2 Jul - Today</CellMuted><div className="text-3xl font-semibold text-fg-black">{value}</div><ProgressBar value={progress} color={color} /><div className="flex justify-between text-sm"><span className="font-semibold text-fg-green-500">10%</span><span className="text-fg-grey-500">+150 today</span></div></ProjectSection>;
}

function ActivityList() {
  return <div className="relative flex flex-col gap-5 border-l border-dashed border-fg-grey-300 pl-5">{activityItems.map((item) => <div key={item.title} className="relative"><span className="absolute -left-[27px] top-1 size-3 rounded-full border-2 border-fg-violet-100 bg-fg-violet" /><div className="flex justify-between"><h4 className="font-semibold text-fg-black">{item.title}</h4><span className="text-sm text-fg-grey-500">{item.time}</span></div><p className="mt-1 text-sm text-fg-grey-700"><span className="font-semibold text-fg-violet">Jay Parker</span> {item.body.replace("Jay Parker ", "")}</p></div>)}</div>;
}

const boardGroups = [
  { title: "To Do", tone: "grey", tasks: tasks.filter((_, index) => index % 4 === 0 || index === 2) },
  { title: "In Progress", tone: "yellow", tasks: tasks.filter((_, index) => index % 4 === 1 || index === 0) },
  { title: "Done", tone: "green", tasks: tasks.filter((task) => task.progress === 100) },
  { title: "Blocked", tone: "red", tasks: tasks.filter((task) => task.priority === "High") },
] as const;

function KanbanBoard({ onOpenTask, onAddTask, compact = false }: { onOpenTask: (task: Task) => void; onAddTask: () => void; compact?: boolean }) {
  return (
    <div className={`grid gap-4 ${compact ? "grid-cols-2" : "grid-cols-4"}`}>
      {boardGroups.map((group) => (
        <section key={group.title} className="flex flex-col gap-3">
          <div className="flex items-center justify-between">
            <h3 className="font-semibold text-fg-black">{group.title} ({group.tasks.length})</h3>
            <Button variant="tertiary" onClick={onAddTask}><AddCircleLinear size={18} /></Button>
          </div>
          {group.tasks.map((task) => <TaskBoardCard key={`${group.title}-${task.id}`} task={task} tone={group.tone} onOpen={() => onOpenTask(task)} />)}
        </section>
      ))}
    </div>
  );
}

function TaskBoardCard({ task, tone, onOpen }: { task: Task; tone: "grey" | "yellow" | "green" | "red"; onOpen: () => void }) {
  const progressColor = task.progress === 100 ? "green" : task.priority === "High" ? "red" : "yellow";
  return (
    <CorePanel variant="custom" as="article" className="rounded-[20px] border border-fg-grey-200 bg-white p-4">
      <div className="flex items-start justify-between">
        <StatusBadge label={task.priority} color={task.priority === "High" ? "red" : task.priority === "Medium" ? "yellow" : "green"} />
        <CellActions actions={["pen"]} />
      </div>
      <Button variant="unstyled" type="button" className="mt-3 text-left" onClick={onOpen}>
        <h4 className="text-lg font-semibold text-fg-black">{task.name.replace("...", "")}</h4>
        <p className="mt-1 text-sm leading-5 text-fg-grey-500">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Praesent vel hendrerit ipsum.</p>
      </Button>
      <div className="mt-3">
        <div className="mb-2 flex items-center justify-between text-sm">
          <span className="text-fg-grey-500">Progress</span>
          <span className={`font-semibold ${tone === "red" ? "text-fg-red" : tone === "green" ? "text-fg-green-500" : "text-fg-yellow"}`}>{task.progress === 45 ? "Blocked" : `${task.progress}%`}</span>
        </div>
        <ProgressBar value={task.progress || 8} color={progressColor} />
      </div>
      <div className="mt-3 flex items-center justify-between">
        <AvatarGroup overflowCount={task.memberOverflow}>{task.members.slice(0, 3).map((src, index) => <Avatar key={index} src={src} size="sm" />)}</AvatarGroup>
        <span className="text-sm text-fg-grey-500">{task.dueDate}</span>
      </div>
    </CorePanel>
  );
}

const attachmentRows = [
  ...fileItems,
  { name: "Project Presentation.ppt", size: "100 KB", type: "ppt" },
  { name: "Photo Material.zip", size: "100 KB", type: "zip" },
  { name: "Brainstorming.pdf", size: "100 KB", type: "pdf" },
  { name: "Marketing Material.ppt", size: "100 KB", type: "ppt" },
  { name: "Pitching Template.ppt", size: "100 KB", type: "ppt" },
  { name: "New Logo.fig", size: "100 KB", type: "fig" },
  { name: "Project Alpha.pdf", size: "100 KB", type: "pdf" },
  { name: "Promo Banner.ppt", size: "100 KB", type: "ppt" },
];

function AttachmentTile({ file, onDelete }: { file: { name: string; size: string }; onDelete: () => void }) {
  return (
    <CorePanel variant="custom" className="flex items-center justify-between rounded-2xl border border-fg-grey-200 bg-white p-4">
      <div className="flex items-center gap-3">
        <FileTypeIcon fileName={file.name} />
        <div>
          <div className="font-semibold text-fg-black">{file.name}</div>
          <div className="text-sm text-fg-grey-500">{file.size}</div>
        </div>
      </div>
      <CellActions actions={["trash"]} onAction={onDelete} />
    </CorePanel>
  );
}

function TeamDrawer({ onAddMember }: { onAddMember: () => void }) {
  return (
    <CorePanel variant="custom" as="aside" className={projectPanelClass}>
      <div className="mb-4 flex items-center justify-between">
        <h3 className="text-lg font-semibold text-fg-black">Members</h3>
        <Button variant="tertiary" onClick={onAddMember}><AddCircleLinear size={18} /></Button>
      </div>
      <div className="flex flex-col gap-4">
        {members.map((member) => (
          <div key={member.id} className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Avatar src={member.avatar} size="sm" />
              <div>
                <div className="font-semibold text-fg-black">{member.name}</div>
                <div className="text-sm text-fg-grey-500">{member.role}</div>
              </div>
            </div>
            <CellActions actions={["chat", "mail"]} />
          </div>
        ))}
      </div>
      <Button className="mt-5 w-full" iconLeft={<UserPlusLinear size={18} />} onClick={onAddMember}>Add Member</Button>
    </CorePanel>
  );
}

"use client";

import { Panel } from "@forge-ui-official/core";
import { ProjectSection } from "@/app/templates/_shared/project-section";
import { useMemo, useState } from "react";
import { useParams } from "next/navigation";
import { AddCircleLinear, Pen2Linear, UserPlusLinear } from "@forge-ui-official/core/icons";
import { Avatar, AvatarGroup, Button, Checkbox, FileCard, ProgressBar, StatusBadge } from "@forge-ui-official/core";
import { PageTop, ProjectTemplateShell } from "../../_chrome";
import { activityItems, fileItems, tasks } from "../../_data";
import { projectPageStackClass, projectPanelClass } from "../../_density";
import { TemplateDeleteDialog, TemplateFormModal } from "../../_modals";
import { ProjectLogo } from "../../_logos";

export default function TaskDetailPage() {
  const params = useParams<{ id: string }>();
  const task = useMemo(() => tasks.find((item) => item.id === params.id) ?? tasks[0], [params.id]);
  const [modal, setModal] = useState<"edit" | "member" | "delete" | null>(null);

  return (
    <ProjectTemplateShell>
      <div className={projectPageStackClass}>
        <PageTop
          title="Task Details"
          parent="Overview / Project"
          current="Task Details"
          actions={<div className="flex gap-4"><Button variant="tertiary" iconLeft={<UserPlusLinear size={18} />} onClick={() => setModal("member")}>Add Member</Button><Button iconLeft={<Pen2Linear size={18} />} onClick={() => setModal("edit")}>Edit</Button></div>}
        />

        <section className="grid grid-cols-1 gap-4 xl:grid-cols-[320px_minmax(0,1fr)]">
          <aside className="flex flex-col gap-4">
            <ProjectSection className={projectPanelClass} title="General Information">
              <div className="flex items-center gap-3"><ProjectLogo name={task.logo} /><div><h2 className="text-lg font-semibold text-fg-black">{task.name}</h2><p className="text-sm text-fg-grey-500">{task.client}</p></div></div>
              <Info label="Status" value={task.status} />
              <Info label="Due Date" value={task.dueDate} />
              <Info label="Priority" value={task.priority} />
            </ProjectSection>
            <ProjectSection className={projectPanelClass} title="Members" action={<Button variant="tertiary" onClick={() => setModal("member")}><AddCircleLinear size={18} /></Button>}>
              <AvatarGroup overflowCount={task.memberOverflow}>{task.members.map((src, index) => <Avatar key={index} src={src} size="md" />)}</AvatarGroup>
            </ProjectSection>
            <ProjectSection className={projectPanelClass} title="Attachment" action={<Button variant="tertiary"><AddCircleLinear size={18} /></Button>}>
              {fileItems.slice(0, 2).map((file) => <FileCard key={file.name} file={{ id: file.name, name: file.name, size: file.size, state: "uploaded" }} />)}
            </ProjectSection>
          </aside>
          <main className="flex flex-col gap-4">
            <ProjectSection className={projectPanelClass} title="Progress">
              <div className="text-4xl font-semibold text-fg-black">{task.progress}%</div>
              <ProgressBar value={task.progress} color={task.progress === 100 ? "green" : task.priority === "High" ? "red" : "yellow"} />
              <div className="flex gap-3"><StatusBadge label={task.priority} color={task.priority === "High" ? "red" : task.priority === "Medium" ? "yellow" : "green"} /><StatusBadge label={task.status} color={task.status === "Finished" ? "green" : task.status === "Not Started" ? "grey" : "yellow"} /></div>
            </ProjectSection>
            <ProjectSection className={projectPanelClass} title="Description"><p className="leading-6 text-fg-grey-700">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Quisque nisl dui, fringilla ac venenatis ut, varius at arcu.</p></ProjectSection>
            <ProjectSection className={projectPanelClass} title="Checklist" action={<Button variant="tertiary"><AddCircleLinear size={18} /></Button>}>
              {["Wireframe", "Moodboard", "Prototype"].map((item, index) => <Panel variant="custom" key={item} className="flex items-center justify-between rounded-2xl border border-fg-grey-200 p-4"><span className="text-fg-black">{item}</span><Checkbox color="purple" checked={index === 0} /></Panel>)}
            </ProjectSection>
            <ProjectSection className={projectPanelClass} title="Activity">
              {activityItems.map((item) => <div key={item.title} className="border-b border-fg-grey-200 py-3"><h3 className="font-semibold text-fg-black">{item.title}</h3><p className="text-sm text-fg-grey-700">{item.body}</p></div>)}
            </ProjectSection>
          </main>
        </section>
      </div>

      <TemplateFormModal
        open={modal === "edit" || modal === "member"}
        title={modal === "member" ? "Add Member" : "Edit Task"}
        fields={[
          { label: "Task Name", placeholder: "Task Name", value: modal === "edit" ? task.name : undefined },
          { label: "Priority", placeholder: "Priority", value: modal === "edit" ? task.priority : undefined },
          { label: "Due Date", placeholder: "21 Oct 2022", value: modal === "edit" ? task.dueDate : undefined },
          { label: "Member", placeholder: "Select member" },
        ]}
        onClose={() => setModal(null)}
      />
      <TemplateDeleteDialog open={modal === "delete"} title="Delete Task?" description="Are you sure you want to delete this task?" onClose={() => setModal(null)} />
    </ProjectTemplateShell>
  );
}



function Info({ label, value }: { label: string; value: string }) {
  return <div><div className="text-sm text-fg-grey-500">{label}</div><div className="text-fg-black">{value}</div></div>;
}

"use client";
import { useState } from "react";
import { Button, Checkbox, Grid, SurfaceCard, TextField } from "@forge-ui-official/core";
import { FolderBoldDuotone } from "@forge-ui-official/core/icons";
import { useWorkspace } from "../_workspace-context";
import { CreateButton, EmptyModule, ModulePage } from "../_workspace-ui";
import { taskIsArchived } from "../_data";
export default function ProjectsPage(){
 const {board,openProject,createProject}=useWorkspace();const [query,setQuery]=useState("");const [archived,setArchived]=useState(false);
 const projects=board.projects.filter(name=>Boolean(board.archived?.includes(name))===archived&&name.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
 return <ModulePage title="项目" description="按目标组织工作，任务、上下文与交付都留在项目中。" action={<CreateButton onClick={createProject}>新建项目</CreateButton>}><div className="workspace-collection-toolbar"><TextField color="blue" aria-label="搜索项目" placeholder="搜索项目" value={query} onChange={setQuery}/><label className="flex items-center gap-2 text-sm text-fg-grey-700"><Checkbox color="blue" aria-label="已归档项目" checked={archived} onChange={setArchived}/>已归档项目</label></div><Grid columns={{base:1,md:2,xl:3}} gap={16}>{projects.map(name=>{const tasks=board.tasks.filter(task=>task.project===name&&(!taskIsArchived(board,task)||archived));const done=tasks.filter(task=>task.done).length;return <SurfaceCard key={name} padding="md" className="workspace-project-card"><div className="flex items-center gap-3"><FolderBoldDuotone size={24}/><Button variant="unstyled" type="button" className="workspace-row-title" onClick={()=>openProject(name)}>{name}</Button></div><p>{board.projectDetails?.[name]?.description||"任务与交付的共同工作区"}</p><div className="workspace-project-card-footer"><span>{tasks.length-done} 项待办 · {done} 项完成</span><Button color="blue" variant="tertiary" size="sm" onClick={()=>openProject(name)}>打开项目 →</Button></div></SurfaceCard>})}</Grid>{!projects.length&&<EmptyModule title={query?"没有匹配的项目":archived?"还没有已归档项目":"还没有项目"} description="项目会保存在当前工作空间。" action={!archived?<CreateButton onClick={createProject}>新建项目</CreateButton>:undefined}/>}</ModulePage>;
}

"use client";
import { useParams } from "next/navigation";
import { useWorkspace, WORKSPACE_BASE } from "../../_workspace-context";
import { EmptyModule, ModulePage } from "../../_workspace-ui";
import { Button } from "@forge-ui-official/core";
export default function ProjectPage() {
 const params=useParams<{project:string}>(); let project=params.project; try {project=decodeURIComponent(project);}catch{} const {board,ready,taskView,navigate}=useWorkspace();
 if(ready&&!board.projects.includes(project))return <ModulePage title="项目不存在"><EmptyModule title="这个空间中没有该项目" description="项目可能已重命名或删除，也可能属于另一个工作空间。" action={<Button color="blue" onClick={()=>navigate(`${WORKSPACE_BASE}/projects`)}>返回项目</Button>}/></ModulePage>;
 return taskView;
}

"use client";
import { useWorkspace } from "../_workspace-context";
export default function TasksPage() { return useWorkspace().taskView; }

